# scripts/hi_translations.py
# Hindi translations authored for the English content remaining in the Hindi
# database (`verses.translation_text`, `quotes.quote_text`). Keyed by id and
# applied by hi_data_fixes.py. VERSE_HI is keyed by verses.id, QUOTE_HI by
# quotes.id (quote-only texts that do not duplicate a verse translation).

VERSE_HI = {
    12: "दक्ष नामक तोता, जो श्रीकृष्ण की लीलाओं का वर्णन करने में निपुण तथा असंख्य अन्य तोतों का गुरु था, पुष्प-कुंज में प्रवेश करके आनन्द से अपने पंख फैलाकर बोला—'देखो कृष्ण! सूर्य उदय हो चुका है। चक्रवाकी पूर्व दिशा के रक्ताभ आकाश की ओर, और फिर अपने दूरस्थ प्रियतम की ओर उत्सुकता से देख रही है। कौओं के भय से उल्लू चुपचाप वृक्षों के कोटरों में घुस गए हैं। कृपया आप तुरंत अपनी निद्रा त्याग दें।'",
    15: "सूक्ष्मधी नाम की तोती, जिसने वृन्दादेवी से सीखी हुई सम्पूर्ण सेवा-विद्या को अपने गले में मोती की माला की भाँति धारण कर रखा था, प्रेम-मदिरा पान करने से मतवाली हो उठी थी। वह राधा को जगाने के लिए बोली।",
    18: "हे सुदति! (सुंदर दाँतोंवाली) सफेद कुमुदनी के कोरों में लीला करते हुए मत्त भौंरों का एक दल उमड़कर प्रस्फुटित कमल-समूह की ओर बढ़ता है, मानो प्रणय-अभिसार के लिए जा रहा हो। समय की ऐसी बेला में भौंरों ने कुमुदिनियों से रुचि खो दी है और कमल-पुष्पों पर मुग्ध हो गए हैं।",
    22: "राधा-माधव के चरण-नूपुर, कंगन और अन्य आभूषण मधुर झंकार कर रहे थे तथा उनके अंग प्रेम से जगमगा रहे थे। बिखरी हुई अलकों से घिरे उनके मुखमंडल, हार तथा कुण्डलों की छटा से आलोकित हो रहे थे।",
    25: "राधा ने अपनी सुंदर साड़ी का पल्ला दाहिने हाथ में लेकर अपने सुंदर दाँतों के प्रकाश से नहाए हुए कमल-मुख को ढक लिया। फिर कंधे थोड़े उठाकर जमुहाई लेते हुए राधा ने बाएँ हाथ की अँगुलियाँ चटकाकर और चूड़ियाँ बजाकर एक मधुर राग गुनगुनाया। राधा ने शरीर मर्दन किया तथा अपने सुडौल कटि-प्रदेश को बेचैन होकर हिलाया। हाथ जोड़कर राधा ने उन्हें सिर के ऊपर उठाया। इस प्रकार राधिका का सुंदर मुख परिधिमण्डल में चंद्रमा के समान चमक रहा था।",
    42: "उस युवक-युवती के शरीर से निकलती हुई सौंदर्य-किरणों के कण-कण के लिए अपने करोड़ों प्राण न्यौछावर करनेवाली सखियों की मीनाक्षी नेत्रों ने कुटिया की जालीदार खिड़की से बहते हुए शोभा-रस की धाराओं में क्रीड़ा की।\nविशाखा ने कहा—'देखो ललिते! यद्यपि राधा-माधव निरंशुक (वस्त्रहीन) हैं, तथापि वे आंशुक (अद्भुत कान्ति से आवृत) हैं। यद्यपि वे विहारी (हाररहित) हैं, तथापि राधा-माधव अपने अंगों पर प्रेम के चिह्नों के साथ अतिहारी (अत्यंत सुंदर) लग रहे हैं। यद्यपि वे अनंगद (बाजूबंदरहित) हैं, तथापि वे अंगदद (एक-दूसरे को अद्वितीय कामानन्द देनेवाले) हैं। यद्यपि वे निरंजन (अंजनरहित) हैं, तथापि वे निरंजन (एक-दूसरे को प्रसन्न करनेवाले) हैं। यद्यपि उनके होठों के राग की आसक्ति शिथिल हो चुकी थी (विस्रस्त-राग-अधरता-अभिलक्षितौ), तथापि उनका बिखरा हुआ शय्या-पट मानो प्रेम की भीषण लड़ाई की कथा कह रहा था (विप्रस्तर-गाढ़-रत-अभिलक्षितौ)।'\nललिता ने कहा—'हे सखियों! कृपया बताओ, कल रात्रि के प्रणय-युद्ध में कौन विजयी हुआ? मैं नहीं कह सकती, क्योंकि युद्ध में कृष्ण का शिखा-गुच्छ तथा राधा की वेणी दोनों शिथिल होकर आपस में उलझ गए हैं। और भी, दोनों के होठों पर दंशन के चिह्न तथा वक्षस्थल पर नख-क्षत हैं।' विशाखा ने कहा—'हे सखी! देखो! राधा अपने वक्ष पर कुंकुम लगाकर अपने हृदय के प्रेम से अच्युत के चरण-कमलों को रंग रही है! और कृष्ण अपने सिर पर लगे लाल अलक्तक के द्वारा राधिका के चरण-कमलों के प्रति अपने प्रेम की घोषणा कर रहे हैं।'\nयुगल का आनन्द देखने से सखियाँ गुप्त रूप से राधा-श्याम की लीलाओं के आश्चर्य का वर्णन कर रही थीं। अपने सौभाग्य की प्रशंसा करती हुई वे आनन्द-सागर में डूब गईं।",
    46: "राधा-माधव अपनी आनंदित और स्नेहमयी सखियों का स्वागत करते हुए मुस्कुराए। उनके सान्निध्य में राधा-माधव के सौंदर्य की कली (रूपमञ्जरी) पूर्ण रूप से खिल उठी। उस रूपमञ्जरी ने अत्यंत कुशलता से युगल की सेवा की। [दूसरा अनुवाद]: श्री रूपमञ्जरी नाम की सखी, जो राधा-माधव को रुचिपूर्वक सजाने-धजाने में निपुण है, आनंदित हो उठी।",
    56: "जटिला (राधा की सास) शब्द सुनते ही गोपियों के मुख पीले पड़ गए। अत्यधिक भय और चिंता का उदय हुआ सूर्य, जो उनके आनंद-लीला-सागर को सुखाने के लिए उदित हुआ था।",
    59: "एक सखी ने दूसरी से कहा—'देखो, सूर्योदय होने पर व्रजवासियों के जागने से पहले ही कृष्ण अपने घर लौट रहे हैं। उन्होंने मुरझाई हुई फूलों की माला फेंक दी है। प्रणय-युद्ध में कृष्ण का रत्न-हार टूट गया है। राधा के काजल-युक्त नेत्रों के चुंबन से उनके होठ काले पड़ गए हैं और उनके शरीर पर प्रेयसी के नख-चिह्न दिखाई दे रहे हैं। देखे जाने के भय से कृष्ण थकी आँखों से इधर-उधर देखते हुए मार्ग पर दौड़ रहे हैं। देखो, वे कैसे चुपचाप अपने घर में घुस रहे हैं!' स्तव-माला,",
    63: "राधा अपनी सखियों से घिरी हुई किसी को दिखाई न देकर अपने घर में प्रवेश कर गईं और शय्या पर लेट गईं। कृष्ण के विरह में तीव्र वेदना का अनुभव करते हुए राधा रोने लगीं। व्याकुल स्वर में राधा ने ललिता के सम्मुख अपना हृदय खोल दिया।",
    65: "एक सखी, जो राधा-माधव के जागरण की लीला में उपस्थित नहीं थी, दूसरी से बोली—'देखो सखी! राधिका निकुंज से लौटकर चुपचाप अपने शयन-कक्ष में प्रवेश कर गई हैं। उनके सिर का नीला वस्त्र बार-बार खिसक जाता है और वे थककर उसे ठीक करती हैं। प्रणय-लीला के कारण उनके वस्त्र और आभूषण बिखरे हुए हैं। राधा की थकी हुई आँखें इधर-उधर देख रही हैं, और वे कमजोर होकर अपनी शिथिल वेणी को फिर से गूँथने का प्रयास कर रही हैं।' स्तव-माला,",
    68: "राधा के ससुराल में सो जाने के बाद श्री रूपमञ्जरी और अन्य मञ्जरियाँ उठकर स्नान कर चंदन तथा सुगंधित लेप शरीर पर लगाने लगीं। मञ्जरियों ने अपनी स्वाभाविक शोभा बढ़ाने के लिए राधा के प्रसाद-रूप माला, वस्त्र और आभूषण धारण किए। जिन्होंने सभी निजी इच्छाओं का त्याग कर दिया था, वे मञ्जरियाँ राधा-गोविन्द की प्रेम-सेवा में लगकर मनोहर गुणों और उत्तम आचरण का प्रकाश करने लगीं।\nउनके चरणों के अग्रभाग से निकली एक भी किरण बिजली की चमक को सरलता से पराजित कर सकती थी। राधा की मञ्जरियाँ चतुरता की प्रतिमूर्ति थीं। यद्यपि प्रत्येक मञ्जरी यूथेश्वरी बनने की अधिकारिणी थी, फिर भी उनका मन कभी उस ओर नहीं गया, क्योंकि वे सदा राधा-सेवा के मधुर सागर में डूबी रहती थीं।\nवृषभानु महाराज ने अपनी पुत्री राधा के स्नेह से यावट में जटिला के निवास की उत्तरी दिशा में उनके लिए एक अद्वितीय सुंदर महल बनवाया था। राधा का वह महल प्रकाश से परिपूर्ण तथा उत्कृष्ट कला से सज्जित था। वह भव्य महल सुंदर स्तंभों, चबूतरों, छतों, झरोखों, आँगनों, अनेक प्रकार के कक्षों, द्वारों और बालकनियों से भरा हुआ था। रत्न-दीपकों से जगमगाती वह अनोखी इमारत देखनेवालों की आँखों को चकित कर देती थी।\nमहल के शिखर पर बादल जैसी श्याम चमकती इंद्रनीलमणि की कलशी थी, जो चमकते हुए रजत-हंसों के झुंड से सुशोभित थी। मोर उस कलशी को देखकर उसे अपना मित्र मेघ समझकर आनंद से पंख खोल देते थे; फिर पास जाकर सजातीय-शत्रु रजत-हंसों को देखकर तुरंत अपने मोरपंख समेट लेते थे।",
	
    73: "सहसा राधा सब कुछ भूलकर आनंद-विह्वल होकर मूर्च्छित हो गईं। चेतना लौटने पर राधिका ने पूछा—'हे श्यामे! तुम कब आईं?'\nश्यामला ने उत्तर दिया—'अभी-अभी। सखी, आपको क्या हुआ है? आपके शिथिल अंग थकान प्रकट कर रहे हैं। आपके होठ पीले पड़ गए हैं, भुजाएँ मुरझाए हुए कमल-नाल जैसी लग रही हैं और गालों पर लावण्य की मनोहर रेखाएँ नहीं हैं। आज आप वायु से झूले हुए कोमल लता की भाँति, हाथी द्वारा कुचले कमल-कोरक के समान, या पागल भौंरे द्वारा त्यागी गई नव्य जूही-माला जैसी दिख रही हैं।'\n'हे सुंदरी! आपको अपने चिर-प्रियतम से कोई अत्यंत दुर्लभ वस्तु मिली है। अन्यथा हमारी भाग्य-लता ऐसा फल कैसे दे सकती थी? कृपया मुझे बताइए।'\nश्यामला के स्नेहपूर्ण प्रश्न से पूछी गई शुद्ध-हृदया राधा ने अपने चंद्रवदन मुख को वस्त्र से ढककर भूमि की ओर देखा। आनंदमयी सखियों के बीच राधा मधुर मुस्कान के साथ बोलीं—'हे कमल-नयन सखी! मैं जानती हूँ कि मैं कहाँ थी, कहाँ गई, उनसे मिलने किस मार्ग से गई और कैसे वहाँ पहुँची, तो तुम कैसे नहीं जानतीं? तुम्हारी सलाह के बिना मैं कुछ भी नहीं करती।'\n'अरे! वह क्या है, जो मन की पहुँच से परे और चिंतन की सीमा से बाहर है? संभवतः वह कोई स्वप्न, कोई इंद्रजाल, या दीर्घ मोह की अवधि थी, जिसने मुझे आनंद दिया या पीड़ा, या दोनों, या कुछ भी नहीं—मैं नहीं कह सकती। मुझे केवल इतना ज्ञात है कि उसने मेरा हृदय पूर्णतः पिघला दिया और मैं अचेत हो गई।'",
    88: "'जब पौर्णमासी नंद महाराज के महल में प्रवेश करीं, तो उन्होंने दिनभर की मथनी-क्रीड़ा से टपके मक्खन और दही की बूँदों से सज्जित प्रसन्न आँगन देखा। वह आँगन श्वेतद्वीप के समान लग रहा था, जहाँ रत्नभूषित भगवान अच्युत दूध की हिलती तरंगों के बीच अनंत के कोमल उदर पर आनंद से विश्राम करते हैं। अत्यंत हर्ष से पौर्णमासी ने रत्नों से विभूषित कृष्ण को देखा, जो अपने प्रियजनों से घिरे कोमल शय्या पर शांतिपूर्वक सो रहे थे। शिष्टाचार में निपुण यशोदा ने जैसे ही तपस्या की मूर्ति पौर्णमासी को देखा, वे प्रसन्न होकर उनका स्वागत करने दौड़ीं।'\n'यशोदा ने कहा—स्वागत है भगवती! अंदर पधारिए। आप व्रज की सर्वाधिक पूजनीय महिला हैं। मैं आपके चरणों में प्रणाम करती हूँ।'\n'यशोदा जब आदर करने आगे बढ़ीं, तो पौर्णमासी ने उन्हें स्नेह से गले लगा लिया। पौर्णमासी गोविन्द को देखने के लिए अत्यंत उत्सुक थीं। उन्होंने यशोदा को आशीर्वाद दिया तथा उनके, उनके पति, पुत्र और गौओं के कुशल-क्षेम का प्रश्न किया। यशोदा ने पौर्णमासी को अपनी सुख-समृद्धि की सूचना दी और फिर शीघ्र ही कृष्ण के शयन-कक्ष में प्रवेश कर गईं।'",
    104: "राधा ने अपनी हथेली से जल उठाकर मुँह में कुल्ला किया। ऐसा करते समय उनके गाल थोड़े फूले और उनके मुँह से कोमल मधुर ध्वनि निकली। राधा ने कुल्ले का जल सोने के पीकदान में थूका। मुख धोते समय कुछ अलकें उनके ललाट पर आ गिरीं। राधा ने बाएँ हाथ की अँगुलियों से उन्हें सिर के ऊपर धकेल दिया। राधा ने तीन बार अपना ललाट, गाल और नेत्रों को स्वच्छ किया, जिससे वे और भी अधिक कांतिमय हो उठे।\nएक सखी ने राधा को कल्पवृक्ष की उत्तम शाखा दातून के रूप में भेंट की। राधा ने उसे अपने कमल-कलिका-से हाथ में स्वीकार कर दाँत माँजे। दाँत माँजते समय राधा की पहुँची और कुण्डल इधर-उधर झूल रहे थे। उनके दाँत मोती की वर्षा के कणों के समान चमक रहे थे। हाथों की शीघ्र गति के बावजूद किशोरी की चूड़ियाँ किसी प्रकार चुपचाप रह जातीं। एक सखी ने रत्न-जड़ित धनुषाकार जिह्वा-शोधक भेंट किया। राधा ने उसे अपने कोमल हाथों के अँगूठे-तर्जनी के बीच पकड़कर जिह्वा पर आगे-पीछे फेरा।\nराधा, जो कोमल नव कमल-पर्ण के समान जिह्वा को स्वच्छ कर रही थीं, सिर हल्का झुकाकर हिला रही थीं, जिससे अलकें मुख पर बिखर गईं। सखियों को मुस्कुराते देख राधिका भी मुस्कुराईं। राधा ने अपने चंद्रवदन मुख और मुँह को कुछ बार धोया और फिर हाथ साफ किए। एक सखी द्वारा दिए कोमल, महीन तौलिये से राधा ने मुख की शेष बूँदें पोंछ लीं।\nएक सखी ने राधा के सम्मुख रत्न-जड़ित दर्पण धारण किया। अपनी अद्वितीय सुंदरता को देखकर राधा ने अनुभव किया कि यह प्रियतम के नेत्रों के लिए उत्सव होगा। राधा ने अपनी मुस्कान के अमृत से पुनः मुख धोया।",
    107: "'प्रत्येक गाय ने कृष्ण के स्नेह से, जो उसे अपने बछड़े से भी अधिक प्रिय थे, अपने थनों से दूध स्वतः बहा दिया। दूध की धाराओं से भर-भरकर बाल्टियाँ उछलने लगीं और छलककर पृथ्वी को गीला कर दिया।'",
    151: "तुङ्गविद्या सखी ने कहा—'नंदीश्वर के परिदृश्य को असंख्य उत्तुंग वृक्ष, पुष्पित लताएँ और झाड़ियाँ सुशोभित कर रहे हैं। वहाँ रसाल, कटहल, आम, पान, अर्जुन, गुवाक, नारियल, असन, पलाश, बरगद, पर्कटी, खदिर, बिल्व, मधुक, गिरिमल्लिका, बकुल, नाग, पुन्नाग, अशोक, बक, पाटली, स्वर्ण-चम्पक, तमाल, नवमल्लिका, स्वर्ण-यूथिका, यूथिका, पीत-अमरंथ, लौंग, दमनक, अतिमुक्ता, जवा, मल्लिका, कदली, प्रियंगु और तुलसी के वृक्ष हैं।'",
    172: "राजसी भोजन-गृह को सजाने वाले झालरों और रंगीन चित्रों से वहाँ उत्सव-जैसा वातावरण बन गया। रत्न-जड़ित प्यालों में रखी विभिन्न सब्जियाँ रत्न-मणि खचित मेज के किनारे सजाई गई थीं। स्वादिष्ट मिठाइयों के असंख्य कटोरे तथा विभिन्न दुग्ध-पदार्थों के स्वर्ण-कटोरे सब्जियों की पंक्ति के ठीक पीछे रखे गए थे। राधा की सखियों ने पदार्थों को अर्ध-वृत्त तथा अन्य आकृतियों में कलात्मक रूप से सजाकर अद्भुत वातावरण निर्मित किया। बीच में घी से तर-बतर सुगंधित श्वेत चावल का विशाल ढेर स्वर्ण-थाल में रखा था। दाईं ओर उन्होंने घी, नींबू, अचार, अदरक, आम और सरसों की चटनी का स्वर्ण-थाल रखा। चतुर्दिक कपूर-सुगंधित पेय-जल के घड़े रखे गए।\nमाता यशोदा किशोरी की पाक-कला और भोजन परोसने की सखियों की अद्भुत व्यवस्था देखकर अत्यंत प्रसन्न हुईं। उन्होंने एक धाय को अपने लड़कों को बुलाने भेजा। कृष्ण और बलराम उत्सुकता से भोजन-गृह की ओर चले। सुंदर पीत-वस्त्र धारण किए कृष्ण ने माता यशोदा को प्रणाम किया। उनके निर्देश पर कृष्ण ने कुछ कन्याओं को अपने और बलराम के चरण धोने तथा मुँह धोने के लिए जल देने की आज्ञा दी। यह देखकर यशोदा आनंद से विभोर हो गईं। कृष्ण ऊँचे भोजन-मंच पर बैठ गए। सभी स्वादिष्ट पदार्थों को देखकर वे पूर्ण आश्चर्यचकित रह गए।",
    186: "गहन स्मरण करते हुए गौरांग ने गोविन्द की वह अत्यंत आकर्षक पूर्वाह्न-लीला पुनः अभिनीत की, जब वे मित्रों के साथ गायों को वन ले जाते थे और जिससे व्रजवासियों को अत्यंत वेदना होती थी। गौरांग जब व्रज-भाव में डूबे, उनका शरीर पुलकित हो गया, स्वर्ण-वर्ण शरीर काँपने लगा और आनंद-विह्वलता में स्तब्ध हो गया। गौरांग अपने अंतरंग सहचरों के साथ विविध भावों को बाँटते हुए अश्रुधारा बहाते थे। सदा दिव्य आनंद की तरंगों में डूबे रहने वाले उस गौरचंद्र की, उनके सहचरों सहित, मैं सदा सेवा करूँ।\nमूल-सूत्र: प्रतिदिन प्रातः कृष्ण और गोप-बालक गायों को वन ले जाते थे। तीव्र वात्सल्य-प्रेम के कारण नंद, यशोदा और अन्य व्रजवासी उनका अनुसरण करते थे। कृष्ण गायों और बालकों को गोवर्धन पर छोड़कर चुपचाप राधा-कुण्ड जाकर राधिका की खोज करते थे।\nराधारानी कृष्ण को अपनी गायों के साथ नंदग्राम से जाते देखती थीं। तब वे घर लौटकर यावट आ जातीं और जटिला की आज्ञा से सूर्य-पूजा करने जातीं। प्रस्थान से पहले राधा कृष्ण के समाचार लानेवाले अपनी दूती की प्रतीक्षा में मार्ग की ओर व्याकुलता से देखती थीं। राधा-गोविन्द की पूर्वाह्न-लीलाओं का हम सदा स्मरण करें।",
    189: "श्याम ने अपनी शिखा में अत्यंत मनोहर इंद्रधनुषी मोरपंख और चमकीले लाल गुंजाओं की माला धारण की। इंद्रनील-कुण्डल और पुन्नाग-पुष्पों के गुच्छे उनके कानों को सुशोभित कर रहे थे। उनके विशाल वक्ष पर मोती तथा गुंजा की मालाएँ लटक रही थीं। इस प्रकार पीत-वस्त्र और विविध आभूषणों से सज्जित कृष्ण वन में प्रवेश करने के लिए तैयार होकर अद्भुत शोभायमान हो रहे थे।",
    230: "'गोप-बालकों ने अपनी-अपनी रुचि के अनुसार कृष्ण को विविध रंग-बिरंगे वन-आभूषणों से सजाने की होड़ में कहा—पहले मैं करूँ! पहले मैं करूँ!'\n'कृष्ण ने कहा—मेरे प्रिय मित्रों! इस रमणीय वातावरण वाले नदी-तट की सुंदरता देखो। और ध्यान दो कि कैसे प्रस्फुटित कमल अपनी सुगंध से भौंरों और पक्षियों को आकर्षित कर रहे हैं। उनकी गुंजार और चहचहाहट वन के सुंदर वृक्षों में गूँज रही है। यहाँ की रेत कोमल और स्वच्छ है, अतः यह हमारी क्रीड़ाओं के लिए सर्वोत्तम स्थान है। मैं समझता हूँ कि हमें यहीं भोजन करना चाहिए, क्योंकि हमें भूख लगी है और बहुत देर हो चुकी है। बछड़े जल पी सकते हैं और घास चरते हुए इधर-उधर विचर सकते हैं।'\n'जैसे कमल-पुष्प की कर्णिका पंखुड़ियों और पत्तों से घिरी होती है, वैसे ही कृष्ण मित्रों की पंक्तियों से घिरकर बीच में बैठे थे, और सभी अत्यंत सुंदर दिख रहे थे। प्रत्येक बालक कृष्ण की ओर देखता था, यह सोचते हुए कि कृष्ण मेरी ओर देखें। इस प्रकार उन सबने वन में आनंदपूर्वक भोजन का आनंद लिया।",
    254: "'मैं नहीं जानता कि वंशी जहर उगल रही है या अमृत। क्या वह वज्र से भी कठोर है या जल से भी कोमल? क्या वह प्रज्वलित अग्नि से अधिक गर्म है या चंद्रमा से अधिक शीतल? तथापि मैं इतना जानता हूँ कि उसे सुनकर समस्त व्रजवासी उन्मत्त हो जाते हैं।'",
    261: "प्रेमावेश में व्याकुल कृशोदरी राधा ने अपनी मेखला गले में, हार पैरों में, बाजूबंद चरणों पर और नूपुर भुजाओं में पहन लिए। प्रियतम से मिलने जाते समय राधा के सभी अंगों ने प्रेम के आनंद का प्रचार करके अपनी-अपनी विशेष शक्ति प्रकट की।",
	
    273: "मार्ग पर दौड़ती हुई वृन्दा ने सोचा—'मूर्ख लोगों ने किशोरी के मुख की सुंदरता की तुलना चंद्रमा या कमल से करने का प्रयास क्यों किया है? दूर से देखने पर भी राधिका के मुख की सुंदरता दर्जनों अमृतमय चंद्रमाओं को लज्जित कर देती है और गर्वित कमल-समूहों को हारकर कुम्हला डालती है!'",
    275: "राधा: 'तुम झूठी हो! ऐसा मत बोलो!'\nवृन्दा: 'हे राधा, मैं सत्य कह रही हूँ! सुनो! गोकुल में सैकड़ों तेजस्वी सुंदर युवतियाँ हैं, जिनके मन पूर्णतः कृष्ण से आसक्त हैं। तथापि उन सबकी शिरोमणि केवल तुम हो। मैं स्वयं देखकर कह सकती हूँ कि तुम्हारे विरह में कृष्ण किसी अन्य स्त्री की ओर दृष्टि भी नहीं डालते।'",
    276: "अपना आशय छिपाते हुए राधा ने उत्तर दिया—'हे वृन्दा, गपशप से क्या लाभ? हम श्याम-कुण्ड के पाताल-गंगा जल में स्नान करेंगी, जटिला की आज्ञा के अनुसार सूर्य-पूजा करेंगी और घर लौट जाएँगी।'",
    281: "'हे सुबल! क्या यह स्त्री प्रेम-कला का आश्रय है, जो अपने कोमल अंगों को दिखाकर मेरा हृदय चुरा लेती है? उसका सुंदर शरीर चित्रित उत्कृष्ट चित्र-सा, या नवीन शिल्प से तराशा हुआ, या नवयौवन की खराद पर उतारा हुआ और कामदेव की कलाओं की शिला पर घिसा हुआ प्रतीत होता है। उसके अंग ऐसे लगते हैं मानो सौंदर्य के गहरे सरोवर में डुबोकर उठाए गए हों और मानो आलस्य से मोहक हों।'",
    282: "'राधा का तेजस्वी मुख मेरे नेत्रों के प्यासे चकोरों के लिए पूर्णिमा का चंद्रमा है। वह मेरी नासिका के भ्रमर के लिए कमल है और उसके स्वादिष्ट अधर मेरी जिह्वा के कोकिल के लिए नव-विकसित आम्र-मंजरी हैं। किशोरी के झंकृत आभूषण मेरे कानों के हिरणों को आकर्षित करते हैं। कामाग्नि में जलते मेरे शरीर के मत्त गजराज के लिए वह अमृत की शीतल नदी के समान मेरे पास आती है। अहा! मेरे सौभाग्य का कल्पवृक्ष अब फलित हुआ!'",
    283: "'राधा के नेत्रों के कोने, सुंदर काजल से चिह्नित, स्वर्ण-पिंजर में खंजन पक्षियों के समान चमक रहे हैं। उनकी मधुर मुस्कान कुट्टित कपूर के समान कांतिमय दिख रही है।'",
    284: "'हे मेरे मित्र सुबल! जब कमल-नयन राधारानी श्वास लेती हैं, तो उनके माणिक्य-समान रंग के नथुनों के छिद्र फूलते हैं और उनकी नाक का मोती वायु में झूलते झूले पर चढ़े हुए के समान आगे-पीछे हिलता है। राधा का यह मनोहारी दृश्य मेरे हृदय में गहराई तक समा गया है।'",
    286: "जैसे ही राधा ने अपने प्रियतम को देखा, उनकी प्यासी आँखें आनंद से फैल गईं और कानों तक पहुँचने का प्रयास करने लगीं। राधिका का आंतरिक उल्लास नेत्रों से आनंदाश्रु के रूप में बह निकला, मानो नेत्रों के परिश्रम से उत्पन्न स्वेद-बूँदें हों।",
    288: "तुलसी की बातों से राधा के मुख पर भौंहें चढ़ गईं। तब एक सखी ने कहा—'हे गौरी! आपके नेत्रों की पुतलियों में सभी बुद्धिमानों को मोहित करने की शक्ति है। हे गांधर्विका! आपके नेत्रों के भौंरे कृष्ण के कानों में लटकते सुगंधित कमलों की ओर उड़ते हैं। मधुसूदन (भौंरा) आपके कमल-नेत्रों की लीलापूर्ण चंचलता से पूर्णतः अपना स्मरण खो बैठते हैं। कृष्ण दूसरे कमल (पद्मा, यानी चंद्रावली सखी) को कैसे याद कर सकते हैं?'",
    291: "'नीला-श्याम वर्ण धारण करने वाले, सर्वव्यापी तेजस्वी, हाथ में सीधी गोपाल-छड़ी लिए, कटि में पीत-वस्त्र लपेटे, जिनके शरीर की सुगंध नील-कमल को लज्जित करती है, और जिनकी रसीली मूर्ति प्रेम की प्रतिमूर्ति है, वे हरि अब वन में विहार कर रहे हैं।'",
    298: "एक-दूसरे को देखकर राधा-माधव प्रेमावेश से विह्वल हो उठे। उनके दिव्य शरीर, मन और हृदय तीव्र हर्ष से काँपने लगे। क्षण भर वे स्तब्ध खड़े रहे, बोलने या हिलने में असमर्थ।",
    305: "कृष्ण राधिका की अद्वितीय सुंदरता की मदिरा पीकर उनसे मिलने की उत्कंठा से मतवाले हो गए। आनंद-विह्वलता के कारण कृष्ण पूर्णतः भूल गए कि उन्होंने राधा को पहले कभी देखा था। फिर स्मृति लौटने पर उन्होंने देखा कि व्रज-गोपियों की शिरोमणि उनके पुष्प तोड़ रही थीं। मन में आनंद की दौड़ लगाते हुए कृष्ण धीरे-धीरे राधा के पास पहुँचकर पूछा—'तुम कौन हो? मेरी मंजुल-लता को क्यों जान-बूझकर विचलित कर रही हो?'\nराधा ने कृष्ण की ओर देखा, जिनके नेत्र चंचल थे और ललाट पर गोरोचन का तिलक था, और कहा—'मैं सूर्य-पूजा के लिए पुष्प तोड़ रही हूँ। आप क्यों आपत्ति करते हैं?' राधा ने अपना सुंदर सिर पूर्णतः घूँघट से ढक लिया और पुष्प-तोड़ने के बहाने चल दीं। राधा ने चंचल नेत्रों से इधर-उधर देखा। उन्हें राधा-कुण्ड के तट पर घनी पत्तियों वाला एक जूही-गुल्म दिखाई दिया। प्रेम के प्रभाव से जगमगाते कमल-मुख वाली राधिका उस जूही-गुल्म के पास पहुँचीं और उसकी घनी पत्तियों, अनगिनत पुष्पों और भौंरों के झुंड के भीतर अंतर्धान हो गईं।",
    306: "कृष्ण ने कहा—'अरे मृग-नयनी! अब मैं समझ गया कि तुम प्रतिदिन छिपकर पुष्प चुराती हो। अरे चोरिनी! आज तो भाग्य से मैंने तुम्हें पकड़ लिया। अब हठ मत करो; बस मेरे साथ कारागार-गुफा में चलो।'",
	
    318: "राधा के स्पर्श से कृष्ण इतने मोहित हो गए कि उनके हाथ काँपने लगे, जिससे राधारानी पर उनकी पकड़ ढीली पड़ गई और उनसे अनजाने में उनकी वंशी गिर गई। किशोरी श्याम के आलिंगन से छिटककर बाहर निकलीं, शीघ्रता से वंशी उठाई और सावधानी से अपने वस्त्रों के नीचे छिपा लिया। सभी सखियों ने सोचा कि ललिता के भय से कृष्ण ने अपनी वंशी गिरा दी और राधा को छोड़ दिया।\nललिता ने कहा—'हे सखी! यह विचित्र बात है कि सोते हुए भी किसी अन्य गोपी ने नंदनंदन से वंशी नहीं चुराई। फिर भी भाग्यवती राधा ने कटाक्ष-कला से कृष्ण को मोहित करके उनकी आँखों के सामने ही वंशी चुरा ली।'\nराधा ने स्वयं से धीरे-धीरे कहा—'यह वही वंशी है, जो गोपियों के हाथों को गृह-कार्य करते समय स्तब्ध कर देती है। रात्रि में यह वंशी स्वर्ण-कांतिमयी गोपियों को उनके पतियों की गोद से भी खींच लाती है। यह धृष्ट वंशी बड़े-बुजुर्गों के सामने भी गोपियों के अंतर्वस्त्र के सूत्र शिथिल कर देती है! अब कृष्ण की यह शरारती वंशी मेरे वश में है।'",
    324: "राधिका की चूड़ियाँ जोर से झंकृत हुईं, जब उन्होंने कृष्ण को अपने चोली और अंतर्वस्त्र खोलने से रोकने के लिए हाथ बढ़ाए। प्रेम-कंप से काँपते हुए कृष्ण हकलाकर बोले—'वं-वं-वंशी दो!' राधिका ने हर्ष से हकलाते हुए उत्तर दिया—'मेरे पास तुम्हारी वंशी नहीं-नहीं है!'\nकृष्ण ने उत्सुकता से राधा के यौवन के रत्न चुराने शुरू किए और वे व्याकुल होकर उन्हें रोकने लगीं। अंततः कंदर्प (कामदेव) का सेनापति, जिसे धृष्टता कहते हैं, ने राधिका के प्रतिरोध, लज्जा और धैर्य रूपी सखियों को रणभूमि से भगा दिया। राधा-माधव के सुंदर दिव्य प्रेम-उत्सव की आग बढ़ती गई, जब राधा के भावपूर्ण उच्छ्वास, कोकिल के मधुर कूजन के समान, अमृत की धारा के रूप में प्रकट हुए। उनके तेजस्वी शरीरों पर प्रणय-दंशन और नख-चिह्न उत्पन्न हुए, जब वे क्रीड़ा से संघर्ष करते रहे। राधा-माधव की एकांत कुंज की मधुर लीलाएँ सदा विजयी हों!",
    332: "एक अन्य सखी ने राधा से पूछा—'हे कमल-नयनी! किसने अपने नखों से आपके वक्ष के ऊपरी भाग पर अपना चित्र बना लिया है? वह चित्र न तो धूमिल होता है, न मिटाया जा सकता है। क्या आप उस चित्र को धारण करने में गर्व का अनुभव नहीं करतीं?'",
    339: "'कहीं भूमि मरकत मणि की बनी है, जिसमें स्वर्ण के वृक्ष, गुल्म और लताएँ हैं। कहीं मार्ग स्वर्ण के हैं और वृक्ष-लताएँ मरकत के। कहीं-कहीं माणिक्य की भूमि पर स्फटिक के वृक्ष, गुल्म और लताएँ हैं। अन्य स्थानों में स्फटिक की भूमि तथा माणिक्य के वृक्ष और गुल्म हैं। कहीं मरकत के वृक्षों को स्वर्ण की लताएँ आलिंगित किए हैं, तो कहीं मरकत की लताएँ स्वर्ण के वृक्षों को। कहीं स्फटिक के वृक्ष माणिक्य की लताओं को आलिंगन करते हैं, तो कहीं माणिक्य के वृक्ष स्फटिक की लताओं को।'\n'वृन्दावन में ऐसा कोई रत्न-वृक्ष नहीं है, जिसकी रत्न-शाखाएँ न हों, और न ऐसी रत्न-शाखा है, जिसमें रत्न-कलिकाएँ न हों। न रत्न-कलिका है जिसमें रत्न-पुष्प न हों, और न रत्न-पुष्प है जिसमें मनोहर सुगंध न हो। वृक्षों के आधार के चारों ओर जल-कुण्ड हैं। रत्न-पर्वतों से उत्पन्न तरल रत्नों के ढेरों के समान प्रवाहित धाराओं से वे कुण्ड भरे हुए हैं। रत्न-पक्षी उन रत्न-कुण्डों को सुशोभित करते हैं।'",
    340: "'माणिक्य-जड़ित जल-कुण्डों के प्रतिबिंबित प्रकाश-किरणों के कारण वृक्षों के तने लाल लाख से लिप्त प्रतीत होते हैं। ऐसा लगता है कि उनके हृदय के भीतर स्थान की सीमा के कारण उनकी जड़ों से कृष्ण के प्रति उनका तरल आकर्षण (रस) ऊपर उठ रहा है।'",
    352: "राधा की स्वर्ण-कांति ने कृष्ण के नील वर्ण को मरकत जैसा हरा कर दिया, और उनके नील वर्ण ने उसकी स्वर्ण-कांति को हरा। राधा-माधव ने विरह में अपने-अपने वर्ण बनाए रखे, किंतु मिलन में वे एक ही वर्ण के हो गए। राधा ने श्याम के कंधे पर अपनी भुजा रखी और वे धीरे-धीरे मार्ग पर चलने लगे। उनकी कटियाँ सागर में मिलती तरंगों की भाँति कभी-कभी आपस में टकरा जाती थीं।",
    359: "'राधा! यहाँ कामदेव राजा है। मधुर वसंत उसका मंत्री है और मलय-पवन उसका अजेय सेनापति। भौंरे उसके गुप्तचर हैं और कोकिल-झुंड उसके दंडाधिकारी। अवज्ञाकारी व्रज-गोपियाँ दंडनीय हैं और पर्वत-गुफाएँ कारागार हैं।'",
    360: "'कोकिलाएँ, जो सचमुच आद्य ध्वनि की प्रतिमूर्ति हैं, आम्र-मंजरियों का रस लेकर मधुर कूजन के लिए अपनी चोंचें खोलती हैं। आम्र-मधु से मत्त भौंरों का मोह इस समय मंजरियों से हट जाता है और वे विश्राम करते हैं। मदोन्मत्त गजराजों में श्रेष्ठ, कामदेव के समान, वह कृष्ण व्रज की मदमाती गोपियों के साथ विचरण करता है, जिनकी मधुर फुसफुसाहट बहते जल की सुखद ध्वनि को भी पराजित कर देती है। कोकिलाएँ चारों दिशाओं में घंटे के समान कूजकर अपने आगमन की घोषणा करती हैं।'",
    367: "ऐसी अपार सामग्री कैसे प्रकट हुई? वृन्दावन के कल्पवृक्षों ने सभी सुगंधित चूर्ण, रंगीन द्रव, लेप, लाख-फूल बम तथा पिचकारी, पुष्प-धनुष और बाण जैसे हथियार प्रदान किए।",
    369: "कुछ सखियाँ क्रीड़ा से अपनी चमकती स्वर्ण-मेखलाओं में फूलों के पराग की थैलियाँ छिपा रही थीं। पराग की थैलियाँ ऐसी लग रही थीं, मानो लंबे समय से संचित उनकी प्रेम-कला की संपदा हो, जिससे कृष्ण के मन-रत्न को क्रय किया जाएगा। अन्य सखियों ने रत्न-खचित थालों में लाख की कोमल शीशियाँ धारण कीं, जो अगुरु, कस्तूरी, कपूर और चंदन से भरी थीं।",
    370: "कृष्ण ने एक नवीन आम्र-मंजरी तोड़कर क्रीड़ा से अपने एक कान पर लटका लिया, जो उनके सुंदर रत्न-कुण्डलों के भार से थोड़ा लंबा हो गया था। कृष्ण के मनोहर कुण्डलों के झूलने से उनके गालों पर अद्भुत प्रतिबिंब पड़ते थे। उन्होंने माधवी पुष्पों की माला गले में डाल ली और अपनी सुंदर, उछलती घुँघराले अलकों के नीचे छिपा लिया।",
    371: "सूर्य के समान लाल महीन चूर्ण ने समस्त आकाश को ढक लिया। धीरे-धीरे नीचे उतरते हुए उसने कृष्ण की पगड़ी, अलकों, पलकों और तिलक को रंगा और सुगंधित कर दिया।",
    372: "कृष्ण ने अपनी वंशी पर मधुर, अव्यक्त स्वर कंपित करके युवा गोपियों के गायन-कौशल के चिर-प्रतिष्ठित गर्व को पराजित कर दिया। गोपियों ने उत्तर में कृष्ण को घेरकर आनंद से केसर-चूर्ण की वर्षा की, जबकि उनकी चूड़ियाँ झंकृत हो रही थीं।",
	
    386: "विशाखा और चित्रा राधा-माधव के दोनों ओर खड़ी होकर एक-दूसरे को देखने से उत्पन्न स्वेद को हटाने के लिए चामर डुला रही थीं।",
    392: "कृष्ण ने अपने हाथ से बनाए पुष्प-आभूषण प्रसन्नतापूर्वक राधा को भेंट किए। तथापि अपने मन के गहरे रूठने-भाव के कारण उन्होंने उन्हें धारण करने से मना कर दिया।",
    393: "कृष्ण ने किशोरी का रूठा मन तोड़ने का प्रयास करते हुए कहा—'हे देवी! आप व्यर्थ ही क्रोधित हैं। आपके आग्रह पर मैंने स्वयं यहाँ पुष्प तोड़े हैं। आप मुझसे बात करने से क्यों इनकार कर रही हैं? हे राधा! मेरी प्रिया-सखी! अब मैं जान गया कि तुम्हारा नाम राधा क्यों है (राध का अर्थ है नाश करना या तृप्त करना)। धूर्तता मत करो।\nबस आज्ञा दो, मैं तुम्हारे कानों को कुछ पुष्पों से सजा दूँ।'",
    394: "'हे राधा! यदि तुम मुझ पर क्रुद्ध हो, तो तुम्हारे गाल हर्ष से कैसे लाल हो रहे हैं?' श्याम की चंचल बातें सुनकर राधा अपनी मुस्कान नहीं रोक सकीं। तब व्रज के शूरवीर राजकुमार कृष्ण ने राधारानी का चुंबन किया।",
    403: "राधा-माधव ने वन की शोभा का आनंद लिया और शीघ्र ही कदम्ब-ताल तक पहुँचे। जिन वृक्षों की ऊँची श्यामल शाखाओं पर अनगिनत पीले कदम्ब-पुष्पों से मधु की धाराएँ बह रही थीं, उन्होंने बिजली से विभूषित मेघों की शोभा को पराजित कर दिया। कदम्ब-वृक्षों के बीच अत्यंत लंबे चबूतरे कृष्ण के आनंद के बाँध प्रतीत हो रहे थे। कदम्ब-पुष्प चबूतरों पर निरंतर मधु छिड़कते थे और सुंदर निद्रारहित भौंरे उनकी रक्षा करते थे। प्रत्येक चबूतरे के दूरस्थ किनारों पर ऊँचे कदम्ब-वृक्षों के जोड़े खड़े थे, जिनकी ऊपरी शाखाएँ आपस में गुंथकर मरकत-शिखरों वाली छतें बनाती थीं। प्रस्फुटित पुष्पों ने झालरों का रूप धारण कर लिया था।",
    407: "जोरदार झूलने के कारण राधा और कृष्ण की अलकें उनके कुण्डलों में उलझकर बिखर गईं। उनकी कटि की पुष्प-सूत्र रत्न-घुँघरुओं से उलझ गईं। उनकी मुरझाई मालाएँ चूड़ियों में अटक गईं।",
    418: "इसके बाद माधव उस वन में गए, जो शिशिरमोद (हिम-ऋतु का आनंद) कहलाता था, वहाँ के प्रेमपूर्ण स्नेह का प्रत्युत्तर देने के लिए। वन ने कृष्ण के आगमन की चिंता में हर्षाश्रु बहाए और ओस की बूँदों के रूप में अश्रु बहाए। उसने अपने प्रस्फुटित कुंद-पुष्पों से मुस्कान बिखेरी, जिससे उसके सुंदर श्वेत दाँत दिखाई दिए। ऋतु ने अपने प्रियतम के विरह में शोक करते हुए दमनक-गुल्मों के रूप में अपनी अलकें खोल दीं, जो प्रातःकालीन सूर्य की किरणों में चमक रही थीं।",
    424: "यद्यपि कृष्ण उनके सामने खड़े थे, तथापि गहन आसक्ति से उत्पन्न विरह-वेदना से राधा का मन और बुद्धि विह्वल हो रहे थे। राधा ने अपने दाँतों के बीच तिनका दबाया और गहरी साँस लेकर कहा—'हे सखी! कृपया मुझे कहीं कृष्ण दिखाओ!' यह देखकर कृष्ण भी विस्मित हो गए।",
    433: "एक अन्य बातूनी गोपी अस्पष्ट, लड़खड़ाते शब्दों में बोली—'क्या दुर्भाग्य है! दे-देखो! आकाश गि-गिर रहा है! पृथ्वी घू-घूम रही है! हे प्रभो, मेरा सुकुमार शरीर काँ-काँप रहा है। कृपया मुझे था-थाम लो, पहले मैं गि-गिर न जाऊँ।' तब भयभीत उस मदमाती गोपी ने कृष्ण के गले को अपनी भुजाओं से कसकर पकड़ लिया।",
    445: "ललिता ने उत्तर दिया—'हे माधव! राधा के प्रति अपना प्रेम प्रकट करके आपने उनके चरणों की लालिमा को अपने वक्ष पर कौस्तुभ-मणि के रूप में प्राप्त किया है। आपने राधा के नेत्रों को अपने पान-रंजित अधर भेंट किए और बदले में अपने अधरों को उनके काले काजल से रंग लिया। वास्तव में, आपकी प्रेम-कुशलता आपके अपने अंगों पर भी समान रूप से प्रकट है।'",
    450: "राधा ने कृष्ण की ओर तिरछी दृष्टि डाली, परंतु वे बोलते रहे—'मेरी प्रिय चंद्र-मुखी राधारानी! क्या बिजली की चमक ने आपके चंचल कटाक्ष से वेगपूर्वक चलने की कला सीखी है? या आपके कटाक्ष ने बिजली की चमक से चंचलता सीखी है? हे राधा! किसी भी प्रकार, मेरा विचार है कि आपका कटाक्ष ही गुरु होना चाहिए, क्योंकि उसने मेरे चंचल मन को पूर्णतः बंदी बना लिया है।'",
    461: "राधा सारे कोलाहल के बीच खिसककर स्वर्ण-कमलों के गुच्छे के बीच छिप गईं। कृष्ण ने उत्सुकता से राधा की खोज की। उन्होंने एक-एक कर पीले कमलों का चुंबन किया, यह समझकर कि वही राधा का मुख है। राधा और उनकी सखियाँ अनियंत्रित हँसी में फूट पड़ीं। कृष्ण ने राधा का छिपने का स्थान जान लिया और तुरंत उनके पास पहुँच गए।",
	
    481: "'हे प्रभो! वृन्दावन के कामदेव! आपकी जय हो! आपकी परम प्रिया गोपी दिव्य देवी है और आप सबके शिरोमणि हैं। आपके चरण-कमलों का मधु आनंद और ज्ञान की धाराओं से भी मीठा है। हे गोविन्द! समस्त ब्रह्मांडों के बीज-रूप आपकी महान मूर्ति को मैं बार-बार प्रणाम करता हूँ।'",
    496: "'मुझे कृष्ण की भुजाएँ स्मरण हैं, जो प्रेम-उत्सव में व्रज-गोपियों के हृदयों को झूलानेवाले झूले के रत्न-स्तंभों के समान हैं। कृष्ण की लंबी भुजाएँ कामदेव-युद्ध में राधा की पराजय की घोषणा करनेवाले विजय-स्तंभ के उच्च द्वार-स्तंभ हैं। वे असुरों को पराजित करनेवाले महायज्ञ के यूप-स्तंभ हैं, या माधुर्य और संयोग-प्रेम नामक गजराजों की सूँड हैं।'",
    511: "'माधव का दिव्य स्वरूप सनातन ज्ञान और आनंद से संघनित है। गोविन्द के शरीर की नील-कांति मेघ-समूह के समान चमकती है। श्याम का तेजस्वी शरीर, जो प्रेम-श्रम से दीप्त गोपियों के मनोहर कटाक्षों से सदा विचलित रहता है, तीनों लोकों के प्रेम का आश्रय है। मेरे मन में कृष्ण की अद्वितीय दिव्य मूर्ति सदा प्रकट रहे!'",
    512: "तोते ने निष्कर्ष कहा—'और क्या कहूँ! कृष्ण का अलौकिक शरीर सबके नेत्रों पर आनंद की वर्षा करने वाला मधुर रस का अनंत सागर है। कृष्ण के सुंदर अंग उनके आभूषणों की शोभा को भी बढ़ा देते हैं। कृष्ण के महान शरीर की अनोखी सुंदरता का सहस्र मुख वाले स्वयं भगवान अनंत भी पूर्ण वर्णन नहीं कर सकते।'\nनर और मादा तोते प्रेमावेश से गद्गद होकर चुप हो गए। तोतों के वचनों के रस-सागर में डूबी सखियाँ क्षण भर आनंद-विह्वलता में स्तब्ध रह गईं।",
    517: "'प्रेम से विह्वल व्रज-गोपियों ने एक बार कृष्ण की वंशी को संबोधित किया—हे प्रिय सखी! हे क्रूर वंशी! तुम संगीत के वेश में एक क्षण अमृत की बाढ़ और दूसरे क्षण विष की बाढ़ उत्पन्न करती हुई प्रतीत होती हो। तुम एक साथ हमें सजीव और अर्धमृत कर रही हो। तुम हमारे भीतर ऐसी रहस्यमयी स्थिति उत्पन्न कर रही हो, जिसे हम न समझ सकते हैं, न सहन कर सकते हैं।'",
    520: "'हे नंदनंदन, आपकी जय हो! आप सभी रसों के कारण हैं, प्रेम के विषय और आश्रय दोनों हैं। आप व्रज-रस की मूर्ति हैं। आपके सुंदर चरण-कमल अद्वितीय गुणों से विभूषित और निरंतर बढ़ते हुए दिव्य अमृत से युक्त हैं। आपके माणिक्य-समान नखों की तेज किरणें भक्तों के हृदयों से शोक के अंधकार का नाश करती हैं। आपकी सुंदर श्यामल वर्ण-कांति निष्कलंक और अद्भुत आकर्षक है। आपकी कीर्ति समस्त ब्रह्मांड में फैली है। अनंत सौंदर्य, ऐश्वर्य, धैर्य और पराक्रम से युक्त नील-वर्ण वाले गोप-बालक, आपकी जय हो।'",
    521: "'हे कृष्ण, वंशी-वादन में निपुण! प्रफुल्ल शरद-कमलों से भी अधिक आकर्षक अपने नेत्रों की चंचल चेष्टाओं से आप सिद्ध और चारण-स्त्रियों के धैर्य का नाश करते हैं। आपके दीप्तिमान कुण्डल मोती की मालाओं में सुंदर झलकते हैं। आप गोवर्धन के अनेक शीतल कुण्डों में क्रीड़ा करते हुए समय बिताते हैं। आपका शरीर संघनित ज्ञान से बना है और सभी आभूषणों का आभूषण है।\nआपने सहज ही क्रूर वृषभासुर का वध किया। आपकी चमकदार श्याम अलकें तेजस्वी मोरपंख से सुशोभित हैं और आपका सुंदर मुख करोड़ों चंद्रमाओं से अधिक दीप्त है। आप व्रज के एकांत निकुंजों में प्रेम की सभी कलाओं में निपुणता प्रदर्शित करते हैं। आपकी कोमल, सर्प-समान भुजाएँ सखियों के उन्नत वक्षों को आलिंगन करने के लिए सदा तत्पर रहती हैं।\nवृन्दावन में चलते समय आप ऐसे लगते हैं जैसे तमाल-वृक्ष चल रहा हो। आप अपने प्रिय व्रजवासियों की सभी इच्छाएँ पूर्ण करते हैं। आप दाएँ हाथ की छड़ी से गायों की रक्षा करते हैं। आपकी चमकती कांति करोड़ों सूर्य-चंद्रों को ग्रहण कर लेती है। आपके ललाट पर गोरोचन-तिलक शोभायमान है। बाल मुनि सनक-सनंद सदा आपके मनोहर गुणों का रस लेते हैं। हे सुंदर वीर! मुझ पर कृपा करके स्वयं को मुझे दर्शन दीजिए!'",
    522: "'हे केशव, आपकी जय हो, जिनकी ब्रह्मा, शिव और अनंत बार-बार स्तुति करते हैं। आपके चरण-कमलों पर ध्वजा, वज्र और अंकुश के अनोखे चिह्न, तथा आपकी अनंत ब्रह्मांडीय शक्ति स्पष्ट रूप से आपको परमेश्वर सिद्ध करती हैं। अपने ऐश्वर्य के बावजूद आप निश्चिंत क्रीड़ाओं में विचरते हैं और कालिय जैसे मूर्ख प्राणियों से युद्ध करते हैं। आप भक्तों के आनंद को बढ़ाने तथा गोकुलवासियों के सुख में वृद्धि के लिए नंद के मासूम पुत्र की भूमिका निभाते हैं। आपकी अचिंत्य सुंदरता से स्वयं कामदेव भी मोहित हो जाता है। यद्यपि व्रज-गोपियाँ कभी प्रेम-ईर्ष्या के क्रोध में रूठती हैं, तथापि आपकी अद्भुत सुंदर मूर्ति देखते ही वे रुक जाती हैं। आप स्वर्ण-कांति गोपियों के साथ नृत्य करके और उनके सुंदर वक्षों को आलिंगन करके रास का रस लेते हैं। आप सैकड़ों वन-निकुंजों में व्रज-कन्याओं के साथ विहार करते हैं।\nगोपियों में से कोई भी आपको राधिका के समान संतुष्ट नहीं कर सकती, जो व्रज की सभी सुंदरियों की शिरोमणि हैं। जब आप ललिता और अन्य गोपियों के साथ रास-मण्डल में उत्साहपूर्वक नृत्य करते थे, तब आपका मोरपंख और अन्य आभूषण भूमि पर गिर गए। यद्यपि नृत्य की थकान से आपके नेत्र लड़खड़ाते थे, तथापि राधिका को देखते ही वे तुरंत आनंद से खिल उठे। सभी आपको प्रणाम करते हैं! क्रोधित असुर भी आपकी कृपादृष्टि से मुक्त हो जाते हैं। आप सदा व्रजवासियों की रक्षा करते हैं और भक्तों को आनंद देते हैं। हे कृपा-सागर, कृपया मुझे भौतिक संसार के सागर से उद्धार कीजिए!'",
    530: "चम्पाकलता ने कहा—'राधा के दाँत जूही-पुष्पों के समान श्वेत और हीरे के समान तेजस्वी हैं। कृष्ण के अधर-बिम्बों को चबाने से राधा के दाँत-रूपी तोते की चोंचें माणिक्य जैसी लाल हो गई हैं।'",
    531: "रंगदेवी ने कहा—'यह अनुभव करके कि कृष्ण के नाम-यश का युवा युगल झूलने की लीला करने के लिए उत्सुक है, विधाता ने राधा की जिह्वा का झूला बनाया और उसे किरमिजी चादर से ढक दिया।'",
    533: "वसंती ने कहा—'कृष्ण के अद्भुत गुण राधा के हृदय-उद्यान में कल्प-लता की भाँति बढ़ते हैं। उनके पुष्प राधा की मधुर मुस्कान के रूप में प्रस्फुटित हो रहे हैं।'",
    534: "विशाखा ने कहा—'विधाता ने कृष्ण के चकोर-नेत्रों को प्रसन्न करने के लिए ही राधा के मुख का अद्वितीय पूर्ण चंद्रमा बनाया। उन्होंने चंद्रमा पर राधा के नेत्रों के रूप में दो हिरण रखे। हिरणों को चंचल देखकर विधाता ने उन्हें राधा के कानों की दो रस्सियों से बाँध दिया।'\nचम्पाकलता ने कहा—'चंद्रमा कलंक से दूषित है, ग्रहण से ग्रस्त होता है और अपने स्पर्श से सुंदर कमल-पुष्पों को बंद कर देता है। अतः राधा के मुख के निर्मल, पूर्णतः शुद्ध और सदा पूर्ण तेजस्वी मण्डल की तुलना किससे की जा सकती है?'\nचित्रा ने कहा—'कृष्ण राधा के सुंदर गालों को देखकर अपनी तीव्र प्यास बुझाते हैं, जो स्वर्ण-दर्पणों के गर्व को नष्ट कर देते हैं। राधा के सुंदर गाल स्वर्ण-लोक के दो सरोवरों के समान प्रतीत होते हैं, जो दीप्तिमान अमृत से भरे हैं। उन सरोवरों के ऊपर राधा के कमल-कलिका-कुण्डल लटकते हैं। राधा के गालों पर कस्तूरी के चित्र सरोवरों की सेवार हैं, जिनमें राधा के कुण्डलों की दो मकरी (मादा मगरमच्छ) तैरती हैं।'",
    535: "सुदेवी ने आगे कहा—'राधा की नासिका की सुंदर वक्र रेखा तिल-पुष्प के समान है। वह उस तूणीर के समान भी दिखती है, जिसमें कामदेव नामक धनुर्धर अपने बाण रखता है। जब राधा मुस्कुराती हैं, तो ये बाण कृष्ण के हिरण-जैसे हृदय को बींध देते हैं।'\nमाधवी ने कहा—'अज्ञानी कवि कहते हैं कि प्रियाजी की नाक के नीचे लटकता मोती राधा के अधरों की लालिमा और नेत्रों के काजल की श्यामता के प्रतिबिंब से गुंजा-बीज के समान लाल और काला हो गया है। वास्तव में, राधा का हृदय अपने प्रियतम का निरंतर चिंतन करने से श्याम वर्ण का है। राधा का हृदय कृष्ण के प्रति तीव्र आसक्ति के कारण गहरे लाल रंग का भी है। जब भी राधा साँस लेती हैं, ये दोनों रंग उनकी नाक के मोती पर प्रतिबिंबित होते हैं।'\nवसंती ने कहा—'विधाता ने ब्रह्मांड की प्रत्येक सुंदर वस्तु का मधुर सार संग्रह करके राधा के आकर्षक नेत्र बनाए। शेष अंश भूमि पर गिरकर भौंरे, मृग-नेत्र, चकोर, कमल, मीन और कुमुदिनी बन गए।'",
	
    548: "'हे राधा! यदि एक साथ अनेक पूर्ण चंद्रमा उदय होकर अनगिनत ब्रह्मांडों को शुद्ध प्रेम के अमृत-प्रकाश से भर दें, तो भी वह बाढ़ वृन्दावन के निकुंजों में दिखने वाले आपके सुंदर मुख की अद्भुत कांति का केवल हल्का-सा संकेत दे सकती है।\n'सदा नवीन मधुर प्रेम की अधिष्ठात्री देवी, जिनका स्वरूप संघनित आनंद है, जो यमुनातट के कल्पवृक्षों के नीचे भव्य लीलाएँ करती हैं, जो अपनी अंतरंग सखियों के भावों से उद्दीप्त होती हैं, और जिनके चरण-कमल भक्तों के हृदयों में अमृत की धाराएँ प्रवाहित करते हैं, वे राधा हमारे सम्मुख प्रकट हों!",
    571: "कृष्ण ने अपने कौस्तुभ-मणि का शर्त हार दिया। उस समय सखियों ने कहा—'यह मणि तो पहले ही अनेक गोपियों के वक्षस्थलों का स्पर्श कर चुकी है, अतः यह हमारी प्रिय सखी कैसे पहने? इसे चूड़ी से बदल देना चाहिए, या कई बार धोकर शुद्ध करना चाहिए।'",
    580: "विश्वशर्मा ने आगे कहा—'हे भाग्यवती कन्या! अब जब आपने देवता की पूजा कर ली है, तो आकाश में चमकते सूर्य-ग्रह को अर्घ्य-जल अर्पित कीजिए।' (आंतरिक अर्थ: हे भाग्यवती कन्या! अब जब आपने देवता की पूजा कर ली है, तो आप अपने महान जीवन-मित्र की पूजा कर सकती हैं, जो चमकते पीत-वस्त्र धारण किए आपके सम्मुख खड़े हैं।)",
    593: "चंदनकला ने आगे कहा—'हे प्रिया-सखियों! कृष्ण ने श्रीदामा जैसे मित्रों के साथ उत्साहपूर्वक क्रीड़ा की, जो अपने गर्वित वचनों के अमृत-कणों से कृष्ण का सिंचन करके करोड़ों हृदयों से उनके नखों की तेज किरणों की पूजा करते हैं। सख्य-रस की मूर्ति कृष्ण यमुनातट पर अपने अंतरंग मित्रों के साथ समय बिताते थे।'",
    634: "'कृष्ण और बलराम के वस्त्र तथा आभूषण भोजन करने से गंदे हो गए थे, अतः उन्होंने उन्हें बदलकर नए वस्त्र धारण किए। दिव्य बालकों ने सावधानी से अपने चरण धोए और मसालों से अपना मुख ताज़ा किया।'",
    654: "'हे राधा! आपके अद्वितीय चतुर प्रियतम किसी की दृष्टि में न पड़कर महल से निकल गए। वे अब यमुनातट के मिलन-स्थल पर आपकी प्रतीक्षा कर रहे हैं। आप कुछ खा-पी लीजिए, अपने बड़ों को धोखा देकर उनसे मिलने के लिए प्रेमावेश में दौड़िए।'\nयह कहकर इंदुप्रभा चली गईं।",
    659: "'हे सखी! कृष्ण का वक्ष सभी स्त्रियों के दृढ़-संकल्प की नदी का विशाल बाँध है। उनके वचनों की चंद्रिका स्त्री-सतीत्व के कमलों को जबरदस्ती बंद कर देती है। माधव की दो भुजाएँ हमारे चिर-परिचित लज्जा के विनाश के तांत्रिक यज्ञ के स्तंभों के समान हैं। हाय दुर्भाग्य! उनकी चंचल सर्प-समान भौंहें हमारी इंद्रिय-संयम और संकोच का भक्षण करती हैं।'",
    670: "गोविन्द-स्थल में ऐसे कल्पवृक्ष भरे थे, जो हर इच्छा पूर्ण करते थे; पारिजात वृक्ष, जो सभी शत्रुओं का नाश करते थे; मंदार वृक्ष, जो दरिद्रता का नाश करते थे; और संतान वृक्ष, जो सब प्रकार का आनंद प्रदान करते थे।",
    679: "वृन्दा ने कहा—'हे सुकुमारी राधा! जब आप कदम्ब-वृक्ष के नीचे स्थित लीला-कुटिया में बैठे गोपराज-कुमार की ओर देख रही थीं, तब आपके कटाक्षों की तरंगें, मानो क्षीर-सागर से उठी तरल सौंदर्य धारा, श्यामल यमुना को श्वेत गंगा में बदल रही थीं।'",
    684: "विनम्र प्रार्थना के साथ वृन्दा और उनकी वन-देवियों ने राधा-माधव और सखियों को रत्न-मंदिर से उस स्वर्ण-सिंहासन तक ले गईं, जो चंद्रिका से आलोकित तथा सुगंधित पुष्पों से सज्जित था। आकर्षक सिंहासन कोमल मखमली चादर से ढका था और यमुना की शीतल बयार से शीतल था। सखियों ने युगल को सिंहासन पर बैठाकर वृन्दा के भंडार से लाए पान-सुपारी, शीतल जल और सुगंध परोसे। उन्होंने राधा-गोविन्द को रंगीन पुष्प-मुकुट, आभूषण और मालाएँ अर्पित कीं। मञ्जरियों ने उनकी सेवा में चामर डुलाए। सुखद चांदनी रात्रि, शीतल मनोहर वन और दीप्तिमान यमुनातट ने गोविन्द को अपनी प्रिया गोपियों के साथ रास-नृत्य मनाने की प्रेरणा दी।",
    685: "कृष्ण ने गोपियों के साथ एक-एक करके अपने रास-उत्सव के विभिन्न रूपों का आनंद लिया। उन्होंने वन-विहार किया, विचरण किया और वृत्ताकार नृत्य (चक्र-भ्रमण) किया। उन्होंने स्त्रियों का वृत्त-नृत्य (हंसक), युगल-नृत्य (युग्म-नृत्य), पुरुष-नृत्य (तांडव), स्त्री-नृत्य (लास्य) और एकल नृत्य किए। उन्होंने स्व-रचित गीत गाए, प्रेम-भाव से नृत्य किया, हँसी-मजाक किया और जल में क्रीड़ा की।\nवृन्दावन का वन चांदनी में मनोहर रूप से दमक रहा था और कृष्ण की उपस्थिति से वसंत की छटा के साथ खिल उठा था। पत्तों की सरसराहट, भौंरों की गुंजार, कोकिलों का कोमल कूजन सुनकर और मोरों का मदमाता नृत्य देखकर कृष्ण सखियों के साथ क्रीड़ा करने के लिए प्रेरित हुए। कृष्ण ने अपनी वंशी के स्वरों से अपनी इच्छाएँ प्रकट कीं। गोपियों ने बार-बार कृष्ण के नामों का गान करके सहमति दी।\nकृष्ण ने कहा—'हे मेरी प्रियतमाओं! मैं आपके साथ उस आकर्षक वन में क्रीड़ा करना चाहता हूँ, जो प्रस्फुटित पुष्पों से भरा है और मनोहर चांदनी में चमक रहा है।'\nगोपियों ने उत्तर दिया—'हे कृष्ण, कृष्ण, कृष्ण, कृष्ण! हे प्रियतम, ऐसा ही हो!' \nकृष्ण और सखियाँ उठकर मधुर स्वरों में कोमल गीत गाते हुए वृक्षों और लताओं के नीचे बने निकुंजों में विचरण करने लगीं।",
    686: "कोकिलों के प्रेम-पूर्ण कूजन ने सबके कानों को शांत किया। मधु से भरी माधवी-पुष्पों की सुगंध लिए कोमल दक्षिणा-पवन ने वातावरण की मिठास बढ़ा दी। मदमाते युवा भौंरों के झुंड मल्लिका-लताओं पर अर्ध-विकसित पुष्पों का मधु पीते हुए विचर रहे थे। उनकी जोरदार गुंजार वसंत-ऋतु के शंख-ध्वनि के समान लग रही थी। प्रेम-विह्वल हंस और पुकारते सारस अनेक सरोवरों में आनंद से चक्कर लगा रहे थे। प्रस्फुटित कमल-समूहों में भौंरे प्रेममय रूप से इधर-उधर उड़ रहे थे।",
    690: "सिंहिनी से भी अधिक सुंदर कृश कटि वाली गोपियाँ श्याम के निष्कलंक गुणों का मधुर स्वरों में गान कर रही थीं। जब श्याम ने पुष्प-अलंकरण के बहाने गोपियों को दुलार किया, तो उनकी इच्छाएँ जाग उठीं कि वे एकांत स्थान में उनके साथ अनियंत्रित प्रेम-लीलाएँ करें।",
	
    691: "विचरण करते समय कृष्ण कभी-कभी चंद्रमा या लताओं के विषय में अपनी स्वयं-रचित रचनाएँ गाते थे। सखियाँ उत्तर में उन्हीं उपमानों का प्रयोग करके राधा-माधव के प्रेम की महिमा करती थीं।",
    692: "गोपियों ने गाया—'आकर्षक चंद्रमा हमें अपार सुख देने के लिए प्रकट हुआ है। चंद्रमा की सुंदरता सभी आकर्षक युवतियों के मनोहर नेत्रों को आनंदित करती है और उसकी पत्नियों, ताराओं के विरह-भाव को दूर करती है। चंद्रमा रात्रि में खिलनेवाले कुमुदों के हृदयों को सजीव करता है।'\nश्याम और गोपियाँ वृन्दावन के शांत और सुखद वन में विचरण कर रहे थे। श्याम ने अपने लीलामय स्पर्श से लताओं और मुस्कुराती प्रियाओं को रोमांचित कर दिया। भौंरों की गुंजार के साथ कृष्ण और सखियाँ शीघ्र ही वंशीवट-वृक्ष के नीचे के चबूतरे पर पहुँचे।",
    693: "कृष्ण गोपियों के साथ बैठ गए और बहती हुई यमुना को निहारने लगे, जो भगवान को देखकर अत्यंत प्रसन्न थी। यमुना ने अपनी सतह के फेन से कृष्ण पर मुस्कान बिखेरी और पक्षियों के कूजन से उन्हें गीत सुनाया। उसकी सभी इंद्रियाँ कृष्ण से मिलन की अभिलाषा से व्याकुल थीं। उसने कृष्ण के स्पर्श का सुख पाने के लिए अपनी तरंग-रूपी भुजाएँ फैलाईं। श्याम को देखकर उसके लाल कमल-नेत्र आनंद से खिल उठे। श्याम की सुगंध को सूँघने के लिए मगरमच्छ उसकी उठी हुई नासिका के रूप में प्रकट हुए। कृष्ण की गंभीर वाणी और वंशी-ध्वनि सुनने के लिए उसके भँवर-कान व्याकुलता से घूम रहे थे।\nकृष्ण, यमुना की सुंदरता की प्रशंसा करते हुए विहार करना चाहते थे। उठकर श्याम अपनी प्रिय गोपियों के साथ नदी के तट पर चल दिए। यमुनाजी ने अपनी हाथ-रूपी तरंगों से बार-बार उनके चरण-कमलों को कमल-पुष्प अर्पित किए, मानो उनके चरणों को छूकर आदरपूर्वक प्रणाम कर रही हों।",
    694: "कृष्ण यमुनातट पर गोपियों के साथ आनंदित हुए, जहाँ की रेत शीतल थी और जल से आती पवन प्रस्फुटित कमलों की मधुर सुगंध लिए हुए थी।",
    695: "पूर्णिमा के चंद्रमा की किरणों के नीचे यमुनातट कुट्टित कपूर के समान श्वेत दिख रहा था। रेतीले तट कालिंदी की तरंगों से पवित्र और कमल-सुगंधित पवन से आलिंगित थे। दामोदर अपनी सुंदर गोपियों के समूह के साथ क्रीड़ा के उपयुक्त स्थान की खोज में इधर-उधर विचर रहे थे।",
    698: "अपनी मेघ-समान कांति चारों ओर फैलाते हुए श्यामसुंदर स्थिर बिजली के समान चमकती हुई मृग-नयन गोपियों के साथ यमुनातट पर विचर रहे थे। कृष्ण के कुण्डल झूल रहे थे, मंदार-पुष्प की माला चमक रही थी, कटि-बंध और नूपुर झंकृत हो रहे थे और कंधों से चादर खिसक रही थी।",
    699: "बड़े उत्साह से कृष्ण ने गोपियों के साथ अपनी आनंदमयी नृत्य-लीलाएँ आरंभ कीं। कृष्ण अपनी भुजाओं को दो गोपियों के बाएँ-दाएँ कंधों पर रखकर पूर्ण गति से घूमते थे। फिर वे उन दोनों को एक साथ आलिंगन करते थे। तब कृष्ण दोनों गोपियों के बीच स्थान बनाकर शीघ्र ही उनके पीछे चले जाते थे। एक गोपी से अपनी भुजा हटाकर कृष्ण दूसरे के कंधे का सहारा लेकर फिर से उनके सामने आने के लिए चक्कर लगाते थे।",
    700: "कृष्ण ने गोपियों के जोड़ों के बीच तीव्रता से घूमकर और उन्हें आलिंगन करके असीम आनंद का अनुभव किया। चक्कर लगाती गोपियों और कृष्ण के एकाकी श्याम शरीर के संयोग ने चमकती चांदनी और अंधकार के मिश्रण, बिजली और घनघोर मेघों, चम्पक और नील-कमल, तथा स्वर्ण और इंद्रनील के संयोग की सुंदरता को पराजित कर दिया।",
    701: "कृष्ण ने नर्तकियों के बीच खड़ी राधा के चारों ओर एक छोटे वृत्त में नृत्य किया। तब कृष्ण ने अपने वृत्त की परिधि बढ़ाकर शेष गोपियों के चारों ओर नृत्य किया। अपनी नृत्य-लीलाओं का आनंद लेते समय कृष्ण, गोपियों के वृत्त-रूपी रत्न-मंजूषा में दो धागों से मुक्त इंद्रनील-हारों के समान प्रतीत हो रहे थे।",
    703: "वहाँ अनेक गायक, मृदंग-वादक, वीणा और वंशी-वादक प्रसन्नतापूर्वक बजा रहे थे। करताल-निपुण ताल धारण किए थे। नाट्य-कला की मूर्तियाँ और संगीत की उपनिषदें, मुस्कुराते कमल-मुख और आश्चर्य की दृष्टि लिए रास-लीला में उपस्थित थीं। श्रेष्ठ नर्तकियों ने लोक, मिश्र और शुद्ध शैलियों में अपनी निपुणता प्रदर्शित की। उन्होंने संगीत के सभी रहस्यों और लालित्यपूर्ण चेष्टाओं में नैपुण्य दिखाया, जैसे कवि साधारण शब्दों को गीतों में बदल देता है। मार्ग (ब्रह्मा द्वारा स्थापित नियमों के संगीत) और देशी (क्षेत्रीय) दो प्रकार के गीत हैं। चच्चत्पुट से आरंभ होने वाले पाँच तालों सहित मार्ग-गीत चौंतीस प्रकार के हैं और देशी गीत चालीस प्रकार के।\nबोल का पाठ अत्यंत आकर्षक सुनाई दे रहा था: थैया थथैया थथा-थै थथैया! थै-थै-थै-थै-थै थथै-थै थथै था! थैया-थैया थथा-थथा थैया, थैया-थैया तिगदा थथैया। पाठ के बाद ताल-धारकों ने अपने हाथों में करताल लेकर उन्हें बाएँ, दाएँ, ऊपर, नीचे घुमाया और सप्तक के सात स्वरों के बावजूद एक आकर्षक नवीन अष्टम-स्वर गाया। उन्होंने बोल के साथ या बिना बोल के विभिन्न गति से वादन किया। वादकों द्वारा अपने हाथों से मृदंगों के किनारों पर प्रहार से उठी प्रबल ध्वनि से उनके होंठ और कंठ किसी अन्य वाद्य के समान काँपने लगे। महिला गायिकाएँ वाद्यों की ध्वनि की ओर कान लगाकर आकर्षक रूप से चमक रही थीं, क्योंकि वे उचित रागों को पूर्ण रूप से कंपित कर रहे थे।",
    707: "वायु से स्पर्श किए तमाल-वृक्ष की शाखाओं पर लटकती स्वर्ण-लताओं के समान गोपियाँ सुंदर दिख रही थीं। थकी हुई गोपियों से आलिंगित कृष्ण, आनंद-मूर्तियों द्वारा आलिंगित संयोग-रस की संघनित मूर्ति प्रतीत हो रहे थे। एक गोपी, जिसके हार झूल रहे थे, कानों में कमल-कलिका-कुण्डल और पहनावा सुंदर था, ने अपनी बाईं भुजा कृष्ण के कंधे पर रखी। उसकी कटि-मेखला और नूपुर झंकृत हो रहे थे, और वह धीमे, कलात्मक ढंग से गाती और नृत्य करती थी। कृष्ण उसकी चाल का अनुसरण करते हुए नृत्य और गान कर रहे थे।\nएक प्रेम-उद्दीप्त कमल-नयनी गोपी ने कृष्ण की स्वर्ण-धोती का छोर अपने कमल-हाथ से पकड़ा और उसे तथा कृष्ण को खींचती हुई आगे-पीछे नृत्य करने लगी।",
    714: "कोमल लता-समान भुजाओं वाली मृग-नयनी कन्याएँ कृष्ण के प्रत्यक्ष सेवा के आनंद से प्लावित होकर उनके प्रति इच्छा-रूपी नदी में तैर रही थीं। गोपियों के उल्लास में उनकी अलकें, चोली और वस्त्र अनजाने में शिथिल हो गए थे।",
    749: "जब कृष्ण ने राधा के वक्षस्थल को स्पर्श करना चाहा, तो उन्होंने अपनी भुजाएँ सामने क्रॉस कर लीं। जब कृष्ण ने उनकी ओर कमल-नाल फेंका, तो राधा ने उसे टालने के लिए अपनी भुजाएँ उठा लीं। जब श्याम ने उनके मधुर कमल-मुख को सूँघना चाहा, तो किशोरी ने अपने हाथों से मुख ढक लिया। राधा-माधव की अंतरंग सखियों ने उनकी अद्भुत प्रेम-लीलाओं का पूर्ण रस लिया।",
    751: "एक सहानुभूतिपूर्ण सखी ने एक दुखी सखी से कहा—'तुम उत्साह से जल में खेल रही हो। परंतु तुम्हें कमल तोड़ना बंद कर देना चाहिए। क्या तुम नहीं देख रही हो कि कमल के नालों के काँटों से तुम्हारे कोमल अंग आहत हो गए हैं और कुछ मदमाते भौंरों ने तुम्हारे होठों को काट लिया है?'",
    774: "श्री गौरचंद्र के कंधे सिंह के समान सुदृढ़ हैं, और उनके सुंदर गाल मधुर मुस्कान से सुशोभित हैं। उनका अलौकिक शरीर अनेक आश्चर्यजनक रसमय रूपांतरणों से युक्त है। उनकी कांति प्रस्फुटित स्वर्ण-कमल से भी अधिक सुंदर है, और उनका शरीर राधा और माधव के मिलन का स्थान है। वे प्रभु गौर हम पर प्रसन्न हों।",
    775: "श्री गौरचंद्र के भक्तों को मैं विनम्र प्रणाम करता हूँ, जो भक्ति-रस के सागर में क्रीड़ा करनेवाले मकरों के समान हैं। उन्होंने मृत्यु के पाश के भय पर विजय प्राप्त कर ली है और मुक्ति की नदी की उन्हें कोई चिंता नहीं है।",
    776: "पहले यह निश्चित कर लेने के बाद कि राधा और कृष्ण जाग चुके हैं, श्रीमती की किंकरियों ने बिना किसी संकोच के द्वार खोला और शांत, कोमल कदमों से कुटिया में प्रवेश किया।",
	
    402: "वर्षा-ऋतु की देवी ने दिव्य आनंद के विभिन्न लक्षण प्रकट किए। पृथ्वी ने प्रस्फुटित मालती-पुष्पों के समूहों से मधुर मुस्कान बिखेरी। वन की अलकें कदम्ब-पुष्पों के रूप में खड़ी हो गईं और आकाश ने मूसलधार वर्षा के रूप में अश्रु बहाए। इन तीनों ने आनंदमय वर्षा-वन में अपना स्नेह फैलाया।\nवर्षा-ऋतु के ललाट पर तिलक के रूप में इंद्रधनुष था और उसकी श्याम अलकों को स्वर्ण-केतकी पुष्प सुशोभित कर रहे थे। उसके गले में लटकती निर्मल बालक-पुष्पों की माला उसके उन्नत वक्षों के नव-निर्मित उभरे मेघों पर टिकी हुई थी। इस प्रकार वर्षा-ऋतु की देवी ने कृष्ण के मन को उद्दीप्त किया।\nवर्षा-वन में मेघ-गर्जन गूँज रहा था। चातक पक्षियों ने उसे सुना और वर्षा को बुलाने के लिए करुण स्वर में कूजने लगे। उत्तर में गर्जते मेघ चातकों को सांत्वना देते प्रतीत हुए, मानो कह रहे हों—'शोक मत करो, मैं वर्षा की धाराएँ बरसाऊँगा।' गर्जनशील मेघ घूमती चक्की के समान सुनाई दे रहे थे, जो मनुष्य के गर्व को पीस डालती है। मेघों की गर्जन मृदंग की गंभीर मधुर ध्वनि के समान गूँज रही थी, जो मोरों को उन्मत्त नृत्य करने की प्रेरणा देती थी। वह उन मंत्रों के समान थी, जो विरहिणी स्त्रियों के प्राणवायु को जीवित करते हैं।\nवन ध्वनियों की सिम्फनी से भरा था। हर ओर दात्यूह पक्षी और श्वेत सारसों के झुंड पुकार रहे थे, मेंढक टर्रा रहे थे और मोर 'केका, केका' करके विलाप कर रहे थे। मेघ गरज रहे थे, वर्षा-बूँदें टिपटिप-टिपटिप की ध्वनि कर रही थीं और जल-धाराएँ 'झपट, झपट' कहकर कलरव कर रही थीं। ये मधुर मधुर ध्वनियाँ प्रियतम का आनंद लेने के बाद स्त्री को सुलाने के लिए उपयुक्त थीं।\nऋतु के पोषक जल ने वृक्षों और उद्यानों को सुंदर बना दिया। आम्र-वृक्षों के प्रचुर पक्के फलों ने वन के मध्य भाग को स्वर्ण-आभा से रंग दिया। पक्के जामुन के वृक्षों ने श्याम-आभा उत्पन्न की। वृक्षों के परे केतकी वृक्ष की नुकीली सूई-जैसी पत्तियों और पुष्पों से उत्पन्न पीली कांति थी। इन सब रंगों से वृन्दावन के उद्यान चित्रित चित्र के समान सुंदर दिख रहे थे।",
    523: "'राधारानी वृषभानु-कुल के सागर से उत्पन्न अमृत की सुंदर अर्धचंद्रा हैं। राधा के मनोहर माँग-सिंदूर की रेखा मधुर अमृत-नदी के समान दिखती है। मेरी प्रार्थना है कि मेरा मन सदा राधिका पर स्थिर रहे, जो कृष्ण का दिव्य स्वरूप और गुण सुनते ही प्रेम से स्तब्ध हो जाती हैं। किशोरी अपनी सुंदर वेणियों को कोमल, सुगंधित जूही-पुष्पों से बाँधती हैं। राधा के बड़े कमल-नेत्र, काम-विकार से चंचल, खंजन पक्षियों की गतियों को लज्जित करते हैं।\n'राधा की चाल राजसी मदमाते गजराज की गति से भी अधिक लालित्यपूर्ण है। किशोरी के मधुर स्वर्ण-अंग स्वर्ण-चम्पक के दलों से भी अधिक मनोहर हैं। राधारानी की कोमल भुजाओं की स्वर्ण-लताएँ रत्न-जड़ित बाजूबंदों और चूड़ियों से सुशोभित हैं। राधा के दिव्य स्वरूप की अद्भुत सुंदरता सदा व्रज की सभी सुंदर कन्याओं को मोहित करती है।\n'राधारानी का धीरे-धीरे मुस्कुराता मुख पूर्ण चंद्रमा की शोभा को जीत लेता है। संघनित नवीन माधुर्य राधा के सुंदर विस्तृत कटि-प्रदेश के रूप में प्रकट हुआ है, जो घुँघरुओं की डोरियों से बँधा है। एक अद्भुत रंगीन चोली राधिका के सुंदर स्वर्ण-कुम्भों के उन्नत वक्षों को छिपाए हुए है। राधा के चमकते लाल अधर श्याम के मन में उस अमृत का रस लेने की गहरी लालसा भर देते हैं। राधारानी की सुडौल ठुड्डी कस्तूरी के मनोहर बिंदु से सुंदर रूप से विभूषित है। राधा की सुंदर नासिका से स्वर्ण और रत्नों से जड़ा एक बड़ा दीप्तिमान मोती लटकता है।\n'राधिका का आनंदमयी दिव्य स्वरूप सौंदर्य-सागर का सार है, जो श्याम के प्रति प्रेम की तरंगों से उठता है। कृष्ण के नेत्रों का हिरण राधा के मनोहर नाभि-नामक अमृत-कुएँ में गिर गया है। राधा के दिव्य शरीर को लाल साड़ी घेरे हुए है, जो उनके दीप्तिमान कुण्डलों, हारों और नूपुरों से और भी अधिक चमकदार हो गई है। जब भी किशोरी वन-मार्ग पर गोकुलचंद्र के चरण-चिह्न देखती हैं, तो वे प्रेमावेश से काँप उठती हैं। जिनके हृदय व्रज-रस का अमृत पान करने के लिए लालची हैं, उन्हें वृन्दावन के भावों के पारखी विद्वानों के वर्णन के अनुसार राधिका के अद्वितीय सुंदर दिव्य स्वरूप का गुणगान करना चाहिए।",
	
    687: "पक्षियों ने चारों दिशाओं में आनंद से 'जय! जय!' का गान किया। लताएँ मुस्कुराईं और वृक्षों के पत्ते खड़े हो गए। अपनी प्रियतमाओं से वार्तालाप करने के लिए उत्सुक हिरण समूहों में खड़े होकर दृश्यों को देखकर विस्मित हो रहे थे। आनंदमयी पुष्पों ने अपने अमृत-अश्रुओं की बूँदों से भूमि को गीला कर दिया। कृष्ण पृथ्वी पर चलते हुए नवीन मेघ के समान प्रतीत हो रहे थे। अपने दीप्त चंद्रमुख पर मधुर मुस्कान धारण किए श्रीहरि ने, अपने चारों ओर बिजली की माला के समान घिरी सुंदर मुख वाली गोपियों के साथ विहार करते हुए, विश्व को आनंद की तरंगों से भर दिया।\nदामोदर पैरों तक लटकती सुगंधित माला धारण किए, भौंरों की गुंजार-पवन से हिलती हुई, वृक्षों और लताओं के बीच मधुर गीत गाते हुए और अपनी वंशी बजाते हुए चल रहे थे। युवा गोपियाँ श्याम के साथ धीरे-धीरे चलती थीं और प्रेम-आकुलता से भरी अपनी मधुर कंठध्वनि में उत्साहपूर्वक उनके चरित्र की प्रशंसा करती थीं। माधव अपने नख से पत्तों पर प्रेम-संदेश लिखकर अपनी प्रिय सखियों को देते थे।\nकृष्ण ने स्वयं सर्वोत्तम पुष्प, पत्ते और लताएँ चुनीं। फिर कृष्ण ने सखियों को सजाने के लिए चोली, बाजूबंद और अन्य आभूषण बनाने की अपनी प्रतिभा दिखाई। माधव ने सखियों के चरण और हाथ पुष्प-पराग से रंग दिए। क्षण भर में ही कृष्ण ने मालती-पुष्पों के हार, कदम्ब के ललाट-आभूषण, स्थल-कमल के कुण्डल, कुंद-पुष्प के गले के हार और बकुल, केसर तथा नाग-केसर के कटि-बंध बना दिए। श्याम ने गोपियों की अलकों में पुष्प-पराग उड़ाया और उनके गालों को लोध्र-पराग से रंग दिया।\nगोपियों ने बदले में कृष्ण के कानों में केसर-पुष्प, अलकों में केतकी-पुष्प और वक्ष पर मालती-पुष्प लगाए। एक गोपी ने कृष्ण की पगड़ी पर अशोक-पुष्प रखे। दूसरी गोपी ने उन्हें जूही-पुष्पों के कंगन-बाजूबंद अर्पित किए और बकुल-पुष्पों की डोरी से उनकी कटि बाँधी।\nमाधव व्रज की सुंदर कन्याओं के साथ अंतरंग लीलाओं का रस लेने के लिए वन के एकांत स्थान पर चले गए। जब गोपियाँ प्रेमावेश में खो गईं, तो वृक्षों में कोकिलों के कूजन और मदमाते भौंरों की गुंजार गूँजने लगी। सुंदर गोपियाँ, जिनकी दीप्तिमान स्वर्ण-कांति चांदनी के गर्व को जीतती थी, श्वेत-कमल के महीन स्वर्ण-पराग से प्रसन्नता से कृष्ण के शरीर को छिड़कने लगीं। फिर चूड़ियाँ झंकृत करती गोपियों ने प्रेम का एक नवीन संग्राम आरंभ कर दिया।\nकृष्ण ने गोपियों पर पुष्प-बम फेंककर प्रत्युत्तर दिया। यद्यपि गोपियों ने चारों ओर से पुष्प-पराग की वर्षा की, तथापि कृष्ण ने सरलता से उन्हें पराजित कर दिया। तोते और अन्य पक्षियों ने 'जय! जय!' पुकारकर कृष्ण की विजय की घोषणा की। वीर-गर्व से भरे कृष्ण ने राधिका और उनकी सखियों पर पुष्प-बमों की बौछार की। राधा ने कृष्ण को वश में करने के लिए अपने क्रोधित कटाक्षों की सेना संभाली। राधा के पालतू तोते बार-बार कूजते रहे—'हम जीत गए! हम जीत गए!'\nप्रत्येक क्षण कृष्ण नई-नई आनंद-लीलाओं में लगे रहते थे। राधा ने सुगंधित, मधु-भरे पुन्नाग-पुष्प तोड़ने शुरू किए। कुछ भयभीत भौंरे पुष्पों से फुर्र होकर निकले, जिससे राधा ने शीघ्र ही अपना कमल-हाथ खींच लिया और भय से काँप उठीं। कृष्ण ने कहा—'अरे-अरे! यह तुम्हारे लिए उचित दंड है, क्योंकि तुम पुन्नाग (श्वेत कमल अथवा श्रेष्ठ पुरुष) चुरा रही हो।'\nराधिका ने लज्जा से सिर झुकाया और श्याम की हँसी पर मुस्कुराईं। राधिका पैरों की अँगुलियों पर खड़ी होकर पेड़ की ऊँची डाल पर रंगीन पुष्प तोड़ने के लिए अपनी लता-समान भुजाएँ फैलाईं। राधा का निचला वस्त्र खिसकने लगा। तब राधा ने घबराकर चारों ओर देखा। कृष्ण ने अवसर का लाभ उठाकर चुपचाप राधा के पीछे आकर उन्हें उठा लिया। राधा शर्म से लाल हो गईं।\nएक गोपी, आपदा का बहाना करते हुए, बोली—'मेरी आँखों में कुछ पराग गिर गया है!' अपने कमल-हाथों से आँखें रगड़ने का नाटक करते समय उसकी चूड़ियाँ झंकृत हुईं। कृष्ण, हँसते हुए और चिंता की दृष्टि से, शीघ्र ही उसके पास पहुँचकर बोले—'आओ, देखूँ!' पराग उड़ाने के बहाने कृष्ण उसके मुख के पास गए और कोमलता से उसकी आँखों का चुंबन किया। राधा ने वृक्ष की उन शाखाओं पर पुष्प तोड़ने का प्रयास किया, जो उनकी पहुँच से परे थीं। वृक्ष ने अंतरंग मित्र की भाँति व्यवहार करते हुए स्नेहपूर्वक अपनी शाखाएँ झुका दीं, ताकि राधा सरलता से पुष्प तोड़ सकें।",
	
    688: "वन में मंदार, हरिचंदन, अगुरु, संतान, चम्पक, पुन्नाग, बकुल, बक, कुरुवक, अशोक, केतकी, जूही, जूही-जाति का पुष्प, माधवी, पाटल, जवा, सेफालिका, मल्ली, मुचुकुंद, कुंद, नवमल्लिका और स्वर्ण-यूथिका जैसे अनेक पुष्पवृक्ष थे। अमरूद, अनार, नारियल, कटहल, केला, आम्रातक, संतरा, रुचक, मधुक, शमीक, कक्कोल, कोविदार, आमलकी, लौंग, लवली, काम-रंग, जम्बी, सल्लकी, करुणालेबु, इमली और कुब्जक के फलों से लदे वृक्ष भी थे।\nफल-पुष्प धारण करने वाले और केवल फल धारण करने वाले सभी वृक्षों के आधार रत्न-खचित भूमि से घिरे थे और विभिन्न प्रकार की लताओं से आलिंगित थे। सुडौल, घनी पत्तियों वाले वृक्षों ने वन की भव्यता बढ़ा दी। वृक्षों के शिखर मरकत-हरे, शाखाएँ स्वर्ण-वर्णी, नव-पल्लव माणिक्य-लाल, पुष्प-कलिकाएँ प्रवाल के समान, प्रस्फुटित पुष्प हीरे के समान और फल वैदूर्य-रत्न के समान थे। वृक्षों के समूह चारों दिशाओं में तेज बिखेर रहे थे।\nवृक्ष रत्न-खचित रेत और गोवर्धन पर्वत से तीव्र उतरती नदियों में प्रतिबिंबित हो रहे थे। उत्तुंग वृक्षों ने सभी प्रकार के पक्षियों से मित्रता की। वर्ष भर वृन्दावन के वृक्ष कल्पवृक्षों की भाँति सभी की इच्छाएँ पूर्ण करते रहे।\nवन अपनी श्याम भूमि, वृक्षों के नीचे अनेक मंडपों, रत्न-मंडपों और रत्न-भूमि से अद्भुत दिख रहा था, जिसकी सतह से रत्न-अंकुर स्वतः उत्पन्न होते थे। वृन्दावन ब्रह्मा द्वारा निर्मित नहीं है; यह राधा-माधव का सनातन दिव्य धाम है। भूमि पर पड़े मरकत-रत्नों की प्रचुरता के कारण वन के कुछ भाग हरे कालीनों से ढके प्रतीत होते थे। हिरण उन 'कालीनों' को कोमल घास के अंकुर समझकर उत्सुकता से वहाँ दौड़ते थे।\nमाणिक्य-रत्नों के टुकड़े वन के छोटे-छोटे क्षेत्रों को ढकते थे। शीत ऋतु में चामरी हिरणियाँ उन्हें प्रातःकालीन सूर्य की उष्ण किरणें समझकर उन टुकड़ों पर खड़ी रहती थीं। कुछ क्षेत्र सर्वोत्तम स्फटिक से ढके थे। ग्रीष्म ऋतु की गर्मी से पीड़ित सांभर वहाँ चंद्रमा की शीतल किरणें समझकर एकत्र होते थे। कुछ भाग नीलमणि से आच्छादित थे। उल्लू, उदीयमान ग्रीष्म-सूर्य की किरणों से भयभीत होकर उसे अंधकार समझकर वहाँ शरण लेते थे।\nछहों ऋतुओं को प्रिय वन की देवी (वनलक्ष्मी) ने अपनी सुंदरता से कृष्ण की सेवा की। उन्होंने वसंत के पुष्प-कलिकाओं के रूप में अपने गले में मोती की माला धारण की। उन्होंने ग्रीष्म की मल्लिका-पुष्पों से अपनी सजावट की। वर्षा ऋतु में उन्होंने कदम्ब-पुष्पों के गुच्छों के रूप में अपने वक्षों को धारण किया। शरद में उन्होंने कमल-गुच्छों से मुस्कान बिखेरी। शिशिर ऋतु में उन्होंने लोध्र-पुष्पों को कुण्डलों के रूप में पहना। हेमंत ऋतु में दमनक-पुष्पों की डोरी से बँधी मधुकर (भौंरों) की वेणी के साथ वे अत्यंत मनोहर दिख रही थीं।\nवन के वृक्षों ने कृष्ण की पूजा के लिए अनेक सामग्री प्रदान की। ओस की बूँदें कृष्ण के चरण-प्रक्षालन थीं, नवीन घास के अंकुर अर्घ्य, मधु आचमन, उत्तम सुगंधियाँ चंदन, श्रेष्ठ पुष्प पुष्पांजलि, चढ़ती भौंरों की पंक्ति धूप और सुंदर कलिकाएँ दीपक थीं। भूमि पर गिरे पक्के फलों से वृक्षों ने कृष्ण को नैवेद्य अर्पित किया।\nचंचल पवन रूपी नृत्य-गुरु से विभिन्न चालें सिखाकर लताएँ कृष्ण के सम्मुख लयपूर्वक झूम रही थीं। भौंरे पार्श्व-स्वर गुनगुनाते थे और लताएँ अपने पत्ते-रूपी हाथ फैलाकर गीतों के अर्थ प्रकट करती थीं। उनके शरीर के विभिन्न अंग आनंद से फूल उठे। वक्ष-रूपी बड़े कलिका-गुच्छों ने अपनी लज्जा और विनम्रता प्रकट की, जबकि प्रस्फुटित पुष्पों ने आनंद की मुस्कान व्यक्त की। एक लज्जित लता ने अपने पत्ते-रूपी हाथों से अपनी पुष्प-मुस्कान ढक ली। दूसरी लता आनंद से विह्वल होकर मधु के अश्रु बहा रही थी। एक लता ने पराग-रूपी वस्त्र से अपने सुंदर वक्ष-रूपी कलिका-गुच्छों को छिपा लिया।\nदूसरी लता ने अपने शरीर से भौंरों के झुंड को झटक दिया। कुछ लताओं ने कोकिलों के कूजन और पवन में हिलते अपने पत्तों से कृष्ण को पुकारा—'यहाँ आओ, यहाँ आओ!' अर्ध-विकसित पुष्पों से मुस्कुराकर लताओं ने अपने आंतरिक आनंद और कृष्ण से मिलन की उत्सुकता व्यक्त की।\nकुछ लताओं ने हरि को देखा और फिर कठोर स्वर में कठफोड़वों के जोरदार शब्द से पुकारा। उन्होंने काले भौंरों की घुमावदार पंक्तियों से भौंहें चढ़ाईं। उन्होंने अपने पुष्पों से क्रोध-मिश्रित मुस्कान प्रकट की। नवीन पत्ते फड़फड़ाकर उन्होंने अस्वीकार व्यक्त किया और पक्षियों की चहचहाहट से कृष्ण को उलाहना दिया।\nश्याम ने लताओं द्वारा प्रकट प्रेम को स्वीकार किया और उन वृक्षों को आनंद प्रदान किया, जिन्होंने अपने फलों और पुष्पों से निपुणता से उनकी सेवा की। कृष्ण वृन्दावन में इधर-उधर विचरते समय अपने चरण-कमलों से रत्न-भूमि और नवीन घास के अंकुरों को स्पर्श करके उन्हें संतुष्ट करते थे।",
	
    704: "गोपियों ने उत्साह से बोल उच्चारित किए—'थै-थै थो-थो तिगड़ा-तिगड़ा थो, थथै-थो थथै-था।' उन्होंने भूमि पर पैर ठोंके, भुजाएँ आकाश में उठाईं और वृत्त की परिधि पर नृत्य करते हुए कलात्मक रूप से बाएँ से दाएँ घूमीं। गोपियों ने गीतों के शब्दों को चित्रित करने वाली हस्त-मुद्राएँ बनाकर अपने गायन के रस को बढ़ाया। उनके चरण ताल रखते थे और लालित्यपूर्ण घूमते गले स्वरों और तालों को व्यक्त करते थे। लय के अनुसार दाएँ-बाएँ घूमती चंचल दृष्टि से गोपियाँ कृष्ण की ओर प्रेमपूर्ण दृष्टि से देखती थीं। वे अपने सभी अंगों में समान उत्साह के साथ सब कुछ एक साथ करती थीं।\nगोपियों ने हाथ आकाश में फैलाए, चूड़ियाँ झंकृत कीं और सावधानी से पैर रखकर बिजली की गति से आनंद से घूमने लगीं। रास-वृत्त के केंद्र में खड़े कृष्ण से निकलती सौंदर्य-तरंगों की डोर पर पिरोई हुई सुंदर गोपियाँ बिना विश्राम के अपने चरण बाएँ-दाएँ चलाती रहीं। उन्होंने 'धी धी धी धी तधी धी' की ताल पर आनंद से पैर ठोंके, जबकि उनके शरीर लय में झूलते थे और रत्न-नूपुर झंकृत होते थे। आनंद में नृत्य करते हुए अपनी भुजाएँ घुमाने से उनका वक्षस्थल ढकनेवाला वस्त्र खिसक गया। वे सुंदर रूप से बाएँ-दाएँ घूमती थीं, बिना इस भय के कि उनकी कृश कटि दो टुकड़े हो जाएँगी।\nवीणा और वंशी-वादक सटीक कदमों से आनंद से नृत्य कर रहे थे। गायक और ताल-धारक गीत की ताल पर चलते थे। वादक जोर से बजाते और एक साथ नृत्य करते थे। ऐसा प्रतीत होता था मानो उनके शरीर धागे से नृत्य करती गोपियों के शरीरों से बँधे हुए हों।\nजब कृष्ण रास-वृत्त में चक्कर लगाते हुए बाएँ मुड़ते, तो गोपियाँ दाएँ मुड़तीं। और जब कृष्ण दाएँ मुड़ते, तो वे बाएँ। कृष्ण और गोपियों का भँवर-नृत्य अनंत था, जिसमें वे एक ही दिशा में या विपरीत दिशा में चलते थे। कृष्ण और नृत्य करती गोपियाँ घूमते दीपक द्वारा प्रकाशित आकृतियों के समान प्रतीत होती थीं, जिनकी छाया पहले एक ओर और फिर दूसरी ओर पड़ती थी, क्योंकि नील वर्ण कृष्ण और स्वर्ण-अंग गोपियों का संयोजन बार-बार अपनी स्थिति बदलता था।\nवृत्त के बाहर स्थित वादक गोपियों की गति के साथ समय रखकर भगवान की लीला में सहायता करते थे। किसी प्रकार गीत मोड़ लेते थे। गोपियाँ कृष्णचंद्र नामक चंद्रमा के बारे में गाती थीं, जो सभी आनंद की मूर्ति है। उत्तर में कृष्ण उस सुंदर चंद्रमा की महिमा करते थे, जो रात्रि को सुखद किरणों से भर देता है।\nजैसे-जैसे लय बढ़ती और गोपियाँ अपने चरण अधिक जोर से ठोंकती, उनके कमल-चरणों से स्वेद की बूँदें रेत पर टपकते मधु के समान गिरतीं। आश्चर्य की बात है कि नृत्य के प्रचंड वेग से रेत का एक भी कण नहीं उड़ा। क्या रेत के सभी कण आनंद से स्तब्ध हो गए थे? गोपियों के तिलकों पर प्रतिबिंबित कृष्ण की नृत्य-मूर्ति, सिर आगे-पीछे हिलाती गोपियों की लय पर झूलती थी। गोपियाँ कृष्ण के प्रतिबिंब को संबोधित करती प्रतीत होती थीं—'हे कुशल नर्तक! आपका नृत्य कभी भी रास-मण्डल में गोपियों के शानदार नृत्य की बराबरी नहीं कर सकता!'\nकुछ कमल-नयनी गोपियाँ, कृष्ण के आलिंगन के आनंद से पुलकित, नृत्य करती हुईं अपनी तीव्र लालसा व्यक्त करने के लिए एक विशेष राग जोर से गा रही थीं। उस राग को सुनकर संगीत के सभी देवता मूर्च्छित हो गए। एक गोपी ने मधुर गांधार ग्राम में, उचित जाति, श्रुति और गमकों सहित, पूर्ण भावना के साथ शुद्ध मधुर स्वर गाए। कृष्ण ने उसकी प्रशंसा में 'शाबाश, शाबाश' पुकारा। उसने कृष्ण को और प्रसन्न किया, बाईस श्रुतियों से अलंकृत सप्तक के सातों स्वरों को मुख्य अलंकारों सहित आलाप में प्रस्तुत करके।\nमृदंग लगातार 'ता धिक ता धिक-धिक' (अर्थ: स्वर्गीय नर्तकियाँ व्यर्थ हैं!) की ताल बजाते रहे। यह सुनकर स्वर्ग के नर्तक हर्ष से मुस्कुराए। यद्यपि प्रतिस्पर्धा की आलोचना करने वाले स्वर्गीय कलाकार, इस उलाहना को सुनकर आनंद से भर गए। अपनी चमकदार श्याम अलकों पर मोरपंख धारण किए मुकुंद ने राधा का आलिंगन करके रास-नृत्य पर प्रेम-अमृत की मूसलाधार वर्षा की। श्रीमती राधिका कला की देवी द्वारा उत्पन्न सिद्ध औषधि के समान प्रतीत होती थीं, जो पूर्ण संतोष देती और सब शोक हर लेती है। जब श्याम राधा के साथ आनंद से नृत्य करते थे, तो वे स्वर्ण-लता से आलिंगित तमाल-वृक्ष या बिजली चमकते मेघ के समान दिखते थे।\nकृष्ण के अद्वितीय सुंदर शरीर ने करोड़ों कामदेवों के गर्व को जीत लिया। राधिका के साथ नृत्य करते समय श्याम ने चुंबक की भाँति कामदेव के प्रेम-बाणों की लौह-नोकों को अपनी ओर खींच लिया। राधा कृष्ण की लय में चल रही थीं। गोपियाँ राधा के कुशल नृत्य को बढ़ाना चाहती थीं, परंतु गायन, नृत्य और वादन में राधा की निपुणता की बराबरी नहीं कर सकीं।\nराधा-माधव, आकर्षण, आनंद, उत्साह और एक-दूसरे से आगे बढ़ने की इच्छा से विह्वल, ग्रह-स्वर और षड्ज के प्रकारों के साथ आलाप गाते थे। राधा-माधव गमकों (कंपन) के साथ आरोह-अवरोह के सभी स्वर गाते थे। इससे विभिन्न रस उत्पन्न होते, अधिक गायन-नृत्य की प्रेरणा मिलती और चारों ओर मंगल फैलता। यह किसी भौतिक कला का प्रकाशन नहीं था।\nगीत के अंत से ठीक पहले लय धीमी होते ही कृष्ण ने उसे अंतिम स्वर (न्यास) से समाप्त किया, अपना कमल-हस्त (न्यास) बढ़ाकर राधिका के वक्षस्थल का स्पर्श किया। यद्यपि कृष्ण के चतुर व्यवहार से राधा उत्सुक हुईं, तथापि उन्होंने क्रोध का नाटक करते हुए अपने बाएँ कमल-हस्त से कृष्ण का हाथ हटा दिया।",
	
    705: "एक गोपी कृष्ण के सम्मुख नृत्य करती थी, जबकि दूसरी गोपी धीरे-धीरे आगे बढ़कर उसके साथ जुड़ गई। उसी प्रकार तीसरी, फिर चौथी गोपी जुड़ीं और शीघ्र ही कई गोपियाँ एक-दूसरे से जुड़ गईं। कृष्ण गोपियों की गोलाकार पंक्ति के बाहरी छोर पर आश्चर्य से देखते रहे।\nएक गोपी ने एक-एक करके बहुत से नृत्य-भाव प्रस्तुत किए। उसने कमल-नाल की मुद्रा में हाथ घुमाकर कमल की मुद्रा बनाई। इसी प्रकार उसने कमल-भ्रमर मुद्रा में तेजी से हाथ घुमाए। फिर उसने कमल-दर्पण मुद्रा, कमल-लिप्सा मुद्रा और अंत में कमल-प्रदर्शन मुद्रा में कमलों को निहारा। एक क्षण में ही उसने सभी मुद्राओं को संयोजित करते हुए दिखाया।\nउस सुंदर गोपी ने अपने कमल-हस्तों की मुद्राओं से पाँच प्रकार के कमलों के रंग, आकार, पंखुड़ियों की मुद्राएँ, परिभ्रमण और कटि-वलन प्रदर्शित किए। श्याम इन सब को मंत्रमुग्ध होकर देखते रहे। श्याम की ही प्रेरणा से गोपी इतनी निपुणता से नृत्य कर रही थी। इसके साथ ही वह आकर्षक श्लोक भी गा रही थी—'हे कमल-नेत्र! मैं शतपत्र (श्वेत कमल) के साथ क्रीड़ा करती हूँ।' जब गोपी ने नृत्य में अपने चरण उठाए, तो वे श्वेत-कमल के समान दिखे। उसके पैरों के नीचे का पराग श्वेत-कमल के अंतराल जैसा दिखा, और उसकी बायीं भुजा कमल के ऊपर शोभा पाती हुई बाँसुरी के समान दिखी। श्याम उस श्लोक की भावना को चित्रित करने वाले हाव-भाव देखकर हँसे।\nजब कृष्ण ने उस गोपी के मधुर गायन और नृत्य का आनंद लिया, तो दूसरी गोपी ने कृष्ण के सम्मुख प्रस्तुति दी। गोपी ने कमल-भौंरा, भौंरा-उड़ान (भौंरों का छिटकना) की मुद्राएँ बनाईं। फिर उसने भौंरे के घूमने और भौंरे के चुंबन की मुद्राएँ प्रस्तुत कीं। उसने गंध, रंग और कमलों की सुंदरता की मुद्राएँ भी दिखाईं। तदनंतर उसने हरि के लिए सुंदर गीत गाया—'ओ भौंरे, हमारा मन तेरे साथ खेलता है!' कृष्ण ने मुस्कुराकर उस नृत्य की प्रशंसा की।\nतीसरी गोपी ने श्याम के सम्मुख प्रस्तुति दी। उसने नृत्य में अपनी कमर झुकाई, सिर पीछे झुकाया, हाथों की मुद्राएँ बनाईं और अपने वक्षों को कसकर केंद्र में लाया। उसने कमर हिलाई, अपने मुख की कटाक्ष-दृष्टि से कृष्ण को अपनी मुद्राओं के भाव समझाए। उसने अपनी दृष्टि के साथ-साथ भाव-भंगिमाएँ प्रस्तुत कीं और एक गीत गाया।\nएक गोपी ने तमाल-वृक्ष की छाया में नृत्य किया, जहाँ पवन मीठे पराग से सुगंधित था। सफेद कमल का एक सुंदर हार, जिसकी डोरी नीलमणि के मोतियों से बनी थी, गोपी के गले से लटक रहा था। उसका स्वर्ण-वर्णी पहनावा झूलता था और उसके कानों में पुष्प-कुण्डल थे। कृष्ण उसके स्वर्ण-शरीर पर मकर-चिह्न देखकर मोहित हुए और उससे बोले—'यह देखो! तुम्हारी बाहें मेरे कंधों पर रखो।' कृष्ण के शब्दों का अर्थ था कि उसने अपने कमल-हाथ उनके कंधों पर रखकर नृत्य किया, जैसे प्रकाश-कंठी मयूर नृत्य करते हैं। गोपी ने उसी प्रकार किया।\nश्याम ने प्रेम-पुलकित होकर गोपी से एक सुंदर प्रश्न पूछा—'हे सुंदरी! क्या तुम व्रज में रहती हो? तुम्हारे घर पर वृक्ष, गाय और व्रज की मिट्टी हैं।' तब श्याम, उस गोपी को रास-वृत्त से बाहर ले जाकर उसकी ओर मुख करके खड़े हुए, और उसे उठाकर धीरे से प्यार से नृत्य करने लगे।",
}

QUOTE_HI = {
    14: "मोर, जो समय से अवगत हैं, जाग उठे हैं और अब अपनी प्रियाओं के विरह में करुणापूर्वक 'केका, केका' पुकार रहे हैं! वे केवल आपको जगाने आए हैं। क्या कोई बुद्धिमान व्यक्ति अपने कर्तव्यों के निर्धारित समय की उपेक्षा कर सकता है?",
    21: "राधा-माधव ने एक साथ अपने नेत्र खोले और एक-दूसरे को लीलापूर्ण दृष्टि से देखा। तथापि काम-वासना की उत्तेजना ने उनकी परस्पर दृष्टि भंग कर दी और उन्हें अत्यंत अप्रसन्न कर दिया।",
    31: "यह निश्चय करके कि राधा और कृष्ण जाग चुके हैं, मञ्जरियों ने निःसंकोच द्वार खोला और शांत भाव से शयन-कक्ष में प्रवेश किया।",
    39: "निद्रित कृष्ण को प्रसन्न करने के उत्सुक नर तोते, मन और हृदय को अमृत-पान के समान संतुष्ट करनेवाले मधुर शब्दों और अनेक सुंदर, आनंदपूर्ण वचन कहकर उन्हें जगाने का प्रयास कर रहे थे। पवित्र उल्लास की गहराइयों के विद्वान, आकर्षक मधुर शब्दों के प्रयोग में कुशल, प्रेम-चर्चा में तल्लीन और समय के निपुण ज्ञाता वे तोते कृष्ण को जगाने के लिए आकर्षक चहचहाट कर रहे थे। बुद्धिमान पुरुष अपने कर्तव्य-पालन के समय कभी विचलित नहीं होते!\n'हे सुन्दर! (सुंदर युवक) माता यशोदा सारे भय से मुक्त हैं, क्योंकि वे सोचती हैं कि आप रात्रि में अपने शयन-कक्ष में शांतिपूर्वक सो रहे हैं। तथापि अब जब आपको जगाने का समय आ गया है, उनका मातृ-स्नेह उन्हें आपके शय्या के पास खींच लाएगा। आप समय के ज्ञाता, सब दुखों का नाश करनेवाले, सभी व्रजवासियों के मित्र और सद्गुणों के सागर हैं। यद्यपि वन की कोमल क्रीड़ा-शय्या स्वयं आनंद का स्वरूप है, फिर भी अपने कल्याण के लिए आपको उठकर उसे तुरंत छोड़ देना चाहिए!'\n'देखो! मदमाते भौंरों का एक झुंड जाग उठा है और अब पुष्प-बिखरे वन में कमलों के समूह में क्रीड़ा कर रहा है। क्या कोई है, जो दिन के ऐसे सुखद समय पर मोहित न हो? देखो! रात्रि के कुमुदों के मुख अपने प्रिय चंद्रमा से विरह के कारण उदास हैं और नील-कमल अपने प्रिय सूर्य से मिलन पर प्रसन्नता से मुस्कुरा रहे हैं। प्रेमी एक स्थान पर विरह का अनुभव कर रहे हैं और दूसरे स्थान पर मिलन कर रहे हैं। क्या यह समय ही नहीं है, जो मनुष्य के सुख या दुःख का कारण होता है?",
    47: "एक मञ्जरी ने राधा-माधव के पीछे तकिया लगाया, जबकि दूसरी ने उनके नग्न शरीर को कोमल वस्त्र से ढक दिया। एक और मञ्जरी ने राधा-माधव को हल्का-मधुर हर्बल जागृति-टॉनिक दिया, जिससे उनकी आँखें पूर्ण खुल गईं और उनका भ्रम दूर हो गया।",
    55: "कक्खटी नाम की एक वृद्धा वानरी, जो उचित अवसर जानती थी, ने वृन्दा से संकेत लेकर पास के वृक्ष पर बैठी कविता पाठ किया—'सद्गुणियों द्वारा प्रशंसित प्रातःकाल, लाल वस्त्र और जटाएँ धारण किए (जटिला) तपस्विनी के समान आता है, जिनकी जटाएँ उनके सिर से निकलती प्रकाश-किरणों के समान दिखती हैं।'",
    61: "दूर का एक शाखाविहीन वृक्ष राधा को सम्मुख विषधर सर्प देखने से भी अधिक भयभीत कर रहा था। कौओं का काँव-काँव राधा को हाथी के चिंघाड़ से अधिक भयभीत करता था; दिन का प्रकाश उन्हें रात्रि के घने अंधकार से अधिक भयभीत करता था। आज राधा अपने प्रियतम से मिलन के कारण विरह की अपेक्षा अधिक पीड़ा भोग रही हैं।",
    71: "चतुर, शंकालु वृद्धा जटिला ने मुखरा का स्वागत किया और अपने पुत्र की समृद्धि बढ़ाने की इच्छा से उससे बोली—'प्रतिदिन विदुषी पौर्णमासी मुझे सिखाती हैं—हे बुद्धिमती! अपने पुत्र अभिमन्यु के लिए संतान, दीर्घायु, धन और अनगिनत गौएँ पाने हेतु कृपया अपनी बहू राधा से स्नान, वस्त्र-आभूषण धारण करवाकर सूर्य-पूजा करवाइए। गोप-रानी यशोदा की आज्ञा का कभी उल्लंघन न करें। और सामान्य लोगों के विचार की चिंता न करें।' अतः हे माननीय मुखरा! कृपया अपनी पोती को सभी शुभ आशीर्वादों से सुशोभित करें, ताकि मेरा पुत्र सारी समृद्धि पा सके।'\nजटिला ने राधा से कहा—'हे पुत्री! शीघ्र उठो, घर की पूजा करो, स्नान करो और सूर्य-पूजा की सामग्री एकत्र करो।'\nमुखरा बार-बार बोलीं—'कैसे आश्चर्य की बात है! प्रभात बीत गया, परंतु मेरी पोती अभी भी सो रही है!' स्नेह से द्रवित हृदय मुखरा राधा के शयन-कक्ष में प्रवेश कर बोलीं—'हे प्यारी बाला! अब उठो। हे भोली! क्या तुम भूल गई कि आज रविवार है? तुम्हें स्नान करना चाहिए, उदित सूर्य को अर्घ्य अर्पित करना चाहिए और शीघ्र उसकी पूजा की तैयारी करनी चाहिए।'\nराधा के शयन-कक्ष में सेवा कर रही विशाखा वृद्धा की बातें सुनकर जाग उठीं। यद्यपि अभी नींद भरी थीं, तब भी विशाखा शय्या से उठकर बोलीं—'हे सखी राधा! शीघ्र उठो, शीघ्र उठो!'",
    80: "प्रतिदिन श्याम अपना चंद्रमा-सदृश मुख मेरे सम्मुख रखकर निमेषहीन नेत्रों से मुझे निरंतर देखते रहते हैं। वे मुझसे वार्तालाप करने के लिए सदा अत्यंत उत्सुक रहते हैं। कृष्ण मेरे पास लेटकर मुझे अपने वक्ष से आलिंगन करते हैं। हे सखी! मैं अपने प्रियतम, सभी प्रेमियों के रत्न, के प्रति अपना स्नेह कैसे वर्णन करूँ?",
    81: "हे सखी! केशव के प्रेमपूर्ण व्यवहार मेरे हृदय को हलाहल विष के समान जला देते हैं। उनके प्रचुर गुण मेरे प्राणों को मांसाहारी कीट के समान कुतरते हैं। उनका प्रेम मेरे हृदय में आघात के समान असह्य व्याकुलता उत्पन्न करता है।",
    110: "किशोरी ने कलावती सखी के वर्णन का गहरा रस लिया और अपने स्नान की बात पूर्णतः भूल गईं। लवंग-मञ्जरी ने व्याकुल हृदय से राधा को बुलाया।",
    120: "एक सखी ने राधा के ललाट पर बाल-रेखा के साथ चमकती सूक्ष्म मोतियों की माला रखी। दूसरी सखी ने राधिका के सुंदर कानों में दो उत्कृष्ट हीरे के कुण्डल पहनाए।",
    142: "राधिका का हृदय हर्ष से फूल गया, क्योंकि उनके कानों ने अपने प्रियतम की मधुर समाचारों का मधु पान किया। थोड़ी देर बाद, तथापि, राधा ने पूर्ण निराशा का अनुभव किया और उनके नेत्रों से ओस के समान शीतल अश्रु टपके, क्योंकि वे कृष्ण को वे वस्तुएँ नहीं खिला सकीं, जो उन्होंने उनके लिए तैयार की थीं।",
    154: "विदुषी विशाखा ने अद्भुत चुटकुलों से कुण्डल बनाने में प्रसिद्ध कुण्डलता से कहा—'हे सखी! यद्यपि कोमल कमल अपने पति सूर्य के स्नेह में खिलता है, तथापि वह उस लंपट भौंरे (मधुसूदन) के भय से काँपता है, जिसका चचेरा भाई सदा कुंद-लताओं (कुण्डवल्ली) में क्रीड़ा करता है।'",
    156: "किशोरी का हृदय अपने परम आनंद (आनंद) के निवास नंद-महल के निकट पहुँचने पर अपने प्रियतम से मिलने की उत्कंठा से फूल उठा। तुङ्गविद्या ने राधारानी को प्रसन्न करने के लिए श्रीकृष्ण के दिव्य निवास की महिमा की।",
    159: "नंदीश्वर गौओं की रंभाट, गोपों की पुकार और भाटों तथा गायकों के स्वरों से गूँज रहा है। नंदीश्वर सभी व्रजवासियों द्वारा पूजित गोवर्धन पर्वत से भी दामोदर को अधिक प्रिय है।",
    166: "नीलमणि की प्रहरी-मीनारें, पीली माणिक्य और मरकत की दीवारें, स्वर्ण की छतें, चमकते माणिक्य से निर्मित विशाल द्वार, प्रवाल के स्तंभ, स्फटिक की चारदीवारी और लाजवर्द के गुम्बद—सब कुछ भव्य था! नंद-महल की चकाचौंध समृद्धि देवताओं के चमकते निवासों को लज्जित कर देती थी।\nकुशलता से बनाए गए तोतों के चित्र रत्न-दीवारों पर लटके थे। चित्र इतने यथार्थ लगते थे कि कृष्ण के पालतू तोते उनके सान्निध्य के लिए उनके पास बैठ जाते थे। जब गोपियों ने उन्हें देखा, तो वे सच्चे और चित्रित तोतों में भेद नहीं कर सकीं। अपने भ्रम में गोपियाँ बहुत देर तक खड़ी रहीं, यह अनिश्चित था कि किस तोते को अनार के बीज खिलाएँ।",
    168: "जब राधा अपनी सखियों के साथ पहुँचीं, तो यशोदा आनंद से उमड़ पड़ीं। उन्होंने सोचा कि तीनों लोकों की सबसे सुंदर देवी अपने घर को प्रकाशित करने उतरी हैं।",
    180: "बलराम कृष्ण के दाहिनी ओर बैठे, श्रीदामा और सुबल बाईं ओर, हास्यकार मधुमंगल उनके सम्मुख और शेष बालक चारों ओर बैठे थे।",
    183: "कृष्ण के दिव्य नाश्ते और मधुमंगल की मजेदार चुटकुलों के वर्णन को दोहराने में कोई दोष नहीं है।",
    198: "हिमाच्छादित पर्वत के समान श्वेत सुंदर शरीर वाले बलराम, जिनके शरीर पर उबटन लगा था, शिखा से निकलता मोरपंख और भुजाओं पर स्वर्ण-रत्न के बाजूबंद और कंगन थे। उन्होंने नीली धोती पहनी और अपने साथियों से मिलने के लिए हाथों में शृंग और लाठी धारण की।",
    231: "वृन्दा की वन-सखी से अपने प्रियतम की लीलाओं का वर्णन सुनकर राधा उल्लास में मूर्च्छित हो गईं। यद्यपि क्षण भर के लिए स्तब्ध हुईं, तथापि राधा कृष्ण और उनके मित्रों के विषय में और अधिक सुनने की लालसा करती रहीं।",
    243: "कृष्ण ने आचमन किया और नंदग्राम से आए कपूर मिश्रित सुगंधित पान चबाए। उन्होंने वन से ताज़े पान के पत्ते और नागवल्ली भी चबाए।",
    258: "राधिका की आँखों से अश्रुधारा बहने लगी और उनका दिव्य शरीर काँपने लगा। विशाखा के सम्मुख अपनी तीव्र इच्छाएँ प्रकट करते समय उन्होंने अन्य अनेक उल्लास-लक्षण भी दिखाए। फिर राधा ने उस मार्ग की ओर गहरी लालसा से देखा, जिस पर तुलसी-मञ्जरी कृष्ण के समाचार लेकर लौटेंगी।",
    269: "श्याम की वंशी की स्वाभाविक मधुर ध्वनि राधा के वर्णन से और भी अधिक सुस्वादु हो गई। सखियों ने अपने प्यासे कानों के कटोरों से उस मधुर अमृत का पूर्ण संतोषपूर्वक पान किया।",
    284: "राधा बोलीं—'हे भाई वायु! तुमने अवश्य किसी महान तीर्थ-स्थान पर तपस्या की है। फलस्वरूप तुम अब प्रसन्नता से अपने पूरे शरीर से गोकुलचंद्र के चरण-कमलों का निरंतर स्पर्श कर रहे हो।'",
    313: "जब राधा कृष्ण की दृष्टि के सामने पुष्प तोड़ने में लगी थीं, तभी उन्हें अचानक एक भौंरे ने काट लिया। राधा भय से काँप उठीं और हल्की मूर्च्छा का अनुभव करने लगीं। उन्होंने सहारे के लिए एक सखी के कंधे थाम लिए। यद्यपि उनका वस्त्र लता में नहीं उलझा था, फिर भी राधा ने उत्सुकता से सिर घुमाकर अपने वस्त्र को देखा।",
    357: "वृन्दावन की अद्वितीय सुंदरता दिखाने के लिए दिव्य युगल ने वृन्दा को दो अमूल्य हार पुरस्कार में दिए। राधा-माधव ने प्रसन्नतापूर्वक वृन्दावन की प्रशंसा की।",
    407: "राधा-गोविन्द ने सखियों द्वारा भेंट किए स्वादिष्ट वन-फल, जड़ें और पान खाए। दिव्य युगल को प्रसन्न करने के लिए उनके अंतरंग सहचरों ने कुशलता से बनाए पुष्प-मेखला, कुण्डल, हार, मुकुट और बाजूबंदों से उन्हें पुनः सजाया।",
    642: "एक रंगीन पुष्प-हार कृष्ण के वक्ष पर झूलता हुआ यावट गाँव में धीरे-धीरे चलते समय हिल रहा था। प्रेम के आनंद से भरी अपनी चंचल, मदमाती कटाक्ष-दृष्टियों से श्याम ने सुकुमार सखियों को कामोन्माद के भँवर में डाल दिया। श्याम के शरीर में उमड़ता स्वाभाविक यौवन-सौंदर्य का सागर गोपियों के मनों के साथ गेंद खेलता हुआ प्रतीत होता था। कृष्ण की सर्वव्यापी कांति ने व्रज के मार्ग को प्रस्फुटित नील-कमलों का वन बना दिया, जिसमें गोपियों के नेत्र-रूपी भौंरे मधुर रस पीने के लिए यज्ञ कर रहे थे। कृष्ण अपने अंतरंग मित्रों के साथ यावट में मस्ती से प्रवेश करते समय उनके नूपुर जोर से झंकृत हो रहे थे।",
    649: "स्नान और भोजन के बाद गौरचंद्र राधा-गोविन्द का ध्यान करते हुए प्रेम से भर गए। गौरांग ने अपने गुप्त सहचरों के साथ राधा-गोविन्द की सायंकालीन लीलाओं का अभिनय करते हुए संकीर्तन किया। गौरसुंदर ने स्वयं को व्रज-भाव में सराबोर कर लिया। उनके दीर्घ केश कदम्ब-पुष्प के केसरों के समान खड़े हो गए और उनके अश्रु गंगा के समान बहने लगे, जब उन्होंने उल्लासपूर्ण प्रेम में भगवान के पवित्र नामों का उच्चारण किया।\nमूल-सूत्र: सायंकाल राधा ने कृष्ण के रात्रि-भोजन के लिए कुछ सखियों को नंदग्राम भेजा। सखियाँ कृष्ण के प्रसाद और उनकी गतिविधियों के समाचार लेकर लौटीं और राधा को प्रसन्न किया। राधा ने अपनी प्रिय सहेलियों के साथ प्रसन्नतापूर्वक भोजन किया। इसी बीच गोविन्द ने स्नान कर मनोहर वेश धारण किया। माता यशोदा ने अतिशय मातृ-स्नेह से उन्हें दुलारा। कृष्ण ने गायें दुहीं और अपने मित्रों के साथ क्रीड़ा की। महल लौटकर कृष्ण ने अपने परिजनों के साथ सायं-भोजन का रस लिया। राधा-गोविन्द की सायंकालीन लीलाओं का हम सदा स्मरण करें।",
    707: "गौरांग ने श्रीवास ठाकुर के आँगन में अपने भक्तों के बीच कीर्तन आरंभ किया, जो उत्साहपूर्वक ताली बजाते हुए भगवान के पवित्र नामों का जाप कर रहे थे। कीर्तन के उल्लास में गौरांग के नेत्रों में अश्रु उमड़ आए, उनके रोम खड़े हो गए, स्वेद निरंतर बहता रहा, उनका शरीर काँपता रहा और उनका कंठ भर आया। जब नाम-संकीर्तन शांत हुआ, तो गौरांग ने अपने भक्तों के साथ फल और अन्य भोजन ग्रहण किया। चंद्रमा की शीतल किरणों से स्नात पुष्प-उद्यान में रत्न-जड़ित शय्या पर स्वर्ण-वर्ण भगवान सो गए। भगवान गौरांग सदा मेरी सेवा के विषय हों।\nमूल-सूत्र: जब राधा-माधव वन-कुंज में प्रसन्नतापूर्वक मिले, तो वृन्दा और उसकी वन-देवियों ने अनेक उत्तम वस्तुओं से उनकी पूजा की। दिव्य युगल और उनकी गुप्त सखियों ने वृन्दावन के छहों ऋतु-वनों में विविध आनंदमयी लीलाओं का आनंद लिया। वे साथ-साथ गाते और परिहास करते वन में विचरे। यमुनातट पर पहुँचकर उन्होंने वृत्त बनाया। राधा-माधव केंद्र में रास-लीला का आनंद लेते हुए नृत्य कर रहे थे।\nराधा-माधव ने कुछ घंटों तक उल्लासपूर्वक नृत्य किया और फिर अपनी थकान दूर करने के लिए मधु-मदिरा पी। नशे के कारण राधा-माधव के नेत्र मदमाते झूलने लगे और उन्हें नींद आने लगी। रसिक युगल विविध दांपत्य सुखों का आस्वादन करने के लिए कुंज में पुष्प-शय्या पर लेट गए। तदनंतर राधा-माधव यमुना में क्रीड़ा करने लगे। फिर उन्होंने मिठाइयाँ और वन-फल खाए। राधा-माधव के सोने से पहले स्नेहमयी गोपियों ने चामर-सेवा और चरण-संवाहन करके उन्हें प्रसन्न किया। सखियाँ अपने-अपने कुंजों में सो गईं। राधा-माधव की आनंदमयी मध्यरात्रि लीलाओं का हम सदा स्मरण करें।",
    799: "गांधर्विका-गिरिधारी की जय!",
    12: "दक्ष नामक तोता, जो श्रीकृष्ण की लीलाओं का वर्णन करने में निपुण तथा असंख्य अन्य तोतों का गुरु था, पुष्प-कुंज में प्रवेश करके आनन्द से अपने पंख फैलाकर बोला—'देखो कृष्ण! सूर्य उदय हो चुका है। चक्रवाकी पूर्व दिशा के रक्ताभ आकाश की ओर, और फिर अपने दूरस्थ प्रियतम की ओर उत्सुकता से देख रही है। कौओं के भय से उल्लू चुपचाप वृक्षों के कोटरों में घुस गए हैं। कृपया आप तुरंत अपनी निद्रा त्याग दें।'",
    15: "सूक्ष्मधी नाम की तोती, जिसने वृन्दादेवी से सीखी हुई सम्पूर्ण सेवा-विद्या को अपने गले में मोती की माला की भाँति धारण कर रखा था, प्रेम-मदिरा पान करने से मतवाली हो उठी थी। वह राधा को जगाने के लिए बोली।",
    18: "हे सुदति! (सुंदर दाँतोंवाली) सफेद कुमुदनी के कोरों में लीला करते हुए मत्त भौंरों का एक दल उमड़कर प्रस्फुटित कमल-समूह की ओर बढ़ता है, मानो प्रणय-अभिसार के लिए जा रहा हो। समय की ऐसी बेला में भौंरों ने कुमुदिनियों से रुचि खो दी है और कमल-पुष्पों पर मुग्ध हो गए हैं।",
    22: "राधा-माधव के चरण-नूपुर, कंगन और अन्य आभूषण मधुर झंकार कर रहे थे तथा उनके अंग प्रेम से जगमगा रहे थे। बिखरी हुई अलकों से घिरे उनके मुखमंडल, हार तथा कुण्डलों की छटा से आलोकित हो रहे थे।",
    25: "राधा ने अपनी सुंदर साड़ी का पल्ला दाहिने हाथ में लेकर अपने सुंदर दाँतों के प्रकाश से नहाए हुए कमल-मुख को ढक लिया। फिर कंधे थोड़े उठाकर जमुहाई लेते हुए राधा ने बाएँ हाथ की अँगुलियाँ चटकाकर और चूड़ियाँ बजाकर एक मधुर राग गुनगुनाया। राधा ने शरीर मर्दन किया तथा अपने सुडौल कटि-प्रदेश को बेचैन होकर हिलाया। हाथ जोड़कर राधा ने उन्हें सिर के ऊपर उठाया। इस प्रकार राधिका का सुंदर मुख परिधिमण्डल में चंद्रमा के समान चमक रहा था।",
    42: "उस युवक-युवती के शरीर से निकलती हुई सौंदर्य-किरणों के कण-कण के लिए अपने करोड़ों प्राण न्यौछावर करनेवाली सखियों की मीनाक्षी नेत्रों ने कुटिया की जालीदार खिड़की से बहते हुए शोभा-रस की धाराओं में क्रीड़ा की।\nविशाखा ने कहा—'देखो ललिते! यद्यपि राधा-माधव निरंशुक (वस्त्रहीन) हैं, तथापि वे आंशुक (अद्भुत कान्ति से आवृत) हैं। यद्यपि वे विहारी (हाररहित) हैं, तथापि राधा-माधव अपने अंगों पर प्रेम के चिह्नों के साथ अतिहारी (अत्यंत सुंदर) लग रहे हैं। यद्यपि वे अनंगद (बाजूबंदरहित) हैं, तथापि वे अंगदद (एक-दूसरे को अद्वितीय कामानन्द देनेवाले) हैं। यद्यपि वे निरंजन (अंजनरहित) हैं, तथापि वे निरंजन (एक-दूसरे को प्रसन्न करनेवाले) हैं। यद्यपि उनके होठों के राग की आसक्ति शिथिल हो चुकी थी (विस्रस्त-राग-अधरता-अभिलक्षितौ), तथापि उनका बिखरा हुआ शय्या-पट मानो प्रेम की भीषण लड़ाई की कथा कह रहा था (विप्रस्तर-गाढ़-रत-अभिलक्षितौ)।'\nललिता ने कहा—'हे सखियों! कृपया बताओ, कल रात्रि के प्रणय-युद्ध में कौन विजयी हुआ? मैं नहीं कह सकती, क्योंकि युद्ध में कृष्ण का शिखा-गुच्छ तथा राधा की वेणी दोनों शिथिल होकर आपस में उलझ गए हैं। और भी, दोनों के होठों पर दंशन के चिह्न तथा वक्षस्थल पर नख-क्षत हैं।' विशाखा ने कहा—'हे सखी! देखो! राधा अपने वक्ष पर कुंकुम लगाकर अपने हृदय के प्रेम से अच्युत के चरण-कमलों को रंग रही है! और कृष्ण अपने सिर पर लगे लाल अलक्तक के द्वारा राधिका के चरण-कमलों के प्रति अपने प्रेम की घोषणा कर रहे हैं।'\nयुगल का आनन्द देखने से सखियाँ गुप्त रूप से राधा-श्याम की लीलाओं के आश्चर्य का वर्णन कर रही थीं। अपने सौभाग्य की प्रशंसा करती हुई वे आनन्द-सागर में डूब गईं।",
    46: "राधा-माधव अपनी आनंदित और स्नेहमयी सखियों का स्वागत करते हुए मुस्कुराए। उनके सान्निध्य में राधा-माधव के सौंदर्य की कली (रूपमञ्जरी) पूर्ण रूप से खिल उठी। उस रूपमञ्जरी ने अत्यंत कुशलता से युगल की सेवा की। [दूसरा अनुवाद]: श्री रूपमञ्जरी नाम की सखी, जो राधा-माधव को रुचिपूर्वक सजाने-धजाने में निपुण है, आनंदित हो उठी।",
    56: "जटिला (राधा की सास) शब्द सुनते ही गोपियों के मुख पीले पड़ गए। अत्यधिक भय और चिंता का उदय हुआ सूर्य, जो उनके आनंद-लीला-सागर को सुखाने के लिए उदित हुआ था।",
    59: "एक सखी ने दूसरी से कहा—'देखो, सूर्योदय होने पर व्रजवासियों के जागने से पहले ही कृष्ण अपने घर लौट रहे हैं। उन्होंने मुरझाई हुई फूलों की माला फेंक दी है। प्रणय-युद्ध में कृष्ण का रत्न-हार टूट गया है। राधा के काजल-युक्त नेत्रों के चुंबन से उनके होठ काले पड़ गए हैं और उनके शरीर पर प्रेयसी के नख-चिह्न दिखाई दे रहे हैं। देखे जाने के भय से कृष्ण थकी आँखों से इधर-उधर देखते हुए मार्ग पर दौड़ रहे हैं। देखो, वे कैसे चुपचाप अपने घर में घुस रहे हैं!' स्तव-माला,",
    63: "राधा अपनी सखियों से घिरी हुई किसी को दिखाई न देकर अपने घर में प्रवेश कर गईं और शय्या पर लेट गईं। कृष्ण के विरह में तीव्र वेदना का अनुभव करते हुए राधा रोने लगीं। व्याकुल स्वर में राधा ने ललिता के सम्मुख अपना हृदय खोल दिया।",
    65: "एक सखी, जो राधा-माधव के जागरण की लीला में उपस्थित नहीं थी, दूसरी से बोली—'देखो सखी! राधिका निकुंज से लौटकर चुपचाप अपने शयन-कक्ष में प्रवेश कर गई हैं। उनके सिर का नीला वस्त्र बार-बार खिसक जाता है और वे थककर उसे ठीक करती हैं। प्रणय-लीला के कारण उनके वस्त्र और आभूषण बिखरे हुए हैं। राधा की थकी हुई आँखें इधर-उधर देख रही हैं, और वे कमजोर होकर अपनी शिथिल वेणी को फिर से गूँथने का प्रयास कर रही हैं।' स्तव-माला,",
    68: "राधा के ससुराल में सो जाने के बाद श्री रूपमञ्जरी और अन्य मञ्जरियाँ उठकर स्नान कर चंदन तथा सुगंधित लेप शरीर पर लगाने लगीं। मञ्जरियों ने अपनी स्वाभाविक शोभा बढ़ाने के लिए राधा के प्रसाद-रूप माला, वस्त्र और आभूषण धारण किए। जिन्होंने सभी निजी इच्छाओं का त्याग कर दिया था, वे मञ्जरियाँ राधा-गोविन्द की प्रेम-सेवा में लगकर मनोहर गुणों और उत्तम आचरण का प्रकाश करने लगीं।\nउनके चरणों के अग्रभाग से निकली एक भी किरण बिजली की चमक को सरलता से पराजित कर सकती थी। राधा की मञ्जरियाँ चतुरता की प्रतिमूर्ति थीं। यद्यपि प्रत्येक मञ्जरी यूथेश्वरी बनने की अधिकारिणी थी, फिर भी उनका मन कभी उस ओर नहीं गया, क्योंकि वे सदा राधा-सेवा के मधुर सागर में डूबी रहती थीं।\nवृषभानु महाराज ने अपनी पुत्री राधा के स्नेह से यावट में जटिला के निवास की उत्तरी दिशा में उनके लिए एक अद्वितीय सुंदर महल बनवाया था। राधा का वह महल प्रकाश से परिपूर्ण तथा उत्कृष्ट कला से सज्जित था। वह भव्य महल सुंदर स्तंभों, चबूतरों, छतों, झरोखों, आँगनों, अनेक प्रकार के कक्षों, द्वारों और बालकनियों से भरा हुआ था। रत्न-दीपकों से जगमगाती वह अनोखी इमारत देखनेवालों की आँखों को चकित कर देती थी।\nमहल के शिखर पर बादल जैसी श्याम चमकती इंद्रनीलमणि की कलशी थी, जो चमकते हुए रजत-हंसों के झुंड से सुशोभित थी। मोर उस कलशी को देखकर उसे अपना मित्र मेघ समझकर आनंद से पंख खोल देते थे; फिर पास जाकर सजातीय-शत्रु रजत-हंसों को देखकर तुरंत अपने मोरपंख समेट लेते थे।",
    74: "सहसा राधा सब कुछ भूलकर आनंद-विह्वल होकर मूर्च्छित हो गईं। चेतना लौटने पर राधिका ने पूछा—'हे श्यामे! तुम कब आईं?'\nश्यामला ने उत्तर दिया—'अभी-अभी। सखी, आपको क्या हुआ है? आपके शिथिल अंग थकान प्रकट कर रहे हैं। आपके होठ पीले पड़ गए हैं, भुजाएँ मुरझाए हुए कमल-नाल जैसी लग रही हैं और गालों पर लावण्य की मनोहर रेखाएँ नहीं हैं। आज आप वायु से झूले हुए कोमल लता की भाँति, हाथी द्वारा कुचले कमल-कोरक के समान, या पागल भौंरे द्वारा त्यागी गई नव्य जूही-माला जैसी दिख रही हैं।'\n'हे सुंदरी! आपको अपने चिर-प्रियतम से कोई अत्यंत दुर्लभ वस्तु मिली है। अन्यथा हमारी भाग्य-लता ऐसा फल कैसे दे सकती थी? कृपया मुझे बताइए।'\nश्यामला के स्नेहपूर्ण प्रश्न से पूछी गई शुद्ध-हृदया राधा ने अपने चंद्रवदन मुख को वस्त्र से ढककर भूमि की ओर देखा। आनंदमयी सखियों के बीच राधा मधुर मुस्कान के साथ बोलीं—'हे कमल-नयन सखी! मैं जानती हूँ कि मैं कहाँ थी, कहाँ गई, उनसे मिलने किस मार्ग से गई और कैसे वहाँ पहुँची, तो तुम कैसे नहीं जानतीं? तुम्हारी सलाह के बिना मैं कुछ भी नहीं करती।'\n'अरे! वह क्या है, जो मन की पहुँच से परे और चिंतन की सीमा से बाहर है? संभवतः वह कोई स्वप्न, कोई इंद्रजाल, या दीर्घ मोह की अवधि थी, जिसने मुझे आनंद दिया या पीड़ा, या दोनों, या कुछ भी नहीं—मैं नहीं कह सकती। मुझे केवल इतना ज्ञात है कि उसने मेरा हृदय पूर्णतः पिघला दिया और मैं अचेत हो गई।'",
    89: "'जब पौर्णमासी नंद महाराज के महल में प्रवेश करीं, तो उन्होंने दिनभर की मथनी-क्रीड़ा से टपके मक्खन और दही की बूँदों से सज्जित प्रसन्न आँगन देखा। वह आँगन श्वेतद्वीप के समान लग रहा था, जहाँ रत्नभूषित भगवान अच्युत दूध की हिलती तरंगों के बीच अनंत के कोमल उदर पर आनंद से विश्राम करते हैं। अत्यंत हर्ष से पौर्णमासी ने रत्नों से विभूषित कृष्ण को देखा, जो अपने प्रियजनों से घिरे कोमल शय्या पर शांतिपूर्वक सो रहे थे। शिष्टाचार में निपुण यशोदा ने जैसे ही तपस्या की मूर्ति पौर्णमासी को देखा, वे प्रसन्न होकर उनका स्वागत करने दौड़ीं।'\n'यशोदा ने कहा—स्वागत है भगवती! अंदर पधारिए। आप व्रज की सर्वाधिक पूजनीय महिला हैं। मैं आपके चरणों में प्रणाम करती हूँ।'\n'यशोदा जब आदर करने आगे बढ़ीं, तो पौर्णमासी ने उन्हें स्नेह से गले लगा लिया। पौर्णमासी गोविन्द को देखने के लिए अत्यंत उत्सुक थीं। उन्होंने यशोदा को आशीर्वाद दिया तथा उनके, उनके पति, पुत्र और गौओं के कुशल-क्षेम का प्रश्न किया। यशोदा ने पौर्णमासी को अपनी सुख-समृद्धि की सूचना दी और फिर शीघ्र ही कृष्ण के शयन-कक्ष में प्रवेश कर गईं।'",
    105: "राधा ने अपनी हथेली से जल उठाकर मुँह में कुल्ला किया। ऐसा करते समय उनके गाल थोड़े फूले और उनके मुँह से कोमल मधुर ध्वनि निकली। राधा ने कुल्ले का जल सोने के पीकदान में थूका। मुख धोते समय कुछ अलकें उनके ललाट पर आ गिरीं। राधा ने बाएँ हाथ की अँगुलियों से उन्हें सिर के ऊपर धकेल दिया। राधा ने तीन बार अपना ललाट, गाल और नेत्रों को स्वच्छ किया, जिससे वे और भी अधिक कांतिमय हो उठे।\nएक सखी ने राधा को कल्पवृक्ष की उत्तम शाखा दातून के रूप में भेंट की। राधा ने उसे अपने कमल-कलिका-से हाथ में स्वीकार कर दाँत माँजे। दाँत माँजते समय राधा की पहुँची और कुण्डल इधर-उधर झूल रहे थे। उनके दाँत मोती की वर्षा के कणों के समान चमक रहे थे। हाथों की शीघ्र गति के बावजूद किशोरी की चूड़ियाँ किसी प्रकार चुपचाप रह जातीं। एक सखी ने रत्न-जड़ित धनुषाकार जिह्वा-शोधक भेंट किया। राधा ने उसे अपने कोमल हाथों के अँगूठे-तर्जनी के बीच पकड़कर जिह्वा पर आगे-पीछे फेरा।\nराधा, जो कोमल नव कमल-पर्ण के समान जिह्वा को स्वच्छ कर रही थीं, सिर हल्का झुकाकर हिला रही थीं, जिससे अलकें मुख पर बिखर गईं। सखियों को मुस्कुराते देख राधिका भी मुस्कुराईं। राधा ने अपने चंद्रवदन मुख और मुँह को कुछ बार धोया और फिर हाथ साफ किए। एक सखी द्वारा दिए कोमल, महीन तौलिये से राधा ने मुख की शेष बूँदें पोंछ लीं।\nएक सखी ने राधा के सम्मुख रत्न-जड़ित दर्पण धारण किया। अपनी अद्वितीय सुंदरता को देखकर राधा ने अनुभव किया कि यह प्रियतम के नेत्रों के लिए उत्सव होगा। राधा ने अपनी मुस्कान के अमृत से पुनः मुख धोया।",
    108: "'प्रत्येक गाय ने कृष्ण के स्नेह से, जो उसे अपने बछड़े से भी अधिक प्रिय थे, अपने थनों से दूध स्वतः बहा दिया। दूध की धाराओं से भर-भरकर बाल्टियाँ उछलने लगीं और छलककर पृथ्वी को गीला कर दिया।'",
    157: "तुङ्गविद्या सखी ने कहा—'नंदीश्वर के परिदृश्य को असंख्य उत्तुंग वृक्ष, पुष्पित लताएँ और झाड़ियाँ सुशोभित कर रहे हैं। वहाँ रसाल, कटहल, आम, पान, अर्जुन, गुवाक, नारियल, असन, पलाश, बरगद, पर्कटी, खदिर, बिल्व, मधुक, गिरिमल्लिका, बकुल, नाग, पुन्नाग, अशोक, बक, पाटली, स्वर्ण-चम्पक, तमाल, नवमल्लिका, स्वर्ण-यूथिका, यूथिका, पीत-अमरंथ, लौंग, दमनक, अतिमुक्ता, जवा, मल्लिका, कदली, प्रियंगु और तुलसी के वृक्ष हैं।'",
    179: "राजसी भोजन-गृह को सजाने वाले झालरों और रंगीन चित्रों से वहाँ उत्सव-जैसा वातावरण बन गया। रत्न-जड़ित प्यालों में रखी विभिन्न सब्जियाँ रत्न-मणि खचित मेज के किनारे सजाई गई थीं। स्वादिष्ट मिठाइयों के असंख्य कटोरे तथा विभिन्न दुग्ध-पदार्थों के स्वर्ण-कटोरे सब्जियों की पंक्ति के ठीक पीछे रखे गए थे। राधा की सखियों ने पदार्थों को अर्ध-वृत्त तथा अन्य आकृतियों में कलात्मक रूप से सजाकर अद्भुत वातावरण निर्मित किया। बीच में घी से तर-बतर सुगंधित श्वेत चावल का विशाल ढेर स्वर्ण-थाल में रखा था। दाईं ओर उन्होंने घी, नींबू, अचार, अदरक, आम और सरसों की चटनी का स्वर्ण-थाल रखा। चतुर्दिक कपूर-सुगंधित पेय-जल के घड़े रखे गए।\nमाता यशोदा किशोरी की पाक-कला और भोजन परोसने की सखियों की अद्भुत व्यवस्था देखकर अत्यंत प्रसन्न हुईं। उन्होंने एक धाय को अपने लड़कों को बुलाने भेजा। कृष्ण और बलराम उत्सुकता से भोजन-गृह की ओर चले। सुंदर पीत-वस्त्र धारण किए कृष्ण ने माता यशोदा को प्रणाम किया। उनके निर्देश पर कृष्ण ने कुछ कन्याओं को अपने और बलराम के चरण धोने तथा मुँह धोने के लिए जल देने की आज्ञा दी। यह देखकर यशोदा आनंद से विभोर हो गईं। कृष्ण ऊँचे भोजन-मंच पर बैठ गए। सभी स्वादिष्ट पदार्थों को देखकर वे पूर्ण आश्चर्यचकित रह गए।",
    194: "गहन स्मरण करते हुए गौरांग ने गोविन्द की वह अत्यंत आकर्षक पूर्वाह्न-लीला पुनः अभिनीत की, जब वे मित्रों के साथ गायों को वन ले जाते थे और जिससे व्रजवासियों को अत्यंत वेदना होती थी। गौरांग जब व्रज-भाव में डूबे, उनका शरीर पुलकित हो गया, स्वर्ण-वर्ण शरीर काँपने लगा और आनंद-विह्वलता में स्तब्ध हो गया। गौरांग अपने अंतरंग सहचरों के साथ विविध भावों को बाँटते हुए अश्रुधारा बहाते थे। सदा दिव्य आनंद की तरंगों में डूबे रहने वाले उस गौरचंद्र की, उनके सहचरों सहित, मैं सदा सेवा करूँ।\nमूल-सूत्र: प्रतिदिन प्रातः कृष्ण और गोप-बालक गायों को वन ले जाते थे। तीव्र वात्सल्य-प्रेम के कारण नंद, यशोदा और अन्य व्रजवासी उनका अनुसरण करते थे। कृष्ण गायों और बालकों को गोवर्धन पर छोड़कर चुपचाप राधा-कुण्ड जाकर राधिका की खोज करते थे।\nराधारानी कृष्ण को अपनी गायों के साथ नंदग्राम से जाते देखती थीं। तब वे घर लौटकर यावट आ जातीं और जटिला की आज्ञा से सूर्य-पूजा करने जातीं। प्रस्थान से पहले राधा कृष्ण के समाचार लानेवाले अपनी दूती की प्रतीक्षा में मार्ग की ओर व्याकुलता से देखती थीं। राधा-गोविन्द की पूर्वाह्न-लीलाओं का हम सदा स्मरण करें।",
    197: "श्याम ने अपनी शिखा में अत्यंत मनोहर इंद्रधनुषी मोरपंख और चमकीले लाल गुंजाओं की माला धारण की। इंद्रनील-कुण्डल और पुन्नाग-पुष्पों के गुच्छे उनके कानों को सुशोभित कर रहे थे। उनके विशाल वक्ष पर मोती तथा गुंजा की मालाएँ लटक रही थीं। इस प्रकार पीत-वस्त्र और विविध आभूषणों से सज्जित कृष्ण वन में प्रवेश करने के लिए तैयार होकर अद्भुत शोभायमान हो रहे थे।",
    240: "'गोप-बालकों ने अपनी-अपनी रुचि के अनुसार कृष्ण को विविध रंग-बिरंगे वन-आभूषणों से सजाने की होड़ में कहा—पहले मैं करूँ! पहले मैं करूँ!'\n'कृष्ण ने कहा—मेरे प्रिय मित्रों! इस रमणीय वातावरण वाले नदी-तट की सुंदरता देखो। और ध्यान दो कि कैसे प्रस्फुटित कमल अपनी सुगंध से भौंरों और पक्षियों को आकर्षित कर रहे हैं। उनकी गुंजार और चहचहाहट वन के सुंदर वृक्षों में गूँज रही है। यहाँ की रेत कोमल और स्वच्छ है, अतः यह हमारी क्रीड़ाओं के लिए सर्वोत्तम स्थान है। मैं समझता हूँ कि हमें यहीं भोजन करना चाहिए, क्योंकि हमें भूख लगी है और बहुत देर हो चुकी है। बछड़े जल पी सकते हैं और घास चरते हुए इधर-उधर विचर सकते हैं।'\n'जैसे कमल-पुष्प की कर्णिका पंखुड़ियों और पत्तों से घिरी होती है, वैसे ही कृष्ण मित्रों की पंक्तियों से घिरकर बीच में बैठे थे, और सभी अत्यंत सुंदर दिख रहे थे। प्रत्येक बालक कृष्ण की ओर देखता था, यह सोचते हुए कि कृष्ण मेरी ओर देखें। इस प्रकार उन सबने वन में आनंदपूर्वक भोजन का आनंद लिया।",
    265: "'मैं नहीं जानता कि वंशी जहर उगल रही है या अमृत। क्या वह वज्र से भी कठोर है या जल से भी कोमल? क्या वह प्रज्वलित अग्नि से अधिक गर्म है या चंद्रमा से अधिक शीतल? तथापि मैं इतना जानता हूँ कि उसे सुनकर समस्त व्रजवासी उन्मत्त हो जाते हैं।'",
    273: "प्रेमावेश में व्याकुल कृशोदरी राधा ने अपनी मेखला गले में, हार पैरों में, बाजूबंद चरणों पर और नूपुर भुजाओं में पहन लिए। प्रियतम से मिलने जाते समय राधा के सभी अंगों ने प्रेम के आनंद का प्रचार करके अपनी-अपनी विशेष शक्ति प्रकट की।",
    286: "मार्ग पर दौड़ती हुई वृन्दा ने सोचा—'मूर्ख लोगों ने किशोरी के मुख की सुंदरता की तुलना चंद्रमा या कमल से करने का प्रयास क्यों किया है? दूर से देखने पर भी राधिका के मुख की सुंदरता दर्जनों अमृतमय चंद्रमाओं को लज्जित कर देती है और गर्वित कमल-समूहों को हारकर कुम्हला डालती है!'",
    288: "राधा: 'तुम झूठी हो! ऐसा मत बोलो!'\nवृन्दा: 'हे राधा, मैं सत्य कह रही हूँ! सुनो! गोकुल में सैकड़ों तेजस्वी सुंदर युवतियाँ हैं, जिनके मन पूर्णतः कृष्ण से आसक्त हैं। तथापि उन सबकी शिरोमणि केवल तुम हो। मैं स्वयं देखकर कह सकती हूँ कि तुम्हारे विरह में कृष्ण किसी अन्य स्त्री की ओर दृष्टि भी नहीं डालते।'",
    289: "अपना आशय छिपाते हुए राधा ने उत्तर दिया—'हे वृन्दा, गपशप से क्या लाभ? हम श्याम-कुण्ड के पाताल-गंगा जल में स्नान करेंगी, जटिला की आज्ञा के अनुसार सूर्य-पूजा करेंगी और घर लौट जाएँगी।'",
    294: "'हे सुबल! क्या यह स्त्री प्रेम-कला का आश्रय है, जो अपने कोमल अंगों को दिखाकर मेरा हृदय चुरा लेती है? उसका सुंदर शरीर चित्रित उत्कृष्ट चित्र-सा, या नवीन शिल्प से तराशा हुआ, या नवयौवन की खराद पर उतारा हुआ और कामदेव की कलाओं की शिला पर घिसा हुआ प्रतीत होता है। उसके अंग ऐसे लगते हैं मानो सौंदर्य के गहरे सरोवर में डुबोकर उठाए गए हों और मानो आलस्य से मोहक हों।'",
    295: "'राधा का तेजस्वी मुख मेरे नेत्रों के प्यासे चकोरों के लिए पूर्णिमा का चंद्रमा है। वह मेरी नासिका के भ्रमर के लिए कमल है और उसके स्वादिष्ट अधर मेरी जिह्वा के कोकिल के लिए नव-विकसित आम्र-मंजरी हैं। किशोरी के झंकृत आभूषण मेरे कानों के हिरणों को आकर्षित करते हैं। कामाग्नि में जलते मेरे शरीर के मत्त गजराज के लिए वह अमृत की शीतल नदी के समान मेरे पास आती है। अहा! मेरे सौभाग्य का कल्पवृक्ष अब फलित हुआ!'",
    296: "'राधा के नेत्रों के कोने, सुंदर काजल से चिह्नित, स्वर्ण-पिंजर में खंजन पक्षियों के समान चमक रहे हैं। उनकी मधुर मुस्कान कुट्टित कपूर के समान कांतिमय दिख रही है।'",
    297: "'हे मेरे मित्र सुबल! जब कमल-नयन राधारानी श्वास लेती हैं, तो उनके माणिक्य-समान रंग के नथुनों के छिद्र फूलते हैं और उनकी नाक का मोती वायु में झूलते झूले पर चढ़े हुए के समान आगे-पीछे हिलता है। राधा का यह मनोहारी दृश्य मेरे हृदय में गहराई तक समा गया है।'",
    299: "जैसे ही राधा ने अपने प्रियतम को देखा, उनकी प्यासी आँखें आनंद से फैल गईं और कानों तक पहुँचने का प्रयास करने लगीं। राधिका का आंतरिक उल्लास नेत्रों से आनंदाश्रु के रूप में बह निकला, मानो नेत्रों के परिश्रम से उत्पन्न स्वेद-बूँदें हों।",
    301: "तुलसी की बातों से राधा के मुख पर भौंहें चढ़ गईं। तब एक सखी ने कहा—'हे गौरी! आपके नेत्रों की पुतलियों में सभी बुद्धिमानों को मोहित करने की शक्ति है। हे गांधर्विका! आपके नेत्रों के भौंरे कृष्ण के कानों में लटकते सुगंधित कमलों की ओर उड़ते हैं। मधुसूदन (भौंरा) आपके कमल-नेत्रों की लीलापूर्ण चंचलता से पूर्णतः अपना स्मरण खो बैठते हैं। कृष्ण दूसरे कमल (पद्मा, यानी चंद्रावली सखी) को कैसे याद कर सकते हैं?'",
    304: "'नीला-श्याम वर्ण धारण करने वाले, सर्वव्यापी तेजस्वी, हाथ में सीधी गोपाल-छड़ी लिए, कटि में पीत-वस्त्र लपेटे, जिनके शरीर की सुगंध नील-कमल को लज्जित करती है, और जिनकी रसीली मूर्ति प्रेम की प्रतिमूर्ति है, वे हरि अब वन में विहार कर रहे हैं।'",
    311: "एक-दूसरे को देखकर राधा-माधव प्रेमावेश से विह्वल हो उठे। उनके दिव्य शरीर, मन और हृदय तीव्र हर्ष से काँपने लगे। क्षण भर वे स्तब्ध खड़े रहे, बोलने या हिलने में असमर्थ।",
    319: "कृष्ण राधिका की अद्वितीय सुंदरता की मदिरा पीकर उनसे मिलने की उत्कंठा से मतवाले हो गए। आनंद-विह्वलता के कारण कृष्ण पूर्णतः भूल गए कि उन्होंने राधा को पहले कभी देखा था। फिर स्मृति लौटने पर उन्होंने देखा कि व्रज-गोपियों की शिरोमणि उनके पुष्प तोड़ रही थीं। मन में आनंद की दौड़ लगाते हुए कृष्ण धीरे-धीरे राधा के पास पहुँचकर पूछा—'तुम कौन हो? मेरी मंजुल-लता को क्यों जान-बूझकर विचलित कर रही हो?'\nराधा ने कृष्ण की ओर देखा, जिनके नेत्र चंचल थे और ललाट पर गोरोचन का तिलक था, और कहा—'मैं सूर्य-पूजा के लिए पुष्प तोड़ रही हूँ। आप क्यों आपत्ति करते हैं?' राधा ने अपना सुंदर सिर पूर्णतः घूँघट से ढक लिया और पुष्प-तोड़ने के बहाने चल दीं। राधा ने चंचल नेत्रों से इधर-उधर देखा। उन्हें राधा-कुण्ड के तट पर घनी पत्तियों वाला एक जूही-गुल्म दिखाई दिया। प्रेम के प्रभाव से जगमगाते कमल-मुख वाली राधिका उस जूही-गुल्म के पास पहुँचीं और उसकी घनी पत्तियों, अनगिनत पुष्पों और भौंरों के झुंड के भीतर अंतर्धान हो गईं।",
    320: "कृष्ण ने कहा—'अरे मृग-नयनी! अब मैं समझ गया कि तुम प्रतिदिन छिपकर पुष्प चुराती हो। अरे चोरिनी! आज तो भाग्य से मैंने तुम्हें पकड़ लिया। अब हठ मत करो; बस मेरे साथ कारागार-गुफा में चलो।'",
    332: "राधा के स्पर्श से कृष्ण इतने मोहित हो गए कि उनके हाथ काँपने लगे, जिससे राधारानी पर उनकी पकड़ ढीली पड़ गई और उनसे अनजाने में उनकी वंशी गिर गई। किशोरी श्याम के आलिंगन से छिटककर बाहर निकलीं, शीघ्रता से वंशी उठाई और सावधानी से अपने वस्त्रों के नीचे छिपा लिया। सभी सखियों ने सोचा कि ललिता के भय से कृष्ण ने अपनी वंशी गिरा दी और राधा को छोड़ दिया।\nललिता ने कहा—'हे सखी! यह विचित्र बात है कि सोते हुए भी किसी अन्य गोपी ने नंदनंदन से वंशी नहीं चुराई। फिर भी भाग्यवती राधा ने कटाक्ष-कला से कृष्ण को मोहित करके उनकी आँखों के सामने ही वंशी चुरा ली।'\nराधा ने स्वयं से धीरे-धीरे कहा—'यह वही वंशी है, जो गोपियों के हाथों को गृह-कार्य करते समय स्तब्ध कर देती है। रात्रि में यह वंशी स्वर्ण-कांतिमयी गोपियों को उनके पतियों की गोद से भी खींच लाती है। यह धृष्ट वंशी बड़े-बुजुर्गों के सामने भी गोपियों के अंतर्वस्त्र के सूत्र शिथिल कर देती है! अब कृष्ण की यह शरारती वंशी मेरे वश में है।'",
    338: "राधिका की चूड़ियाँ जोर से झंकृत हुईं, जब उन्होंने कृष्ण को अपने चोली और अंतर्वस्त्र खोलने से रोकने के लिए हाथ बढ़ाए। प्रेम-कंप से काँपते हुए कृष्ण हकलाकर बोले—'वं-वं-वंशी दो!' राधिका ने हर्ष से हकलाते हुए उत्तर दिया—'मेरे पास तुम्हारी वंशी नहीं-नहीं है!'\nकृष्ण ने उत्सुकता से राधा के यौवन के रत्न चुराने शुरू किए और वे व्याकुल होकर उन्हें रोकने लगीं। अंततः कंदर्प (कामदेव) का सेनापति, जिसे धृष्टता कहते हैं, ने राधिका के प्रतिरोध, लज्जा और धैर्य रूपी सखियों को रणभूमि से भगा दिया। राधा-माधव के सुंदर दिव्य प्रेम-उत्सव की आग बढ़ती गई, जब राधा के भावपूर्ण उच्छ्वास, कोकिल के मधुर कूजन के समान, अमृत की धारा के रूप में प्रकट हुए। उनके तेजस्वी शरीरों पर प्रणय-दंशन और नख-चिह्न उत्पन्न हुए, जब वे क्रीड़ा से संघर्ष करते रहे। राधा-माधव की एकांत कुंज की मधुर लीलाएँ सदा विजयी हों!",
    347: "एक अन्य सखी ने राधा से पूछा—'हे कमल-नयनी! किसने अपने नखों से आपके वक्ष के ऊपरी भाग पर अपना चित्र बना लिया है? वह चित्र न तो धूमिल होता है, न मिटाया जा सकता है। क्या आप उस चित्र को धारण करने में गर्व का अनुभव नहीं करतीं?'",
    354: "'कहीं भूमि मरकत मणि की बनी है, जिसमें स्वर्ण के वृक्ष, गुल्म और लताएँ हैं। कहीं मार्ग स्वर्ण के हैं और वृक्ष-लताएँ मरकत के। कहीं-कहीं माणिक्य की भूमि पर स्फटिक के वृक्ष, गुल्म और लताएँ हैं। अन्य स्थानों में स्फटिक की भूमि तथा माणिक्य के वृक्ष और गुल्म हैं। कहीं मरकत के वृक्षों को स्वर्ण की लताएँ आलिंगित किए हैं, तो कहीं मरकत की लताएँ स्वर्ण के वृक्षों को। कहीं स्फटिक के वृक्ष माणिक्य की लताओं को आलिंगन करते हैं, तो कहीं माणिक्य के वृक्ष स्फटिक की लताओं को।'\n'वृन्दावन में ऐसा कोई रत्न-वृक्ष नहीं है, जिसकी रत्न-शाखाएँ न हों, और न ऐसी रत्न-शाखा है, जिसमें रत्न-कलिकाएँ न हों। न रत्न-कलिका है जिसमें रत्न-पुष्प न हों, और न रत्न-पुष्प है जिसमें मनोहर सुगंध न हो। वृक्षों के आधार के चारों ओर जल-कुण्ड हैं। रत्न-पर्वतों से उत्पन्न तरल रत्नों के ढेरों के समान प्रवाहित धाराओं से वे कुण्ड भरे हुए हैं। रत्न-पक्षी उन रत्न-कुण्डों को सुशोभित करते हैं।'",
    355: "'माणिक्य-जड़ित जल-कुण्डों के प्रतिबिंबित प्रकाश-किरणों के कारण वृक्षों के तने लाल लाख से लिप्त प्रतीत होते हैं। ऐसा लगता है कि उनके हृदय के भीतर स्थान की सीमा के कारण उनकी जड़ों से कृष्ण के प्रति उनका तरल आकर्षण (रस) ऊपर उठ रहा है।'",
    370: "राधा की स्वर्ण-कांति ने कृष्ण के नील वर्ण को मरकत जैसा हरा कर दिया, और उनके नील वर्ण ने उसकी स्वर्ण-कांति को हरा। राधा-माधव ने विरह में अपने-अपने वर्ण बनाए रखे, किंतु मिलन में वे एक ही वर्ण के हो गए। राधा ने श्याम के कंधे पर अपनी भुजा रखी और वे धीरे-धीरे मार्ग पर चलने लगे। उनकी कटियाँ सागर में मिलती तरंगों की भाँति कभी-कभी आपस में टकरा जाती थीं।",
    377: "'राधा! यहाँ कामदेव राजा है। मधुर वसंत उसका मंत्री है और मलय-पवन उसका अजेय सेनापति। भौंरे उसके गुप्तचर हैं और कोकिल-झुंड उसके दंडाधिकारी। अवज्ञाकारी व्रज-गोपियाँ दंडनीय हैं और पर्वत-गुफाएँ कारागार हैं।'",
    378: "'कोकिलाएँ, जो सचमुच आद्य ध्वनि की प्रतिमूर्ति हैं, आम्र-मंजरियों का रस लेकर मधुर कूजन के लिए अपनी चोंचें खोलती हैं। आम्र-मधु से मत्त भौंरों का मोह इस समय मंजरियों से हट जाता है और वे विश्राम करते हैं। मदोन्मत्त गजराजों में श्रेष्ठ, कामदेव के समान, वह कृष्ण व्रज की मदमाती गोपियों के साथ विचरण करता है, जिनकी मधुर फुसफुसाहट बहते जल की सुखद ध्वनि को भी पराजित कर देती है। कोकिलाएँ चारों दिशाओं में घंटे के समान कूजकर अपने आगमन की घोषणा करती हैं।'",
    385: "ऐसी अपार सामग्री कैसे प्रकट हुई? वृन्दावन के कल्पवृक्षों ने सभी सुगंधित चूर्ण, रंगीन द्रव, लेप, लाख-फूल बम तथा पिचकारी, पुष्प-धनुष और बाण जैसे हथियार प्रदान किए।",
    387: "कुछ सखियाँ क्रीड़ा से अपनी चमकती स्वर्ण-मेखलाओं में फूलों के पराग की थैलियाँ छिपा रही थीं। पराग की थैलियाँ ऐसी लग रही थीं, मानो लंबे समय से संचित उनकी प्रेम-कला की संपदा हो, जिससे कृष्ण के मन-रत्न को क्रय किया जाएगा। अन्य सखियों ने रत्न-खचित थालों में लाख की कोमल शीशियाँ धारण कीं, जो अगुरु, कस्तूरी, कपूर और चंदन से भरी थीं।",
    388: "कृष्ण ने एक नवीन आम्र-मंजरी तोड़कर क्रीड़ा से अपने एक कान पर लटका लिया, जो उनके सुंदर रत्न-कुण्डलों के भार से थोड़ा लंबा हो गया था। कृष्ण के मनोहर कुण्डलों के झूलने से उनके गालों पर अद्भुत प्रतिबिंब पड़ते थे। उन्होंने माधवी पुष्पों की माला गले में डाल ली और अपनी सुंदर, उछलती घुँघराले अलकों के नीचे छिपा लिया।",
    389: "सूर्य के समान लाल महीन चूर्ण ने समस्त आकाश को ढक लिया। धीरे-धीरे नीचे उतरते हुए उसने कृष्ण की पगड़ी, अलकों, पलकों और तिलक को रंगा और सुगंधित कर दिया।",
    390: "कृष्ण ने अपनी वंशी पर मधुर, अव्यक्त स्वर कंपित करके युवा गोपियों के गायन-कौशल के चिर-प्रतिष्ठित गर्व को पराजित कर दिया। गोपियों ने उत्तर में कृष्ण को घेरकर आनंद से केसर-चूर्ण की वर्षा की, जबकि उनकी चूड़ियाँ झंकृत हो रही थीं।",
    404: "विशाखा और चित्रा राधा-माधव के दोनों ओर खड़ी होकर एक-दूसरे को देखने से उत्पन्न स्वेद को हटाने के लिए चामर डुला रही थीं।",
    411: "कृष्ण ने अपने हाथ से बनाए पुष्प-आभूषण प्रसन्नतापूर्वक राधा को भेंट किए। तथापि अपने मन के गहरे रूठने-भाव के कारण उन्होंने उन्हें धारण करने से मना कर दिया।",
    412: "कृष्ण ने किशोरी का रूठा मन तोड़ने का प्रयास करते हुए कहा—'हे देवी! आप व्यर्थ ही क्रोधित हैं। आपके आग्रह पर मैंने स्वयं यहाँ पुष्प तोड़े हैं। आप मुझसे बात करने से क्यों इनकार कर रही हैं? हे राधा! मेरी प्रिया-सखी! अब मैं जान गया कि तुम्हारा नाम राधा क्यों है (राध का अर्थ है नाश करना या तृप्त करना)। धूर्तता मत करो।\nबस आज्ञा दो, मैं तुम्हारे कानों को कुछ पुष्पों से सजा दूँ।'",
    413: "'हे राधा! यदि तुम मुझ पर क्रुद्ध हो, तो तुम्हारे गाल हर्ष से कैसे लाल हो रहे हैं?' श्याम की चंचल बातें सुनकर राधा अपनी मुस्कान नहीं रोक सकीं। तब व्रज के शूरवीर राजकुमार कृष्ण ने राधारानी का चुंबन किया।",
    421: "वर्षा-ऋतु की देवी ने दिव्य आनंद के विभिन्न लक्षण प्रकट किए। पृथ्वी ने प्रस्फुटित मालती-पुष्पों के समूहों से मधुर मुस्कान बिखेरी। वन की अलकें कदम्ब-पुष्पों के रूप में खड़ी हो गईं और आकाश ने मूसलधार वर्षा के रूप में अश्रु बहाए। इन तीनों ने आनंदमय वर्षा-वन में अपना स्नेह फैलाया।\nवर्षा-ऋतु के ललाट पर तिलक के रूप में इंद्रधनुष था और उसकी श्याम अलकों को स्वर्ण-केतकी पुष्प सुशोभित कर रहे थे। उसके गले में लटकती निर्मल बालक-पुष्पों की माला उसके उन्नत वक्षों के नव-निर्मित उभरे मेघों पर टिकी हुई थी। इस प्रकार वर्षा-ऋतु की देवी ने कृष्ण के मन को उद्दीप्त किया।\nवर्षा-वन में मेघ-गर्जन गूँज रहा था। चातक पक्षियों ने उसे सुना और वर्षा को बुलाने के लिए करुण स्वर में कूजने लगे। उत्तर में गर्जते मेघ चातकों को सांत्वना देते प्रतीत हुए, मानो कह रहे हों—'शोक मत करो, मैं वर्षा की धाराएँ बरसाऊँगा।' गर्जनशील मेघ घूमती चक्की के समान सुनाई दे रहे थे, जो मनुष्य के गर्व को पीस डालती है। मेघों की गर्जन मृदंग की गंभीर मधुर ध्वनि के समान गूँज रही थी, जो मोरों को उन्मत्त नृत्य करने की प्रेरणा देती थी। वह उन मंत्रों के समान थी, जो विरहिणी स्त्रियों के प्राणवायु को जीवित करते हैं।\nवन ध्वनियों की सिम्फनी से भरा था। हर ओर दात्यूह पक्षी और श्वेत सारसों के झुंड पुकार रहे थे, मेंढक टर्रा रहे थे और मोर 'केका, केका' करके विलाप कर रहे थे। मेघ गरज रहे थे, वर्षा-बूँदें टिपटिप-टिपटिप की ध्वनि कर रही थीं और जल-धाराएँ 'झपट, झपट' कहकर कलरव कर रही थीं। ये मधुर मधुर ध्वनियाँ प्रियतम का आनंद लेने के बाद स्त्री को सुलाने के लिए उपयुक्त थीं।\nऋतु के पोषक जल ने वृक्षों और उद्यानों को सुंदर बना दिया। आम्र-वृक्षों के प्रचुर पक्के फलों ने वन के मध्य भाग को स्वर्ण-आभा से रंग दिया। पक्के जामुन के वृक्षों ने श्याम-आभा उत्पन्न की। वृक्षों के परे केतकी वृक्ष की नुकीली सूई-जैसी पत्तियों और पुष्पों से उत्पन्न पीली कांति थी। इन सब रंगों से वृन्दावन के उद्यान चित्रित चित्र के समान सुंदर दिख रहे थे।",
    422: "राधा-माधव ने वन की शोभा का आनंद लिया और शीघ्र ही कदम्ब-ताल तक पहुँचे। जिन वृक्षों की ऊँची श्यामल शाखाओं पर अनगिनत पीले कदम्ब-पुष्पों से मधु की धाराएँ बह रही थीं, उन्होंने बिजली से विभूषित मेघों की शोभा को पराजित कर दिया। कदम्ब-वृक्षों के बीच अत्यंत लंबे चबूतरे कृष्ण के आनंद के बाँध प्रतीत हो रहे थे। कदम्ब-पुष्प चबूतरों पर निरंतर मधु छिड़कते थे और सुंदर निद्रारहित भौंरे उनकी रक्षा करते थे। प्रत्येक चबूतरे के दूरस्थ किनारों पर ऊँचे कदम्ब-वृक्षों के जोड़े खड़े थे, जिनकी ऊपरी शाखाएँ आपस में गुंथकर मरकत-शिखरों वाली छतें बनाती थीं। प्रस्फुटित पुष्पों ने झालरों का रूप धारण कर लिया था।",
    426: "जोरदार झूलने के कारण राधा और कृष्ण की अलकें उनके कुण्डलों में उलझकर बिखर गईं। उनकी कटि की पुष्प-सूत्र रत्न-घुँघरुओं से उलझ गईं। उनकी मुरझाई मालाएँ चूड़ियों में अटक गईं।",
    437: "इसके बाद माधव उस वन में गए, जो शिशिरमोद (हिम-ऋतु का आनंद) कहलाता था, वहाँ के प्रेमपूर्ण स्नेह का प्रत्युत्तर देने के लिए। वन ने कृष्ण के आगमन की चिंता में हर्षाश्रु बहाए और ओस की बूँदों के रूप में अश्रु बहाए। उसने अपने प्रस्फुटित कुंद-पुष्पों से मुस्कान बिखेरी, जिससे उसके सुंदर श्वेत दाँत दिखाई दिए। ऋतु ने अपने प्रियतम के विरह में शोक करते हुए दमनक-गुल्मों के रूप में अपनी अलकें खोल दीं, जो प्रातःकालीन सूर्य की किरणों में चमक रही थीं।",
    444: "यद्यपि कृष्ण उनके सामने खड़े थे, तथापि गहन आसक्ति से उत्पन्न विरह-वेदना से राधा का मन और बुद्धि विह्वल हो रहे थे। राधा ने अपने दाँतों के बीच तिनका दबाया और गहरी साँस लेकर कहा—'हे सखी! कृपया मुझे कहीं कृष्ण दिखाओ!' यह देखकर कृष्ण भी विस्मित हो गए।",
    453: "एक अन्य बातूनी गोपी अस्पष्ट, लड़खड़ाते शब्दों में बोली—'क्या दुर्भाग्य है! दे-देखो! आकाश गि-गिर रहा है! पृथ्वी घू-घूम रही है! हे प्रभो, मेरा सुकुमार शरीर काँ-काँप रहा है। कृपया मुझे था-थाम लो, पहले मैं गि-गिर न जाऊँ।' तब भयभीत उस मदमाती गोपी ने कृष्ण के गले को अपनी भुजाओं से कसकर पकड़ लिया।",
    465: "ललिता ने उत्तर दिया—'हे माधव! राधा के प्रति अपना प्रेम प्रकट करके आपने उनके चरणों की लालिमा को अपने वक्ष पर कौस्तुभ-मणि के रूप में प्राप्त किया है। आपने राधा के नेत्रों को अपने पान-रंजित अधर भेंट किए और बदले में अपने अधरों को उनके काले काजल से रंग लिया। वास्तव में, आपकी प्रेम-कुशलता आपके अपने अंगों पर भी समान रूप से प्रकट है।'",
    470: "राधा ने कृष्ण की ओर तिरछी दृष्टि डाली, परंतु वे बोलते रहे—'मेरी प्रिय चंद्र-मुखी राधारानी! क्या बिजली की चमक ने आपके चंचल कटाक्ष से वेगपूर्वक चलने की कला सीखी है? या आपके कटाक्ष ने बिजली की चमक से चंचलता सीखी है? हे राधा! किसी भी प्रकार, मेरा विचार है कि आपका कटाक्ष ही गुरु होना चाहिए, क्योंकि उसने मेरे चंचल मन को पूर्णतः बंदी बना लिया है।'",
    481: "राधा सारे कोलाहल के बीच खिसककर स्वर्ण-कमलों के गुच्छे के बीच छिप गईं। कृष्ण ने उत्सुकता से राधा की खोज की। उन्होंने एक-एक कर पीले कमलों का चुंबन किया, यह समझकर कि वही राधा का मुख है। राधा और उनकी सखियाँ अनियंत्रित हँसी में फूट पड़ीं। कृष्ण ने राधा का छिपने का स्थान जान लिया और तुरंत उनके पास पहुँच गए।",
    501: "'हे प्रभो! वृन्दावन के कामदेव! आपकी जय हो! आपकी परम प्रिया गोपी दिव्य देवी है और आप सबके शिरोमणि हैं। आपके चरण-कमलों का मधु आनंद और ज्ञान की धाराओं से भी मीठा है। हे गोविन्द! समस्त ब्रह्मांडों के बीज-रूप आपकी महान मूर्ति को मैं बार-बार प्रणाम करता हूँ।'",
    516: "'मुझे कृष्ण की भुजाएँ स्मरण हैं, जो प्रेम-उत्सव में व्रज-गोपियों के हृदयों को झूलानेवाले झूले के रत्न-स्तंभों के समान हैं। कृष्ण की लंबी भुजाएँ कामदेव-युद्ध में राधा की पराजय की घोषणा करनेवाले विजय-स्तंभ के उच्च द्वार-स्तंभ हैं। वे असुरों को पराजित करनेवाले महायज्ञ के यूप-स्तंभ हैं, या माधुर्य और संयोग-प्रेम नामक गजराजों की सूँड हैं।'",
    531: "'माधव का दिव्य स्वरूप सनातन ज्ञान और आनंद से संघनित है। गोविन्द के शरीर की नील-कांति मेघ-समूह के समान चमकती है। श्याम का तेजस्वी शरीर, जो प्रेम-श्रम से दीप्त गोपियों के मनोहर कटाक्षों से सदा विचलित रहता है, तीनों लोकों के प्रेम का आश्रय है। मेरे मन में कृष्ण की अद्वितीय दिव्य मूर्ति सदा प्रकट रहे!'",
    532: "तोते ने निष्कर्ष कहा—'और क्या कहूँ! कृष्ण का अलौकिक शरीर सबके नेत्रों पर आनंद की वर्षा करने वाला मधुर रस का अनंत सागर है। कृष्ण के सुंदर अंग उनके आभूषणों की शोभा को भी बढ़ा देते हैं। कृष्ण के महान शरीर की अनोखी सुंदरता का सहस्र मुख वाले स्वयं भगवान अनंत भी पूर्ण वर्णन नहीं कर सकते।'\nनर और मादा तोते प्रेमावेश से गद्गद होकर चुप हो गए। तोतों के वचनों के रस-सागर में डूबी सखियाँ क्षण भर आनंद-विह्वलता में स्तब्ध रह गईं।",
    537: "'प्रेम से विह्वल व्रज-गोपियों ने एक बार कृष्ण की वंशी को संबोधित किया—हे प्रिय सखी! हे क्रूर वंशी! तुम संगीत के वेश में एक क्षण अमृत की बाढ़ और दूसरे क्षण विष की बाढ़ उत्पन्न करती हुई प्रतीत होती हो। तुम एक साथ हमें सजीव और अर्धमृत कर रही हो। तुम हमारे भीतर ऐसी रहस्यमयी स्थिति उत्पन्न कर रही हो, जिसे हम न समझ सकते हैं, न सहन कर सकते हैं।'",
    540: "'हे नंदनंदन, आपकी जय हो! आप सभी रसों के कारण हैं, प्रेम के विषय और आश्रय दोनों हैं। आप व्रज-रस की मूर्ति हैं। आपके सुंदर चरण-कमल अद्वितीय गुणों से विभूषित और निरंतर बढ़ते हुए दिव्य अमृत से युक्त हैं। आपके माणिक्य-समान नखों की तेज किरणें भक्तों के हृदयों से शोक के अंधकार का नाश करती हैं। आपकी सुंदर श्यामल वर्ण-कांति निष्कलंक और अद्भुत आकर्षक है। आपकी कीर्ति समस्त ब्रह्मांड में फैली है। अनंत सौंदर्य, ऐश्वर्य, धैर्य और पराक्रम से युक्त नील-वर्ण वाले गोप-बालक, आपकी जय हो।'",
    541: "'हे कृष्ण, वंशी-वादन में निपुण! प्रफुल्ल शरद-कमलों से भी अधिक आकर्षक अपने नेत्रों की चंचल चेष्टाओं से आप सिद्ध और चारण-स्त्रियों के धैर्य का नाश करते हैं। आपके दीप्तिमान कुण्डल मोती की मालाओं में सुंदर झलकते हैं। आप गोवर्धन के अनेक शीतल कुण्डों में क्रीड़ा करते हुए समय बिताते हैं। आपका शरीर संघनित ज्ञान से बना है और सभी आभूषणों का आभूषण है।\nआपने सहज ही क्रूर वृषभासुर का वध किया। आपकी चमकदार श्याम अलकें तेजस्वी मोरपंख से सुशोभित हैं और आपका सुंदर मुख करोड़ों चंद्रमाओं से अधिक दीप्त है। आप व्रज के एकांत निकुंजों में प्रेम की सभी कलाओं में निपुणता प्रदर्शित करते हैं। आपकी कोमल, सर्प-समान भुजाएँ सखियों के उन्नत वक्षों को आलिंगन करने के लिए सदा तत्पर रहती हैं।\nवृन्दावन में चलते समय आप ऐसे लगते हैं जैसे तमाल-वृक्ष चल रहा हो। आप अपने प्रिय व्रजवासियों की सभी इच्छाएँ पूर्ण करते हैं। आप दाएँ हाथ की छड़ी से गायों की रक्षा करते हैं। आपकी चमकती कांति करोड़ों सूर्य-चंद्रों को ग्रहण कर लेती है। आपके ललाट पर गोरोचन-तिलक शोभायमान है। बाल मुनि सनक-सनंद सदा आपके मनोहर गुणों का रस लेते हैं। हे सुंदर वीर! मुझ पर कृपा करके स्वयं को मुझे दर्शन दीजिए!'",
    542: "'हे केशव, आपकी जय हो, जिनकी ब्रह्मा, शिव और अनंत बार-बार स्तुति करते हैं। आपके चरण-कमलों पर ध्वजा, वज्र और अंकुश के अनोखे चिह्न, तथा आपकी अनंत ब्रह्मांडीय शक्ति स्पष्ट रूप से आपको परमेश्वर सिद्ध करती हैं। अपने ऐश्वर्य के बावजूद आप निश्चिंत क्रीड़ाओं में विचरते हैं और कालिय जैसे मूर्ख प्राणियों से युद्ध करते हैं। आप भक्तों के आनंद को बढ़ाने तथा गोकुलवासियों के सुख में वृद्धि के लिए नंद के मासूम पुत्र की भूमिका निभाते हैं। आपकी अचिंत्य सुंदरता से स्वयं कामदेव भी मोहित हो जाता है। यद्यपि व्रज-गोपियाँ कभी प्रेम-ईर्ष्या के क्रोध में रूठती हैं, तथापि आपकी अद्भुत सुंदर मूर्ति देखते ही वे रुक जाती हैं। आप स्वर्ण-कांति गोपियों के साथ नृत्य करके और उनके सुंदर वक्षों को आलिंगन करके रास का रस लेते हैं। आप सैकड़ों वन-निकुंजों में व्रज-कन्याओं के साथ विहार करते हैं।\nगोपियों में से कोई भी आपको राधिका के समान संतुष्ट नहीं कर सकती, जो व्रज की सभी सुंदरियों की शिरोमणि हैं। जब आप ललिता और अन्य गोपियों के साथ रास-मण्डल में उत्साहपूर्वक नृत्य करते थे, तब आपका मोरपंख और अन्य आभूषण भूमि पर गिर गए। यद्यपि नृत्य की थकान से आपके नेत्र लड़खड़ाते थे, तथापि राधिका को देखते ही वे तुरंत आनंद से खिल उठे। सभी आपको प्रणाम करते हैं! क्रोधित असुर भी आपकी कृपादृष्टि से मुक्त हो जाते हैं। आप सदा व्रजवासियों की रक्षा करते हैं और भक्तों को आनंद देते हैं। हे कृपा-सागर, कृपया मुझे भौतिक संसार के सागर से उद्धार कीजिए!'",
    543: "'राधारानी वृषभानु-कुल के सागर से उत्पन्न अमृत की सुंदर अर्धचंद्रा हैं। राधा के मनोहर माँग-सिंदूर की रेखा मधुर अमृत-नदी के समान दिखती है। मेरी प्रार्थना है कि मेरा मन सदा राधिका पर स्थिर रहे, जो कृष्ण का दिव्य स्वरूप और गुण सुनते ही प्रेम से स्तब्ध हो जाती हैं। किशोरी अपनी सुंदर वेणियों को कोमल, सुगंधित जूही-पुष्पों से बाँधती हैं। राधा के बड़े कमल-नेत्र, काम-विकार से चंचल, खंजन पक्षियों की गतियों को लज्जित करते हैं।\n'राधा की चाल राजसी मदमाते गजराज की गति से भी अधिक लालित्यपूर्ण है। किशोरी के मधुर स्वर्ण-अंग स्वर्ण-चम्पक के दलों से भी अधिक मनोहर हैं। राधारानी की कोमल भुजाओं की स्वर्ण-लताएँ रत्न-जड़ित बाजूबंदों और चूड़ियों से सुशोभित हैं। राधा के दिव्य स्वरूप की अद्भुत सुंदरता सदा व्रज की सभी सुंदर कन्याओं को मोहित करती है।\n'राधारानी का धीरे-धीरे मुस्कुराता मुख पूर्ण चंद्रमा की शोभा को जीत लेता है। संघनित नवीन माधुर्य राधा के सुंदर विस्तृत कटि-प्रदेश के रूप में प्रकट हुआ है, जो घुँघरुओं की डोरियों से बँधा है। एक अद्भुत रंगीन चोली राधिका के सुंदर स्वर्ण-कुम्भों के उन्नत वक्षों को छिपाए हुए है। राधा के चमकते लाल अधर श्याम के मन में उस अमृत का रस लेने की गहरी लालसा भर देते हैं। राधारानी की सुडौल ठुड्डी कस्तूरी के मनोहर बिंदु से सुंदर रूप से विभूषित है। राधा की सुंदर नासिका से स्वर्ण और रत्नों से जड़ा एक बड़ा दीप्तिमान मोती लटकता है।\n'राधिका का आनंदमयी दिव्य स्वरूप सौंदर्य-सागर का सार है, जो श्याम के प्रति प्रेम की तरंगों से उठता है। कृष्ण के नेत्रों का हिरण राधा के मनोहर नाभि-नामक अमृत-कुएँ में गिर गया है। राधा के दिव्य शरीर को लाल साड़ी घेरे हुए है, जो उनके दीप्तिमान कुण्डलों, हारों और नूपुरों से और भी अधिक चमकदार हो गई है। जब भी किशोरी वन-मार्ग पर गोकुलचंद्र के चरण-चिह्न देखती हैं, तो वे प्रेमावेश से काँप उठती हैं। जिनके हृदय व्रज-रस का अमृत पान करने के लिए लालची हैं, उन्हें वृन्दावन के भावों के पारखी विद्वानों के वर्णन के अनुसार राधिका के अद्वितीय सुंदर दिव्य स्वरूप का गुणगान करना चाहिए।",
    550: "चम्पाकलता ने कहा—'राधा के दाँत जूही-पुष्पों के समान श्वेत और हीरे के समान तेजस्वी हैं। कृष्ण के अधर-बिम्बों को चबाने से राधा के दाँत-रूपी तोते की चोंचें माणिक्य जैसी लाल हो गई हैं।'",
    551: "रंगदेवी ने कहा—'यह अनुभव करके कि कृष्ण के नाम-यश का युवा युगल झूलने की लीला करने के लिए उत्सुक है, विधाता ने राधा की जिह्वा का झूला बनाया और उसे किरमिजी चादर से ढक दिया।'",
    553: "वसंती ने कहा—'कृष्ण के अद्भुत गुण राधा के हृदय-उद्यान में कल्प-लता की भाँति बढ़ते हैं। उनके पुष्प राधा की मधुर मुस्कान के रूप में प्रस्फुटित हो रहे हैं।'",
    554: "विशाखा ने कहा—'विधाता ने कृष्ण के चकोर-नेत्रों को प्रसन्न करने के लिए ही राधा के मुख का अद्वितीय पूर्ण चंद्रमा बनाया। उन्होंने चंद्रमा पर राधा के नेत्रों के रूप में दो हिरण रखे। हिरणों को चंचल देखकर विधाता ने उन्हें राधा के कानों की दो रस्सियों से बाँध दिया।'\nचम्पाकलता ने कहा—'चंद्रमा कलंक से दूषित है, ग्रहण से ग्रस्त होता है और अपने स्पर्श से सुंदर कमल-पुष्पों को बंद कर देता है। अतः राधा के मुख के निर्मल, पूर्णतः शुद्ध और सदा पूर्ण तेजस्वी मण्डल की तुलना किससे की जा सकती है?'\nचित्रा ने कहा—'कृष्ण राधा के सुंदर गालों को देखकर अपनी तीव्र प्यास बुझाते हैं, जो स्वर्ण-दर्पणों के गर्व को नष्ट कर देते हैं। राधा के सुंदर गाल स्वर्ण-लोक के दो सरोवरों के समान प्रतीत होते हैं, जो दीप्तिमान अमृत से भरे हैं। उन सरोवरों के ऊपर राधा के कमल-कलिका-कुण्डल लटकते हैं। राधा के गालों पर कस्तूरी के चित्र सरोवरों की सेवार हैं, जिनमें राधा के कुण्डलों की दो मकरी (मादा मगरमच्छ) तैरती हैं।'",
    555: "सुदेवी ने आगे कहा—'राधा की नासिका की सुंदर वक्र रेखा तिल-पुष्प के समान है। वह उस तूणीर के समान भी दिखती है, जिसमें कामदेव नामक धनुर्धर अपने बाण रखता है। जब राधा मुस्कुराती हैं, तो ये बाण कृष्ण के हिरण-जैसे हृदय को बींध देते हैं।'\nमाधवी ने कहा—'अज्ञानी कवि कहते हैं कि प्रियाजी की नाक के नीचे लटकता मोती राधा के अधरों की लालिमा और नेत्रों के काजल की श्यामता के प्रतिबिंब से गुंजा-बीज के समान लाल और काला हो गया है। वास्तव में, राधा का हृदय अपने प्रियतम का निरंतर चिंतन करने से श्याम वर्ण का है। राधा का हृदय कृष्ण के प्रति तीव्र आसक्ति के कारण गहरे लाल रंग का भी है। जब भी राधा साँस लेती हैं, ये दोनों रंग उनकी नाक के मोती पर प्रतिबिंबित होते हैं।'\nवसंती ने कहा—'विधाता ने ब्रह्मांड की प्रत्येक सुंदर वस्तु का मधुर सार संग्रह करके राधा के आकर्षक नेत्र बनाए। शेष अंश भूमि पर गिरकर भौंरे, मृग-नेत्र, चकोर, कमल, मीन और कुमुदिनी बन गए।'",
    568: "'हे राधा! यदि एक साथ अनेक पूर्ण चंद्रमा उदय होकर अनगिनत ब्रह्मांडों को शुद्ध प्रेम के अमृत-प्रकाश से भर दें, तो भी वह बाढ़ वृन्दावन के निकुंजों में दिखने वाले आपके सुंदर मुख की अद्भुत कांति का केवल हल्का-सा संकेत दे सकती है।\n'सदा नवीन मधुर प्रेम की अधिष्ठात्री देवी, जिनका स्वरूप संघनित आनंद है, जो यमुनातट के कल्पवृक्षों के नीचे भव्य लीलाएँ करती हैं, जो अपनी अंतरंग सखियों के भावों से उद्दीप्त होती हैं, और जिनके चरण-कमल भक्तों के हृदयों में अमृत की धाराएँ प्रवाहित करते हैं, वे राधा हमारे सम्मुख प्रकट हों!",
    593: "कृष्ण ने अपने कौस्तुभ-मणि का शर्त हार दिया। उस समय सखियों ने कहा—'यह मणि तो पहले ही अनेक गोपियों के वक्षस्थलों का स्पर्श कर चुकी है, अतः यह हमारी प्रिय सखी कैसे पहने? इसे चूड़ी से बदल देना चाहिए, या कई बार धोकर शुद्ध करना चाहिए।'",
    602: "विश्वशर्मा ने आगे कहा—'हे भाग्यवती कन्या! अब जब आपने देवता की पूजा कर ली है, तो आकाश में चमकते सूर्य-ग्रह को अर्घ्य-जल अर्पित कीजिए।' (आंतरिक अर्थ: हे भाग्यवती कन्या! अब जब आपने देवता की पूजा कर ली है, तो आप अपने महान जीवन-मित्र की पूजा कर सकती हैं, जो चमकते पीत-वस्त्र धारण किए आपके सम्मुख खड़े हैं।)",
    615: "चंदनकला ने आगे कहा—'हे प्रिया-सखियों! कृष्ण ने श्रीदामा जैसे मित्रों के साथ उत्साहपूर्वक क्रीड़ा की, जो अपने गर्वित वचनों के अमृत-कणों से कृष्ण का सिंचन करके करोड़ों हृदयों से उनके नखों की तेज किरणों की पूजा करते हैं। सख्य-रस की मूर्ति कृष्ण यमुनातट पर अपने अंतरंग मित्रों के साथ समय बिताते थे।'",
    657: "'कृष्ण और बलराम के वस्त्र तथा आभूषण भोजन करने से गंदे हो गए थे, अतः उन्होंने उन्हें बदलकर नए वस्त्र धारण किए। दिव्य बालकों ने सावधानी से अपने चरण धोए और मसालों से अपना मुख ताज़ा किया।'",
    677: "'हे राधा! आपके अद्वितीय चतुर प्रियतम किसी की दृष्टि में न पड़कर महल से निकल गए। वे अब यमुनातट के मिलन-स्थल पर आपकी प्रतीक्षा कर रहे हैं। आप कुछ खा-पी लीजिए, अपने बड़ों को धोखा देकर उनसे मिलने के लिए प्रेमावेश में दौड़िए।'\nयह कहकर इंदुप्रभा चली गईं।",
    682: "'हे सखी! कृष्ण का वक्ष सभी स्त्रियों के दृढ़-संकल्प की नदी का विशाल बाँध है। उनके वचनों की चंद्रिका स्त्री-सतीत्व के कमलों को जबरदस्ती बंद कर देती है। माधव की दो भुजाएँ हमारे चिर-परिचित लज्जा के विनाश के तांत्रिक यज्ञ के स्तंभों के समान हैं। हाय दुर्भाग्य! उनकी चंचल सर्प-समान भौंहें हमारी इंद्रिय-संयम और संकोच का भक्षण करती हैं।'",
    693: "गोविन्द-स्थल में ऐसे कल्पवृक्ष भरे थे, जो हर इच्छा पूर्ण करते थे; पारिजात वृक्ष, जो सभी शत्रुओं का नाश करते थे; मंदार वृक्ष, जो दरिद्रता का नाश करते थे; और संतान वृक्ष, जो सब प्रकार का आनंद प्रदान करते थे।",
    702: "वृन्दा ने कहा—'हे सुकुमारी राधा! जब आप कदम्ब-वृक्ष के नीचे स्थित लीला-कुटिया में बैठे गोपराज-कुमार की ओर देख रही थीं, तब आपके कटाक्षों की तरंगें, मानो क्षीर-सागर से उठी तरल सौंदर्य धारा, श्यामल यमुना को श्वेत गंगा में बदल रही थीं।'",
    708: "विनम्र प्रार्थना के साथ वृन्दा और उनकी वन-देवियों ने राधा-माधव और सखियों को रत्न-मंदिर से उस स्वर्ण-सिंहासन तक ले गईं, जो चंद्रिका से आलोकित तथा सुगंधित पुष्पों से सज्जित था। आकर्षक सिंहासन कोमल मखमली चादर से ढका था और यमुना की शीतल बयार से शीतल था। सखियों ने युगल को सिंहासन पर बैठाकर वृन्दा के भंडार से लाए पान-सुपारी, शीतल जल और सुगंध परोसे। उन्होंने राधा-गोविन्द को रंगीन पुष्प-मुकुट, आभूषण और मालाएँ अर्पित कीं। मञ्जरियों ने उनकी सेवा में चामर डुलाए। सुखद चांदनी रात्रि, शीतल मनोहर वन और दीप्तिमान यमुनातट ने गोविन्द को अपनी प्रिया गोपियों के साथ रास-नृत्य मनाने की प्रेरणा दी।",
    709: "कृष्ण ने गोपियों के साथ एक-एक करके अपने रास-उत्सव के विभिन्न रूपों का आनंद लिया। उन्होंने वन-विहार किया, विचरण किया और वृत्ताकार नृत्य (चक्र-भ्रमण) किया। उन्होंने स्त्रियों का वृत्त-नृत्य (हंसक), युगल-नृत्य (युग्म-नृत्य), पुरुष-नृत्य (तांडव), स्त्री-नृत्य (लास्य) और एकल नृत्य किए। उन्होंने स्व-रचित गीत गाए, प्रेम-भाव से नृत्य किया, हँसी-मजाक किया और जल में क्रीड़ा की।\nवृन्दावन का वन चांदनी में मनोहर रूप से दमक रहा था और कृष्ण की उपस्थिति से वसंत की छटा के साथ खिल उठा था। पत्तों की सरसराहट, भौंरों की गुंजार, कोकिलों का कोमल कूजन सुनकर और मोरों का मदमाता नृत्य देखकर कृष्ण सखियों के साथ क्रीड़ा करने के लिए प्रेरित हुए। कृष्ण ने अपनी वंशी के स्वरों से अपनी इच्छाएँ प्रकट कीं। गोपियों ने बार-बार कृष्ण के नामों का गान करके सहमति दी।\nकृष्ण ने कहा—'हे मेरी प्रियतमाओं! मैं आपके साथ उस आकर्षक वन में क्रीड़ा करना चाहता हूँ, जो प्रस्फुटित पुष्पों से भरा है और मनोहर चांदनी में चमक रहा है।'\nगोपियों ने उत्तर दिया—'हे कृष्ण, कृष्ण, कृष्ण, कृष्ण! हे प्रियतम, ऐसा ही हो!' \nकृष्ण और सखियाँ उठकर मधुर स्वरों में कोमल गीत गाते हुए वृक्षों और लताओं के नीचे बने निकुंजों में विचरण करने लगीं।",
    710: "कोकिलों के प्रेम-पूर्ण कूजन ने सबके कानों को शांत किया। मधु से भरी माधवी-पुष्पों की सुगंध लिए कोमल दक्षिणा-पवन ने वातावरण की मिठास बढ़ा दी। मदमाते युवा भौंरों के झुंड मल्लिका-लताओं पर अर्ध-विकसित पुष्पों का मधु पीते हुए विचर रहे थे। उनकी जोरदार गुंजार वसंत-ऋतु के शंख-ध्वनि के समान लग रही थी। प्रेम-विह्वल हंस और पुकारते सारस अनेक सरोवरों में आनंद से चक्कर लगा रहे थे। प्रस्फुटित कमल-समूहों में भौंरे प्रेममय रूप से इधर-उधर उड़ रहे थे।",
    711: "पक्षियों ने चारों दिशाओं में आनंद से 'जय! जय!' का गान किया। लताएँ मुस्कुराईं और वृक्षों के पत्ते खड़े हो गए। अपनी प्रियतमाओं से वार्तालाप करने के लिए उत्सुक हिरण समूहों में खड़े होकर दृश्यों को देखकर विस्मित हो रहे थे। आनंदमयी पुष्पों ने अपने अमृत-अश्रुओं की बूँदों से भूमि को गीला कर दिया। कृष्ण पृथ्वी पर चलते हुए नवीन मेघ के समान प्रतीत हो रहे थे। अपने दीप्त चंद्रमुख पर मधुर मुस्कान धारण किए श्रीहरि ने, अपने चारों ओर बिजली की माला के समान घिरी सुंदर मुख वाली गोपियों के साथ विहार करते हुए, विश्व को आनंद की तरंगों से भर दिया।\nदामोदर पैरों तक लटकती सुगंधित माला धारण किए, भौंरों की गुंजार-पवन से हिलती हुई, वृक्षों और लताओं के बीच मधुर गीत गाते हुए और अपनी वंशी बजाते हुए चल रहे थे। युवा गोपियाँ श्याम के साथ धीरे-धीरे चलती थीं और प्रेम-आकुलता से भरी अपनी मधुर कंठध्वनि में उत्साहपूर्वक उनके चरित्र की प्रशंसा करती थीं। माधव अपने नख से पत्तों पर प्रेम-संदेश लिखकर अपनी प्रिय सखियों को देते थे।\nकृष्ण ने स्वयं सर्वोत्तम पुष्प, पत्ते और लताएँ चुनीं। फिर कृष्ण ने सखियों को सजाने के लिए चोली, बाजूबंद और अन्य आभूषण बनाने की अपनी प्रतिभा दिखाई। माधव ने सखियों के चरण और हाथ पुष्प-पराग से रंग दिए। क्षण भर में ही कृष्ण ने मालती-पुष्पों के हार, कदम्ब के ललाट-आभूषण, स्थल-कमल के कुण्डल, कुंद-पुष्प के गले के हार और बकुल, केसर तथा नाग-केसर के कटि-बंध बना दिए। श्याम ने गोपियों की अलकों में पुष्प-पराग उड़ाया और उनके गालों को लोध्र-पराग से रंग दिया।\nगोपियों ने बदले में कृष्ण के कानों में केसर-पुष्प, अलकों में केतकी-पुष्प और वक्ष पर मालती-पुष्प लगाए। एक गोपी ने कृष्ण की पगड़ी पर अशोक-पुष्प रखे। दूसरी गोपी ने उन्हें जूही-पुष्पों के कंगन-बाजूबंद अर्पित किए और बकुल-पुष्पों की डोरी से उनकी कटि बाँधी।\nमाधव व्रज की सुंदर कन्याओं के साथ अंतरंग लीलाओं का रस लेने के लिए वन के एकांत स्थान पर चले गए। जब गोपियाँ प्रेमावेश में खो गईं, तो वृक्षों में कोकिलों के कूजन और मदमाते भौंरों की गुंजार गूँजने लगी। सुंदर गोपियाँ, जिनकी दीप्तिमान स्वर्ण-कांति चांदनी के गर्व को जीतती थी, श्वेत-कमल के महीन स्वर्ण-पराग से प्रसन्नता से कृष्ण के शरीर को छिड़कने लगीं। फिर चूड़ियाँ झंकृत करती गोपियों ने प्रेम का एक नवीन संग्राम आरंभ कर दिया।\nकृष्ण ने गोपियों पर पुष्प-बम फेंककर प्रत्युत्तर दिया। यद्यपि गोपियों ने चारों ओर से पुष्प-पराग की वर्षा की, तथापि कृष्ण ने सरलता से उन्हें पराजित कर दिया। तोते और अन्य पक्षियों ने 'जय! जय!' पुकारकर कृष्ण की विजय की घोषणा की। वीर-गर्व से भरे कृष्ण ने राधिका और उनकी सखियों पर पुष्प-बमों की बौछार की। राधा ने कृष्ण को वश में करने के लिए अपने क्रोधित कटाक्षों की सेना संभाली। राधा के पालतू तोते बार-बार कूजते रहे—'हम जीत गए! हम जीत गए!'\nप्रत्येक क्षण कृष्ण नई-नई आनंद-लीलाओं में लगे रहते थे। राधा ने सुगंधित, मधु-भरे पुन्नाग-पुष्प तोड़ने शुरू किए। कुछ भयभीत भौंरे पुष्पों से फुर्र होकर निकले, जिससे राधा ने शीघ्र ही अपना कमल-हाथ खींच लिया और भय से काँप उठीं। कृष्ण ने कहा—'अरे-अरे! यह तुम्हारे लिए उचित दंड है, क्योंकि तुम पुन्नाग (श्वेत कमल अथवा श्रेष्ठ पुरुष) चुरा रही हो।'\nराधिका ने लज्जा से सिर झुकाया और श्याम की हँसी पर मुस्कुराईं। राधिका पैरों की अँगुलियों पर खड़ी होकर पेड़ की ऊँची डाल पर रंगीन पुष्प तोड़ने के लिए अपनी लता-समान भुजाएँ फैलाईं। राधा का निचला वस्त्र खिसकने लगा। तब राधा ने घबराकर चारों ओर देखा। कृष्ण ने अवसर का लाभ उठाकर चुपचाप राधा के पीछे आकर उन्हें उठा लिया। राधा शर्म से लाल हो गईं।\nएक गोपी, आपदा का बहाना करते हुए, बोली—'मेरी आँखों में कुछ पराग गिर गया है!' अपने कमल-हाथों से आँखें रगड़ने का नाटक करते समय उसकी चूड़ियाँ झंकृत हुईं। कृष्ण, हँसते हुए और चिंता की दृष्टि से, शीघ्र ही उसके पास पहुँचकर बोले—'आओ, देखूँ!' पराग उड़ाने के बहाने कृष्ण उसके मुख के पास गए और कोमलता से उसकी आँखों का चुंबन किया। राधा ने वृक्ष की उन शाखाओं पर पुष्प तोड़ने का प्रयास किया, जो उनकी पहुँच से परे थीं। वृक्ष ने अंतरंग मित्र की भाँति व्यवहार करते हुए स्नेहपूर्वक अपनी शाखाएँ झुका दीं, ताकि राधा सरलता से पुष्प तोड़ सकें।",
    712: "वन में मंदार, हरिचंदन, अगुरु, संतान, चम्पक, पुन्नाग, बकुल, बक, कुरुवक, अशोक, केतकी, जूही, जूही-जाति का पुष्प, माधवी, पाटल, जवा, सेफालिका, मल्ली, मुचुकुंद, कुंद, नवमल्लिका और स्वर्ण-यूथिका जैसे अनेक पुष्पवृक्ष थे। अमरूद, अनार, नारियल, कटहल, केला, आम्रातक, संतरा, रुचक, मधुक, शमीक, कक्कोल, कोविदार, आमलकी, लौंग, लवली, काम-रंग, जम्बी, सल्लकी, करुणालेबु, इमली और कुब्जक के फलों से लदे वृक्ष भी थे।\nफल-पुष्प धारण करने वाले और केवल फल धारण करने वाले सभी वृक्षों के आधार रत्न-खचित भूमि से घिरे थे और विभिन्न प्रकार की लताओं से आलिंगित थे। सुडौल, घनी पत्तियों वाले वृक्षों ने वन की भव्यता बढ़ा दी। वृक्षों के शिखर मरकत-हरे, शाखाएँ स्वर्ण-वर्णी, नव-पल्लव माणिक्य-लाल, पुष्प-कलिकाएँ प्रवाल के समान, प्रस्फुटित पुष्प हीरे के समान और फल वैदूर्य-रत्न के समान थे। वृक्षों के समूह चारों दिशाओं में तेज बिखेर रहे थे।\nवृक्ष रत्न-खचित रेत और गोवर्धन पर्वत से तीव्र उतरती नदियों में प्रतिबिंबित हो रहे थे। उत्तुंग वृक्षों ने सभी प्रकार के पक्षियों से मित्रता की। वर्ष भर वृन्दावन के वृक्ष कल्पवृक्षों की भाँति सभी की इच्छाएँ पूर्ण करते रहे।\nवन अपनी श्याम भूमि, वृक्षों के नीचे अनेक मंडपों, रत्न-मंडपों और रत्न-भूमि से अद्भुत दिख रहा था, जिसकी सतह से रत्न-अंकुर स्वतः उत्पन्न होते थे। वृन्दावन ब्रह्मा द्वारा निर्मित नहीं है; यह राधा-माधव का सनातन दिव्य धाम है। भूमि पर पड़े मरकत-रत्नों की प्रचुरता के कारण वन के कुछ भाग हरे कालीनों से ढके प्रतीत होते थे। हिरण उन 'कालीनों' को कोमल घास के अंकुर समझकर उत्सुकता से वहाँ दौड़ते थे।\nमाणिक्य-रत्नों के टुकड़े वन के छोटे-छोटे क्षेत्रों को ढकते थे। शीत ऋतु में चामरी हिरणियाँ उन्हें प्रातःकालीन सूर्य की उष्ण किरणें समझकर उन टुकड़ों पर खड़ी रहती थीं। कुछ क्षेत्र सर्वोत्तम स्फटिक से ढके थे। ग्रीष्म ऋतु की गर्मी से पीड़ित सांभर वहाँ चंद्रमा की शीतल किरणें समझकर एकत्र होते थे। कुछ भाग नीलमणि से आच्छादित थे। उल्लू, उदीयमान ग्रीष्म-सूर्य की किरणों से भयभीत होकर उसे अंधकार समझकर वहाँ शरण लेते थे।\nछहों ऋतुओं को प्रिय वन की देवी (वनलक्ष्मी) ने अपनी सुंदरता से कृष्ण की सेवा की। उन्होंने वसंत के पुष्प-कलिकाओं के रूप में अपने गले में मोती की माला धारण की। उन्होंने ग्रीष्म की मल्लिका-पुष्पों से अपनी सजावट की। वर्षा ऋतु में उन्होंने कदम्ब-पुष्पों के गुच्छों के रूप में अपने वक्षों को धारण किया। शरद में उन्होंने कमल-गुच्छों से मुस्कान बिखेरी। शिशिर ऋतु में उन्होंने लोध्र-पुष्पों को कुण्डलों के रूप में पहना। हेमंत ऋतु में दमनक-पुष्पों की डोरी से बँधी मधुकर (भौंरों) की वेणी के साथ वे अत्यंत मनोहर दिख रही थीं।\nवन के वृक्षों ने कृष्ण की पूजा के लिए अनेक सामग्री प्रदान की। ओस की बूँदें कृष्ण के चरण-प्रक्षालन थीं, नवीन घास के अंकुर अर्घ्य, मधु आचमन, उत्तम सुगंधियाँ चंदन, श्रेष्ठ पुष्प पुष्पांजलि, चढ़ती भौंरों की पंक्ति धूप और सुंदर कलिकाएँ दीपक थीं। भूमि पर गिरे पक्के फलों से वृक्षों ने कृष्ण को नैवेद्य अर्पित किया।\nचंचल पवन रूपी नृत्य-गुरु से विभिन्न चालें सिखाकर लताएँ कृष्ण के सम्मुख लयपूर्वक झूम रही थीं। भौंरे पार्श्व-स्वर गुनगुनाते थे और लताएँ अपने पत्ते-रूपी हाथ फैलाकर गीतों के अर्थ प्रकट करती थीं। उनके शरीर के विभिन्न अंग आनंद से फूल उठे। वक्ष-रूपी बड़े कलिका-गुच्छों ने अपनी लज्जा और विनम्रता प्रकट की, जबकि प्रस्फुटित पुष्पों ने आनंद की मुस्कान व्यक्त की। एक लज्जित लता ने अपने पत्ते-रूपी हाथों से अपनी पुष्प-मुस्कान ढक ली। दूसरी लता आनंद से विह्वल होकर मधु के अश्रु बहा रही थी। एक लता ने पराग-रूपी वस्त्र से अपने सुंदर वक्ष-रूपी कलिका-गुच्छों को छिपा लिया।\nदूसरी लता ने अपने शरीर से भौंरों के झुंड को झटक दिया। कुछ लताओं ने कोकिलों के कूजन और पवन में हिलते अपने पत्तों से कृष्ण को पुकारा—'यहाँ आओ, यहाँ आओ!' अर्ध-विकसित पुष्पों से मुस्कुराकर लताओं ने अपने आंतरिक आनंद और कृष्ण से मिलन की उत्सुकता व्यक्त की।\nकुछ लताओं ने हरि को देखा और फिर कठोर स्वर में कठफोड़वों के जोरदार शब्द से पुकारा। उन्होंने काले भौंरों की घुमावदार पंक्तियों से भौंहें चढ़ाईं। उन्होंने अपने पुष्पों से क्रोध-मिश्रित मुस्कान प्रकट की। नवीन पत्ते फड़फड़ाकर उन्होंने अस्वीकार व्यक्त किया और पक्षियों की चहचहाहट से कृष्ण को उलाहना दिया।\nश्याम ने लताओं द्वारा प्रकट प्रेम को स्वीकार किया और उन वृक्षों को आनंद प्रदान किया, जिन्होंने अपने फलों और पुष्पों से निपुणता से उनकी सेवा की। कृष्ण वृन्दावन में इधर-उधर विचरते समय अपने चरण-कमलों से रत्न-भूमि और नवीन घास के अंकुरों को स्पर्श करके उन्हें संतुष्ट करते थे।",
    714: "सिंहिनी से भी अधिक सुंदर कृश कटि वाली गोपियाँ श्याम के निष्कलंक गुणों का मधुर स्वरों में गान कर रही थीं। जब श्याम ने पुष्प-अलंकरण के बहाने गोपियों को दुलार किया, तो उनकी इच्छाएँ जाग उठीं कि वे एकांत स्थान में उनके साथ अनियंत्रित प्रेम-लीलाएँ करें।",
    715: "विचरण करते समय कृष्ण कभी-कभी चंद्रमा या लताओं के विषय में अपनी स्वयं-रचित रचनाएँ गाते थे। सखियाँ उत्तर में उन्हीं उपमानों का प्रयोग करके राधा-माधव के प्रेम की महिमा करती थीं।",
    716: "गोपियों ने गाया—'आकर्षक चंद्रमा हमें अपार सुख देने के लिए प्रकट हुआ है। चंद्रमा की सुंदरता सभी आकर्षक युवतियों के मनोहर नेत्रों को आनंदित करती है और उसकी पत्नियों, ताराओं के विरह-भाव को दूर करती है। चंद्रमा रात्रि में खिलनेवाले कुमुदों के हृदयों को सजीव करता है।'\nश्याम और गोपियाँ वृन्दावन के शांत और सुखद वन में विचरण कर रहे थे। श्याम ने अपने लीलामय स्पर्श से लताओं और मुस्कुराती प्रियाओं को रोमांचित कर दिया। भौंरों की गुंजार के साथ कृष्ण और सखियाँ शीघ्र ही वंशीवट-वृक्ष के नीचे के चबूतरे पर पहुँचे।",
    717: "कृष्ण गोपियों के साथ बैठ गए और बहती हुई यमुना को निहारने लगे, जो भगवान को देखकर अत्यंत प्रसन्न थी। यमुना ने अपनी सतह के फेन से कृष्ण पर मुस्कान बिखेरी और पक्षियों के कूजन से उन्हें गीत सुनाया। उसकी सभी इंद्रियाँ कृष्ण से मिलन की अभिलाषा से व्याकुल थीं। उसने कृष्ण के स्पर्श का सुख पाने के लिए अपनी तरंग-रूपी भुजाएँ फैलाईं। श्याम को देखकर उसके लाल कमल-नेत्र आनंद से खिल उठे। श्याम की सुगंध को सूँघने के लिए मगरमच्छ उसकी उठी हुई नासिका के रूप में प्रकट हुए। कृष्ण की गंभीर वाणी और वंशी-ध्वनि सुनने के लिए उसके भँवर-कान व्याकुलता से घूम रहे थे।\nकृष्ण, यमुना की सुंदरता की प्रशंसा करते हुए विहार करना चाहते थे। उठकर श्याम अपनी प्रिय गोपियों के साथ नदी के तट पर चल दिए। यमुनाजी ने अपनी हाथ-रूपी तरंगों से बार-बार उनके चरण-कमलों को कमल-पुष्प अर्पित किए, मानो उनके चरणों को छूकर आदरपूर्वक प्रणाम कर रही हों।",
    718: "कृष्ण यमुनातट पर गोपियों के साथ आनंदित हुए, जहाँ की रेत शीतल थी और जल से आती पवन प्रस्फुटित कमलों की मधुर सुगंध लिए हुए थी।",
    719: "पूर्णिमा के चंद्रमा की किरणों के नीचे यमुनातट कुट्टित कपूर के समान श्वेत दिख रहा था। रेतीले तट कालिंदी की तरंगों से पवित्र और कमल-सुगंधित पवन से आलिंगित थे। दामोदर अपनी सुंदर गोपियों के समूह के साथ क्रीड़ा के उपयुक्त स्थान की खोज में इधर-उधर विचर रहे थे।",
    722: "अपनी मेघ-समान कांति चारों ओर फैलाते हुए श्यामसुंदर स्थिर बिजली के समान चमकती हुई मृग-नयन गोपियों के साथ यमुनातट पर विचर रहे थे। कृष्ण के कुण्डल झूल रहे थे, मंदार-पुष्प की माला चमक रही थी, कटि-बंध और नूपुर झंकृत हो रहे थे और कंधों से चादर खिसक रही थी।",
    723: "बड़े उत्साह से कृष्ण ने गोपियों के साथ अपनी आनंदमयी नृत्य-लीलाएँ आरंभ कीं। कृष्ण अपनी भुजाओं को दो गोपियों के बाएँ-दाएँ कंधों पर रखकर पूर्ण गति से घूमते थे। फिर वे उन दोनों को एक साथ आलिंगन करते थे। तब कृष्ण दोनों गोपियों के बीच स्थान बनाकर शीघ्र ही उनके पीछे चले जाते थे। एक गोपी से अपनी भुजा हटाकर कृष्ण दूसरे के कंधे का सहारा लेकर फिर से उनके सामने आने के लिए चक्कर लगाते थे।",
    724: "कृष्ण ने गोपियों के जोड़ों के बीच तीव्रता से घूमकर और उन्हें आलिंगन करके असीम आनंद का अनुभव किया। चक्कर लगाती गोपियों और कृष्ण के एकाकी श्याम शरीर के संयोग ने चमकती चांदनी और अंधकार के मिश्रण, बिजली और घनघोर मेघों, चम्पक और नील-कमल, तथा स्वर्ण और इंद्रनील के संयोग की सुंदरता को पराजित कर दिया।",
    725: "कृष्ण ने नर्तकियों के बीच खड़ी राधा के चारों ओर एक छोटे वृत्त में नृत्य किया। तब कृष्ण ने अपने वृत्त की परिधि बढ़ाकर शेष गोपियों के चारों ओर नृत्य किया। अपनी नृत्य-लीलाओं का आनंद लेते समय कृष्ण, गोपियों के वृत्त-रूपी रत्न-मंजूषा में दो धागों से मुक्त इंद्रनील-हारों के समान प्रतीत हो रहे थे।",
    727: "वहाँ अनेक गायक, मृदंग-वादक, वीणा और वंशी-वादक प्रसन्नतापूर्वक बजा रहे थे। करताल-निपुण ताल धारण किए थे। नाट्य-कला की मूर्तियाँ और संगीत की उपनिषदें, मुस्कुराते कमल-मुख और आश्चर्य की दृष्टि लिए रास-लीला में उपस्थित थीं। श्रेष्ठ नर्तकियों ने लोक, मिश्र और शुद्ध शैलियों में अपनी निपुणता प्रदर्शित की। उन्होंने संगीत के सभी रहस्यों और लालित्यपूर्ण चेष्टाओं में नैपुण्य दिखाया, जैसे कवि साधारण शब्दों को गीतों में बदल देता है। मार्ग (ब्रह्मा द्वारा स्थापित नियमों के संगीत) और देशी (क्षेत्रीय) दो प्रकार के गीत हैं। चच्चत्पुट से आरंभ होने वाले पाँच तालों सहित मार्ग-गीत चौंतीस प्रकार के हैं और देशी गीत चालीस प्रकार के।\nबोल का पाठ अत्यंत आकर्षक सुनाई दे रहा था: थैया थथैया थथा-थै थथैया! थै-थै-थै-थै-थै थथै-थै थथै था! थैया-थैया थथा-थथा थैया, थैया-थैया तिगदा थथैया। पाठ के बाद ताल-धारकों ने अपने हाथों में करताल लेकर उन्हें बाएँ, दाएँ, ऊपर, नीचे घुमाया और सप्तक के सात स्वरों के बावजूद एक आकर्षक नवीन अष्टम-स्वर गाया। उन्होंने बोल के साथ या बिना बोल के विभिन्न गति से वादन किया। वादकों द्वारा अपने हाथों से मृदंगों के किनारों पर प्रहार से उठी प्रबल ध्वनि से उनके होंठ और कंठ किसी अन्य वाद्य के समान काँपने लगे। महिला गायिकाएँ वाद्यों की ध्वनि की ओर कान लगाकर आकर्षक रूप से चमक रही थीं, क्योंकि वे उचित रागों को पूर्ण रूप से कंपित कर रहे थे।",
    728: "गोपियों ने उत्साह से बोल उच्चारित किए—'थै-थै थो-थो तिगड़ा-तिगड़ा थो, थथै-थो थथै-था।' उन्होंने भूमि पर पैर ठोंके, भुजाएँ आकाश में उठाईं और वृत्त की परिधि पर नृत्य करते हुए कलात्मक रूप से बाएँ से दाएँ घूमीं। गोपियों ने गीतों के शब्दों को चित्रित करने वाली हस्त-मुद्राएँ बनाकर अपने गायन के रस को बढ़ाया। उनके चरण ताल रखते थे और लालित्यपूर्ण घूमते गले स्वरों और तालों को व्यक्त करते थे। लय के अनुसार दाएँ-बाएँ घूमती चंचल दृष्टि से गोपियाँ कृष्ण की ओर प्रेमपूर्ण दृष्टि से देखती थीं। वे अपने सभी अंगों में समान उत्साह के साथ सब कुछ एक साथ करती थीं।\nगोपियों ने हाथ आकाश में फैलाए, चूड़ियाँ झंकृत कीं और सावधानी से पैर रखकर बिजली की गति से आनंद से घूमने लगीं। रास-वृत्त के केंद्र में खड़े कृष्ण से निकलती सौंदर्य-तरंगों की डोर पर पिरोई हुई सुंदर गोपियाँ बिना विश्राम के अपने चरण बाएँ-दाएँ चलाती रहीं। उन्होंने 'धी धी धी धी तधी धी' की ताल पर आनंद से पैर ठोंके, जबकि उनके शरीर लय में झूलते थे और रत्न-नूपुर झंकृत होते थे। आनंद में नृत्य करते हुए अपनी भुजाएँ घुमाने से उनका वक्षस्थल ढकनेवाला वस्त्र खिसक गया। वे सुंदर रूप से बाएँ-दाएँ घूमती थीं, बिना इस भय के कि उनकी कृश कटि दो टुकड़े हो जाएँगी।\nवीणा और वंशी-वादक सटीक कदमों से आनंद से नृत्य कर रहे थे। गायक और ताल-धारक गीत की ताल पर चलते थे। वादक जोर से बजाते और एक साथ नृत्य करते थे। ऐसा प्रतीत होता था मानो उनके शरीर धागे से नृत्य करती गोपियों के शरीरों से बँधे हुए हों।\nजब कृष्ण रास-वृत्त में चक्कर लगाते हुए बाएँ मुड़ते, तो गोपियाँ दाएँ मुड़तीं। और जब कृष्ण दाएँ मुड़ते, तो वे बाएँ। कृष्ण और गोपियों का भँवर-नृत्य अनंत था, जिसमें वे एक ही दिशा में या विपरीत दिशा में चलते थे। कृष्ण और नृत्य करती गोपियाँ घूमते दीपक द्वारा प्रकाशित आकृतियों के समान प्रतीत होती थीं, जिनकी छाया पहले एक ओर और फिर दूसरी ओर पड़ती थी, क्योंकि नील वर्ण कृष्ण और स्वर्ण-अंग गोपियों का संयोजन बार-बार अपनी स्थिति बदलता था।\nवृत्त के बाहर स्थित वादक गोपियों की गति के साथ समय रखकर भगवान की लीला में सहायता करते थे। किसी प्रकार गीत मोड़ लेते थे। गोपियाँ कृष्णचंद्र नामक चंद्रमा के बारे में गाती थीं, जो सभी आनंद की मूर्ति है। उत्तर में कृष्ण उस सुंदर चंद्रमा की महिमा करते थे, जो रात्रि को सुखद किरणों से भर देता है।\nजैसे-जैसे लय बढ़ती और गोपियाँ अपने चरण अधिक जोर से ठोंकती, उनके कमल-चरणों से स्वेद की बूँदें रेत पर टपकते मधु के समान गिरतीं। आश्चर्य की बात है कि नृत्य के प्रचंड वेग से रेत का एक भी कण नहीं उड़ा। क्या रेत के सभी कण आनंद से स्तब्ध हो गए थे? गोपियों के तिलकों पर प्रतिबिंबित कृष्ण की नृत्य-मूर्ति, सिर आगे-पीछे हिलाती गोपियों की लय पर झूलती थी। गोपियाँ कृष्ण के प्रतिबिंब को संबोधित करती प्रतीत होती थीं—'हे कुशल नर्तक! आपका नृत्य कभी भी रास-मण्डल में गोपियों के शानदार नृत्य की बराबरी नहीं कर सकता!'\nकुछ कमल-नयनी गोपियाँ, कृष्ण के आलिंगन के आनंद से पुलकित, नृत्य करती हुईं अपनी तीव्र लालसा व्यक्त करने के लिए एक विशेष राग जोर से गा रही थीं। उस राग को सुनकर संगीत के सभी देवता मूर्च्छित हो गए। एक गोपी ने मधुर गांधार ग्राम में, उचित जाति, श्रुति और गमकों सहित, पूर्ण भावना के साथ शुद्ध मधुर स्वर गाए। कृष्ण ने उसकी प्रशंसा में 'शाबाश, शाबाश' पुकारा। उसने कृष्ण को और प्रसन्न किया, बाईस श्रुतियों से अलंकृत सप्तक के सातों स्वरों को मुख्य अलंकारों सहित आलाप में प्रस्तुत करके।\nमृदंग लगातार 'ता धिक ता धिक-धिक' (अर्थ: स्वर्गीय नर्तकियाँ व्यर्थ हैं!) की ताल बजाते रहे। यह सुनकर स्वर्ग के नर्तक हर्ष से मुस्कुराए। यद्यपि प्रतिस्पर्धा की आलोचना करने वाले स्वर्गीय कलाकार, इस उलाहना को सुनकर आनंद से भर गए। अपनी चमकदार श्याम अलकों पर मोरपंख धारण किए मुकुंद ने राधा का आलिंगन करके रास-नृत्य पर प्रेम-अमृत की मूसलाधार वर्षा की। श्रीमती राधिका कला की देवी द्वारा उत्पन्न सिद्ध औषधि के समान प्रतीत होती थीं, जो पूर्ण संतोष देती और सब शोक हर लेती है। जब श्याम राधा के साथ आनंद से नृत्य करते थे, तो वे स्वर्ण-लता से आलिंगित तमाल-वृक्ष या बिजली चमकते मेघ के समान दिखते थे।\nकृष्ण के अद्वितीय सुंदर शरीर ने करोड़ों कामदेवों के गर्व को जीत लिया। राधिका के साथ नृत्य करते समय श्याम ने चुंबक की भाँति कामदेव के प्रेम-बाणों की लौह-नोकों को अपनी ओर खींच लिया। राधा कृष्ण की लय में चल रही थीं। गोपियाँ राधा के कुशल नृत्य को बढ़ाना चाहती थीं, परंतु गायन, नृत्य और वादन में राधा की निपुणता की बराबरी नहीं कर सकीं।\nराधा-माधव, आकर्षण, आनंद, उत्साह और एक-दूसरे से आगे बढ़ने की इच्छा से विह्वल, ग्रह-स्वर और षड्ज के प्रकारों के साथ आलाप गाते थे। राधा-माधव गमकों (कंपन) के साथ आरोह-अवरोह के सभी स्वर गाते थे। इससे विभिन्न रस उत्पन्न होते, अधिक गायन-नृत्य की प्रेरणा मिलती और चारों ओर मंगल फैलता। यह किसी भौतिक कला का प्रकाशन नहीं था।\nगीत के अंत से ठीक पहले लय धीमी होते ही कृष्ण ने उसे अंतिम स्वर (न्यास) से समाप्त किया, अपना कमल-हस्त (न्यास) बढ़ाकर राधिका के वक्षस्थल का स्पर्श किया। यद्यपि कृष्ण के चतुर व्यवहार से राधा उत्सुक हुईं, तथापि उन्होंने क्रोध का नाटक करते हुए अपने बाएँ कमल-हस्त से कृष्ण का हाथ हटा दिया।",
    729: "एक गोपी कृष्ण के सम्मुख नृत्य करती थी, जबकि दूसरी गोपी धीरे-धीरे आगे बढ़कर उसके साथ जुड़ गई। उसी प्रकार तीसरी, फिर चौथी गोपी जुड़ीं और शीघ्र ही कई गोपियाँ एक-दूसरे से जुड़ गईं। कृष्ण गोपियों की गोलाकार पंक्ति के बाहरी छोर पर आश्चर्य से देखते रहे।\nएक गोपी ने एक-एक करके बहुत से नृत्य-भाव प्रस्तुत किए। उसने कमल-नाल की मुद्रा में हाथ घुमाकर कमल की मुद्रा बनाई। इसी प्रकार उसने कमल-भ्रमर मुद्रा में तेजी से हाथ घुमाए। फिर उसने कमल-दर्पण मुद्रा, कमल-लिप्सा मुद्रा और अंत में कमल-प्रदर्शन मुद्रा में कमलों को निहारा। एक क्षण में ही उसने सभी मुद्राओं को संयोजित करते हुए दिखाया।\nउस सुंदर गोपी ने अपने कमल-हस्तों की मुद्राओं से पाँच प्रकार के कमलों के रंग, आकार, पंखुड़ियों की मुद्राएँ, परिभ्रमण और कटि-वलन प्रदर्शित किए। श्याम इन सब को मंत्रमुग्ध होकर देखते रहे। श्याम की ही प्रेरणा से गोपी इतनी निपुणता से नृत्य कर रही थी। इसके साथ ही वह आकर्षक श्लोक भी गा रही थी—'हे कमल-नेत्र! मैं शतपत्र (श्वेत कमल) के साथ क्रीड़ा करती हूँ।' जब गोपी ने नृत्य में अपने चरण उठाए, तो वे श्वेत-कमल के समान दिखे। उसके पैरों के नीचे का पराग श्वेत-कमल के अंतराल जैसा दिखा, और उसकी बायीं भुजा कमल के ऊपर शोभा पाती हुई बाँसुरी के समान दिखी। श्याम उस श्लोक की भावना को चित्रित करने वाले हाव-भाव देखकर हँसे।\nजब कृष्ण ने उस गोपी के मधुर गायन और नृत्य का आनंद लिया, तो दूसरी गोपी ने कृष्ण के सम्मुख प्रस्तुति दी। गोपी ने कमल-भौंरा, भौंरा-उड़ान (भौंरों का छिटकना) की मुद्राएँ बनाईं। फिर उसने भौंरे के घूमने और भौंरे के चुंबन की मुद्राएँ प्रस्तुत कीं। उसने गंध, रंग और कमलों की सुंदरता की मुद्राएँ भी दिखाईं। तदनंतर उसने हरि के लिए सुंदर गीत गाया—'ओ भौंरे, हमारा मन तेरे साथ खेलता है!' कृष्ण ने मुस्कुराकर उस नृत्य की प्रशंसा की।\nतीसरी गोपी ने श्याम के सम्मुख प्रस्तुति दी। उसने नृत्य में अपनी कमर झुकाई, सिर पीछे झुकाया, हाथों की मुद्राएँ बनाईं और अपने वक्षों को कसकर केंद्र में लाया। उसने कमर हिलाई, अपने मुख की कटाक्ष-दृष्टि से कृष्ण को अपनी मुद्राओं के भाव समझाए। उसने अपनी दृष्टि के साथ-साथ भाव-भंगिमाएँ प्रस्तुत कीं और एक गीत गाया।\nएक गोपी ने तमाल-वृक्ष की छाया में नृत्य किया, जहाँ पवन मीठे पराग से सुगंधित था। सफेद कमल का एक सुंदर हार, जिसकी डोरी नीलमणि के मोतियों से बनी थी, गोपी के गले से लटक रहा था। उसका स्वर्ण-वर्णी पहनावा झूलता था और उसके कानों में पुष्प-कुण्डल थे। कृष्ण उसके स्वर्ण-शरीर पर मकर-चिह्न देखकर मोहित हुए और उससे बोले—'यह देखो! तुम्हारी बाहें मेरे कंधों पर रखो।' कृष्ण के शब्दों का अर्थ था कि उसने अपने कमल-हाथ उनके कंधों पर रखकर नृत्य किया, जैसे प्रकाश-कंठी मयूर नृत्य करते हैं। गोपी ने उसी प्रकार किया।\nश्याम ने प्रेम-पुलकित होकर गोपी से एक सुंदर प्रश्न पूछा—'हे सुंदरी! क्या तुम व्रज में रहती हो? तुम्हारे घर पर वृक्ष, गाय और व्रज की मिट्टी हैं।' तब श्याम, उस गोपी को रास-वृत्त से बाहर ले जाकर उसकी ओर मुख करके खड़े हुए, और उसे उठाकर धीरे से प्यार से नृत्य करने लगे।",
    731: "वायु से स्पर्श किए तमाल-वृक्ष की शाखाओं पर लटकती स्वर्ण-लताओं के समान गोपियाँ सुंदर दिख रही थीं। थकी हुई गोपियों से आलिंगित कृष्ण, आनंद-मूर्तियों द्वारा आलिंगित संयोग-रस की संघनित मूर्ति प्रतीत हो रहे थे। एक गोपी, जिसके हार झूल रहे थे, कानों में कमल-कलिका-कुण्डल और पहनावा सुंदर था, ने अपनी बाईं भुजा कृष्ण के कंधे पर रखी। उसकी कटि-मेखला और नूपुर झंकृत हो रहे थे, और वह धीमे, कलात्मक ढंग से गाती और नृत्य करती थी। कृष्ण उसकी चाल का अनुसरण करते हुए नृत्य और गान कर रहे थे।\nएक प्रेम-उद्दीप्त कमल-नयनी गोपी ने कृष्ण की स्वर्ण-धोती का छोर अपने कमल-हाथ से पकड़ा और उसे तथा कृष्ण को खींचती हुई आगे-पीछे नृत्य करने लगी।",
    738: "कोमल लता-समान भुजाओं वाली मृग-नयनी कन्याएँ कृष्ण के प्रत्यक्ष सेवा के आनंद से प्लावित होकर उनके प्रति इच्छा-रूपी नदी में तैर रही थीं। गोपियों के उल्लास में उनकी अलकें, चोली और वस्त्र अनजाने में शिथिल हो गए थे।",
    773: "जब कृष्ण ने राधा के वक्षस्थल को स्पर्श करना चाहा, तो उन्होंने अपनी भुजाएँ सामने क्रॉस कर लीं। जब कृष्ण ने उनकी ओर कमल-नाल फेंका, तो राधा ने उसे टालने के लिए अपनी भुजाएँ उठा लीं। जब श्याम ने उनके मधुर कमल-मुख को सूँघना चाहा, तो किशोरी ने अपने हाथों से मुख ढक लिया। राधा-माधव की अंतरंग सखियों ने उनकी अद्भुत प्रेम-लीलाओं का पूर्ण रस लिया।",
    775: "एक सहानुभूतिपूर्ण सखी ने एक दुखी सखी से कहा—'तुम उत्साह से जल में खेल रही हो। परंतु तुम्हें कमल तोड़ना बंद कर देना चाहिए। क्या तुम नहीं देख रही हो कि कमल के नालों के काँटों से तुम्हारे कोमल अंग आहत हो गए हैं और कुछ मदमाते भौंरों ने तुम्हारे होठों को काट लिया है?'",
}


